pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0; // tiny sliver: worst outcome
    } else if post_residual < min_useful {
        // perfect fit (post_residual == 0)
        score -= 40.0;
    }

    // Non-linear penalty on wasted fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Reward using bins that would otherwise leave a hard-to-fill residual
    // similar to the current item (good chaining with lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // gap can host the next item: attractive
        } else if post_residual > 0 {
            score += 8.0;  // gap smaller than next item: dead space risk
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it mildly unattractive by default,
    // but attractive when open bins are very full on average.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = bin_capacity as f64 - 15.0 - 10.0 * pressure;
        if next_item_size > 0 && next_item_size >= min_useful && next_item_size <= bin_capacity {
            score += 5.0; // a fresh bin always fits the next item
        }
    }

    // Mild pressure from number of open bins: prefer consolidating
    // into existing bins as the fleet grows.
    score += 0.5 * open_bins_count as f64 * waste_frac;

    // Late-stream tightening: as the stream progresses, dead space matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize residuals that cannot fit even the smallest future item,
    // scaled by how "wasted" the gap is relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Open-bin pressure: discourage spreading across many bins,
    // but allow new bins when current bin would leave a bad gap.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // New-bin candidate: neutral baseline with mild penalty so it is
    // chosen only when all open bins score badly.
    if bin_residual == bin_capacity {
        score = 30.0 + (open_bins_count as f64) * 0.3;
        // Late in the stream, opening new bins is cheaper than dead space.
        if step_index as f64 / total_items.max(1) as f64 > 0.7 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize leaving dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 25.0; // perfect lookahead match
        } else {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins slightly; penalize bins far below mean residual (fragmentation).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        let poor_fit = if fitting_bins_count > 0 {
            (post_residual as f64 / bin_capacity as f64).max(0.0)
        } else {
            0.0
        };
        // Opening new bin costs; make it worse than a decent existing fit.
        score += 45.0 + 5.0 * pressure - 60.0 * poor_fit;
        // Late in stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress * poor_fit;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 15.0 * (1.0 - fit_ratio.min(1.0));

    // Last chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> discourage spreading; few -> encourage filling.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 2.0;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits, mild penalty for blocking it.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 6.0;
    }

    // New bin candidate: neutral baseline with slight early-stream openness.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: small post residual relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 / (1.0 + tightness);

    // Dead space penalty: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize wasting large residuals on small items
        score += 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer fuller bins among many open bins (best-fit bias)
    score -= 0.2 * (bin_capacity - bin_residual) as f64 / open_bins_count.max(1) as f64;

    // Global pressure: if mean residual is low, conserve open capacity
    if mean_residual < item_size as f64 {
        score += 15.0;
    }

    // New-bin candidate logic: only attractive early in stream or when open bins are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64; // = capacity - item_size
        let desperation = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        // favor new bin when existing fits are bad and item is large
        let badness = (post_residual as f64).min(50.0);
        score = fit_quality + desperation - 40.0 * (1.0 - progress) - (item_size as f64 * 0.3) + badness * 0.1;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 50.0;
        }
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when a unique fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands on a
    // "small dead space" class are penalized, "usable" classes rewarded.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward when the next item fits exactly into the post-residual (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it nests.
            score -= 150.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use this leftover: penalize dead space,
            // worse when leftover is in a "useless" harmonic band.
            let dead = post_residual as f64;
            if post_residual < eighth {
                score += 60.0; // tiny sliver, unusable
            } else if post_residual > quarter * 3 {
                score -= 40.0; // still roomy, fine
            } else {
                score += 25.0 * (dead / cap);
            }
        }
    }

    // Modulo-class logic on post_residual: residuals congruent to small
    // multiples of a base granularity (e.g. 10) are more reusable.
    let base = 10u32;
    let cls = post_residual % (base * 5); // class in 0..50
    if cls == 0 {
        score -= 30.0; // clean multiple of 50: highly reusable
    } else if cls < base {
        score -= 10.0; // near-clean class
    } else if cls > base * 4 {
        score += 8.0;  // ragged class
    }

    // Integer-division thresholds: residual usable by typical item sizes.
    let fits_mid = post_residual / 20; // how many "medium" 20-slots remain
    score -= 20.0 * fits_mid as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: prefer it only when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base preference for fresh bins slightly worse than a decent fit.
        score -= 50.0;
        // But if many bins are open and mean residual is small, opening fresh
        // is attractive for future large items.
        score -= 30.0 * (mean_residual / cap).min(1.0);
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 40.0; // next big item: fresh bin valuable
        }
    } else {
        // Penalty for spreading across too many open bins.
        score += 2.0 * open_bins_count as f64;
    }

    // Stream progression: early on, keep bins tight; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * progress * (post_residual as f64 / cap);

    // Prefer bins below mean residual (tighter bins) mildly.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

