pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can still host the next item (chained placement), penalize dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits after this placement: reward proportionally
            // to how tightly the pair packs the bin.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * (bin_capacity as f64 - pair_waste);
        } else {
            // Next item won't fit here: penalize, worse if the leftover is
            // a small unusable sliver.
            let sliver = post_residual as f64;
            let sliver_penalty = if sliver < 10.0 {
                25.0 + (10.0 - sliver) * 2.0
            } else {
                sliver * 0.15
            };
            score += sliver_penalty;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Coupling with mean residual: prefer bins tighter than the average
    // (best-fit style), but not when it creates a tiny dead zone.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it attractive only when no open bin offers
    // a good chained fit. Bias it so it's chosen for large items that
    // would otherwise leave big residuals elsewhere unusable.
    if bin_residual == bin_capacity {
        // Neutral-ish base: full residual; discount when item is large
        // (large items are better placed in a fresh bin) or when current
        // open bins are crowded (high mean residual).
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 25.0;
        let crowded_bonus = if open_bins_count > 0 { mean_residual / bin_capacity as f64 * 15.0 } else { 15.0 };
        score -= large_item_bonus + crowded_bonus;
        // Penalize opening a new bin for tiny items early in the stream.
        if item_size < 30 && (step_index as f64) / (total_items.max(1) as f64) < 0.5 {
            score += 20.0;
        }
    }

    // Mild preference for filling bins more completely overall.
    score -= 0.1 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits mildly; Late: strongly punish residual waste.
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;
    let w = 1.0 + 2.5 * progress * progress;
    score += w * (pr2 * 30.0 + pr3 * 60.0) * cap * 0.1;

    // Exact-ish fit reward (smooth, no piecewise): small post_residual gets big discount.
    score -= 40.0 * (1.0 - pr).powi(6);

    // Penalize bins whose residual is far from the item (bad coupling).
    let br = bin_residual as f64;
    score += 0.15 * (br - item_size as f64).abs();

    // Lookahead: if next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            score -= 12.0 * (1.0 - (post_residual as f64 - nx) / cap);
        } else {
            score += 8.0 + 10.0 * progress;
        }
    }

    // Last-chance bin: strong discount to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Mean residual context: bins below mean residual are more precious.
    score += 0.1 * (mean_residual - br);

    // New-bin candidate: neutral-ish baseline, made less attractive when decent fits exist.
    if bin_residual == bin_capacity {
        score = cap as f64 * 0.5 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= cap * 0.5 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to fit even the smallest
    // plausible future item. Penalize non-zero small gaps super-linearly.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 6.0;
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post gap,
    // reward this placement; if the gap is just barely too small, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 4 {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize opening new bins implicitly via residual bias).
    let ob = open_bins_count as f64;
    score += ob * 0.35;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose post residual stays near the
    // open-bin mean (predictable packing), penalize outliers creating scraps.
    let mr = mean_residual;
    let dev = (post_residual as f64 - mr).abs();
    score += dev * 0.15;

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when existing fits are bad (large post residual or dead gap).
    if bin_residual == bin_capacity {
