        }
        // If next item is large, a fresh bin keeps flexibility.
        if next_item_size >= 60 {
            score -= 8.0;
        }
        // Late in the stream, avoid spreading out.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 5.0;
    }

    // Slight stream-progress term: tighten packing as stream advances.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

