    }

    // Last-chance bin: only one open bin fits this item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if best existing option is bad.
    if bin_residual == bin_capacity {
        // fresh bin baseline: its post_residual == capacity - item_size, already in score.
        // Penalize opening new bins when many bins are open but poorly filled decisions are cheap;
        // reward fresh bin when open bins are congested (few fit).
        if fitting_bins_count == 0 {
