            7 => score += 0.0,               // 70..79
            8 => score += 6.0,               // 80..89
            _ => score += 14.0,              // 90+ : mostly empty, wasteful fill
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Modulo coupling: reward when post_residual is congruent to common small item sizes,
    // making it likely the lookahead item fits exactly later.
    let common = [10u32, 20, 25, 30, 40, 50];
    for c in common.iter() {
        if post_residual >= *c && post_residual % c == 0 {
            score -= 8.0;
            break;
        }
    }

    // Lookahead harmony: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 45.0;
        } else {
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            score -= 10.0 * next_frac;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: mild penalty proportional to waste.
        score += 5.0 * (1.0 - frac);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: prefer keeping bins tight; late: prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * (1.0 - progress) * (1.0 - frac);

    // Prefer filling bins with small residuals relative to the fleet mean.
    score += (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate: penalize opening a new bin unless current bin is unusable.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual below the minimum item size (1) is impossible, but gaps
    // below a "dead zone" threshold are nearly worthless.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward very tight fits (post_residual near zero) superlinearly.
    score -= (item_size as f64 / bin_capacity as f64).powf(3.0) * 25.0;

    // Penalize leaving a gap that the next item cannot use (lookahead dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward leaving exactly the gap the next item needs.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Align with mean residual: bins with residuals far below the mean are
    // already tight; prefer placing into bins above the mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded (mean residual small) or the item is large.
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / bin_capacity as f64).max(0.0);
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - crowded) * (1.0 - large_item);
        // In the early stream, opening bins is cheap; later, discourage it.
        score += (step_index as f64 / total_items.max(1) as f64) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to relax conservatism over time.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect packing strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Perfect fit gets an extra large reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item,
    // penalize leftovers that strand the next item into a new bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover reusable by next item: mild reward, scaled by how snugly it fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * snug;
        } else {
            // leftover too small for next item: dead space penalty, worse if very small
            let waste = post_residual as f64 / next_item_size as f64;
            score += 15.0 * (1.0 - waste.min(1.0));
        }
    } else {
        // Last item: any fit is fine, strongly prefer filling existing bins.
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, favor it
    // heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Global state coupling: penalize placements into bins far from the mean
    // residual when many bins are open (encourages balanced, closeable bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev * (open_bins_count as f64).sqrt();

    // Time horizon: early on, be more selective (penalize mediocre fits);
    // late in the stream, prioritize closing bins out (any fit is good).
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * progress * tightness;

    // New-bin candidate: penalize opening a new bin, but less when current
    // open bins are crowded (many bins, low mean residual) or item is large
    // relative to typical leftover space.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 55.0;
        // If no open bin fits well (post_residual large everywhere), allow new bin.
        if post_residual as f64 > mean_residual.max(1.0) * 0.5 {
            new_bin_penalty -= 20.0;
        }
        // Fewer open bins => cheaper to open one.
        new_bin_penalty -= 3.0 * (open_bins_count as f64).min(10.0);
        // Large items are harder to place later; be more willing to open space.
        new_bin_penalty -= 0.2 * item_size as f64;
        score += new_bin_penalty.max(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress * (1.0 - progress);
    score += 4.0 * poly * cap;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * (item_size as f64);

    // Penalize dead space relative to mean residual across open bins
    score += (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 50.0 * progress;
    }

    // Lookahead: penalize leaving residual that neither fits nor is close to next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += (nx - pr) * (0.5 + 0.5 * progress);
        }
    }

    // Mildly discourage proliferating open bins early
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse buckets (dead space vs. reusable space) via integer division.
    let class = post_residual / 10; // 0..=10 harmonic class of leftover

    // Dead-space penalty: residuals < 10 are unusable for any item (sizes >= 1
    // but small residuals rarely reusable). Penalize quadratically per class.
    score += (class as f64).powi(2) * 0.5;

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact two-item harmony: post_residual == next_item_size is ideal.
            let harmony = (post_residual as i64 - next_item_size as i64).abs();
            score -= 120.0 - harmony as f64 * 3.0;
        } else {
            // Leftover too small for next item: mild penalty scaled by waste.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // unattractive unless no open bin offers a decent fit. Penalize the fresh
    // bin by how many bins already fit the item, plus a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 90.0 + 25.0 * fitting_bins_count as f64;
        // Late in the stream, opening bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * progress;
    }

    // Prefer tighter bins overall: compare residual to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.6;

    // Modulo bonus: leftover divisible nicely (multiples of 10) recombines
    // well with common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; anything below a "usable" threshold (<= 15) gets a heavy penalty.
    let usable_threshold: u32 = 15;
    if post_residual > 0 && post_residual < usable_threshold {
        score += (usable_threshold - post_residual) as f64 * 3.0;
    }

    // Perfect fit is the ideal outcome: reward it strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Reward bins whose residual was already small (tight packing).
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Open-bin pressure: discourage spreading items across many bins;
    // penalize placements that keep many bins open with mediocre residuals.
    score += open_bins_count as f64 * 1.5;

    // If this bin is the ONLY bin that can fit the item, strongly prefer it
    // (last chance before opening a new bin).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with below-average residual (they are closer to being closed out).
    let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
    if (post_residual as f64) < avg {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Lookahead: if the next item would exactly fit the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space the next item cannot use: mild penalty.
        score += 2.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Slight default penalty so existing tight fits win; but if open bins
        // are numerous with large residuals, opening fresh is fine.
        score += 8.0;
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 6.0; // big item coming, fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: strongly reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            // reward small two-step leftover, scaled by how tight it is
            score -= 30.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            // bonus if the two-step chain leaves near-zero waste
            if next_post <= 5 {
                score -= 20.0;
            }
        } else {
            // next item can't follow into this bin: penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer space,
    // placing here is good if fit is tight; bins far above mean waste capacity.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin offers
    // a decent fit. Penalize opening a new bin, more so later in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 40.0 + 20.0 * progress;
        // if next item is large, a fresh bin is more attractive (keeps flexibility)
        if next_item_size >= 60 {
            open_penalty -= 15.0;
        }
        // many open bins with small mean residual -> keep consolidating instead
        if open_bins_count > 2 && mean_residual < 40.0 {
            open_penalty += 10.0;
        }
        score += open_penalty;
    }

    // Mild late-stream pressure to close bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills aggressively.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 30.0 * fill_ratio;
    } else if fill_ratio > 0.5 {
        score -= 8.0 * fill_ratio;
    }

    // Penalize leaving awkward small residuals that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space trap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: default discouraged, but acceptable when residuals
    // across open bins are large and fragmented or item is big.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / (bin_capacity as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when existing residuals are high (fragmented) and
        // the item is large, or late in the stream when closing bins is cheap.
        let new_bin_bonus = 60.0 * fragmentation * big_item + 20.0 * progress;
        score += 45.0 - new_bin_bonus;
    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // reward keeping this residual; if next item can't fit anyway, less pressure.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect chain
        } else if next_item_size <= post_residual && next_item_size >= post_residual.saturating_sub(10) {
            score -= 15.0; // likely usable residual
        } else if next_item_size > post_residual {
            score += 5.0; // residual may become dead space
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer low post-residual, with non-linear (quadratic) waste pressure.
    let mut score = post + (post * post) / cap;

    // Smooth stream-progress coupling: as stream advances, tighten tolerance
    // quadratically (late items should pack tighter into existing bins).
    let tightness = 1.0 + 2.0 * progress * progress;
    score *= tightness;

    // Reward filling bins deeply (high fill fraction) with a smooth saturating term.
    let fill = (bin_residual as f64) / cap;
    score -= (fill * fill * fill) * 12.0;

    // Lookahead: bonus if next item fits the post-residual (smooth compatibility term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            // Penalize leaving residual that is just barely too small for next item.
            score += (gap.abs() / cap) * 4.0;
        }
    }

    // Scarcity pressure: if this is the only fitting bin, strongly favor using it
    // (smooth exponential urgency rather than a hard piecewise rule).
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty when bin residual deviates far above the mean residual
    // (encourages balancing residual space across open bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 5.0;

    // New-bin candidate: smooth penalty scaled by how many bins are already open
    // and how much of the stream remains, so new bins are opened reluctantly.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress) + (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: residuals in the same
    // "decade" (capacity / 10 bands) are interchangeable capacity-wise.
    let band = post_residual / 10; // integer division threshold
    score -= band as f64 * 2.0;    // prefer bins leaving residuals in higher bands (more reusable)

    // Exact / near-exact fit is gold: reward heavily.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // Modulo arithmetic: residual compatible with common item classes
    // (items 1..100; small residuals that match typical item sizes are valuable).
    let next = next_item_size as f64;
    if next > 0.0 {
        // Can the next item exactly fill this bin's post residual?
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // leftover after the lookahead lands here
            let chain = post_residual - next_item_size;
            score -= (20.0 - chain.min(20) as f64) * 0.5;
        } else {
            // next item cannot use this residual: penalize by how "dead" it is
            let dead = (post_residual as f64) / cap;
            score += dead * 25.0;
        }
        // Harmonic residue classes: residuals divisible by common item
        // granularities (5, 10, 20) are easier to pack later.
        if post_residual % 5 == 0 { score -= 4.0; }
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits well
        // (many fitting bins means an existing bin is preferred).
        let fit_pressure = fitting_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty keeps new bins secondary, softened late in stream
        // and when the only alternative leaves large dead space.
        score += 30.0 + fit_pressure * 6.0 - progress * 10.0;
        // If the new bin would hold the item with a "harmonic" leftover
        // (multiple of 10), it's a decent long-term bet.
        if (bin_capacity - item_size) % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, avoid wasting it
    // on a sloppy placement unless the fit is tight.
    if fitting_bins_count == 1 && post_residual > 10 {
        score += 12.0;
    }

    // Prefer bins already below mean residual (tighter bins get tighter).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..100
    // interface, but treat gaps below a small threshold as near-wasted) are
    // heavily penalized, super-linearly as they shrink.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        let waste = (dead_threshold - post_residual) as f64;
        score += 25.0 + 8.0 * waste;
    }

    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: post_residual small relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += 3.0 * tightness;
    }

    // Lookahead: if the next item fits exactly into the post-residual gap,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use this gap: if gap is small, it's dead space.
            if post_residual < dead_threshold {
                score += 15.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: penalize placing into bins when many bins are open,
    // pushing consolidation unless the fit is tight.
    score += 0.35 * open_bins_count as f64;

    // Mean-residual coupling: bins far below mean residual are less attractive
    // (keeps large-residual bins available for future large items).
    score += 0.10 * (mean_residual - post_residual as f64);

    // New-bin candidate: prefer keeping it closed unless all open fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only opened on genuinely good terms.
        score += 40.0;
        // If many bins are already open, opening yet another is extra costly.
        score += 0.5 * open_bins_count as f64;
        // But if the current item is large, a fresh bin gives full flexibility.
        if item_size >= 60 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();

        // Perfect chain: post_residual == next_item_size -> strong reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if post >= nxt {
            // Next item fits in this bin's leftover: reward proportionally
            // to how tight the match is.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize.
            score += 25.0 * (1.0 - post / nxt.max(1.0) as f64).abs();
        }

        // Extra bonus if next item would also fit (post >= next size)
        // AND this bin was tight before placement (efficient packing).
        if post >= nxt && bin_residual <= 2 * item_size {
            score -= 15.0;
        }
    }

    // Penalize post_residual that is small but unusable relative to
    // typical item sizes (dead space below the minimum plausible size).
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.25 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Reward packing into bins that are already below-average residual
    // (i.e., nearly full bins) to consolidate open bins.
    score -= 8.0 * (1.0 - (bin_residual as f64) / (mean_residual.max(1.0)));

    // Late in the stream, prefer tightening existing bins over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for proliferating open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize very small post-residuals that become dead space (< 10, min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a gap that the next item cannot use.
            score += 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to keep options open.
        score += 3.0;
    }

    // Global state: prefer filling bins when many bins are open.
    let open_frac = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 2.0 * open_frac * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean, it is a
    // good "filler" target; if far above, deprioritize slightly.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;
    if progress > 0.8 {
        score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit (i.e., this call itself has a poor fit ratio).
    if bin_residual == bin_capacity {
        let base = 18.0;
        let poor_fit_bonus = if fit_ratio < 0.4 { 0.0 } else { 60.0 };
        let early_bonus = if progress < 0.25 { 10.0 } else { 0.0 };
        score += base + poor_fit_bonus + early_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Normalized post-residual in [0,1]
    let r = post / cap;

    // Base: reward small post-residual (tight fit), non-linearly
    let mut score = post;

    // Smooth polynomial coupling: mid-range residuals are penalized more
    // as the stream progresses (dead space becomes costlier later).
    let dead_penalty = 4.0 * r * (1.0 - r) * (0.5 + progress);
    score += dead_penalty * cap * 0.25;

    // Strong reward for near-perfect fits (r near 0), smoothed
    score -= (1.0 - r).powi(6) * cap * 0.6;

    // Lookahead coupling: if next item fits into post-residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let snug = 1.0 - ((post - nxt) / cap);
            score -= snug * snug * 12.0;
        } else {
            // next item won't fit: mild penalty scaled by wasted potential
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count <= 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Slight preference for filling bins when many bins are open (bin consolidation)
    score -= (open_bins_count as f64).ln() * (1.0 - r) * 2.0;

    // Bias toward bins with residuals below mean (compact the low-residual bins)
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual < 10 (nearly full) -> strong reward.
    // Class 2: post_residual divisible by small harmonics (10/20/25/50) -> moderate reward.
    // Class 3: awkward residue in (0,10) exclusive of 0 handled above; penalize mid-range waste.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    } else {
        // modular harmonic classes on post_residual
        let harmonic_bonus: f64 = if post_residual % 50 == 0 {
            120.0
        } else if post_residual % 25 == 0 {
            90.0
        } else if post_residual % 20 == 0 {
            70.0
        } else if post_residual % 10 == 0 {
            50.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // penalize unusable slivers relative to smallest possible future item (1..100 range, min 1)
        // but with unknown distribution assume typical min item ~10: residue < 10 is dead space
        if post_residual < 10 {
            score += 150.0; // dead space penalty (cannot host even a small item under classic assumption)
        }
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // chain fit: perfect follow-up
        } else if next_item_size < post_residual {
            // harmonic match classes between next item and residual
            let diff = post_residual - next_item_size;
            if diff < 10 {
                score -= 150.0;
            } else if diff % 10 == 0 {
                score -= 60.0;
            }
            // scale reward by how much of residual next item consumes
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * frac;
        } else {
            // next item cannot use this residual: mild penalty proportional to wasted opportunity
            score += 30.0;
        }
    }

    // Last-chance bin: only one open bin fits this item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if best existing option is bad.
    if bin_residual == bin_capacity {
        // fresh bin baseline: its post_residual == capacity - item_size, already in score.
        // Penalize opening new bins when many bins are open but poorly filled decisions are cheap;
        // reward fresh bin when open bins are congested (few fit).
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open
        } else if fitting_bins_count <= 2 {
            score -= 40.0 * (2.0 - fitting_bins_count as f64);
        } else {
            score += 60.0 + 10.0 * (fitting_bins_count as f64).min(10.0);
        }
        // early stream: opening bins is fine since plenty of stream remains
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 100.0 * (1.0 - progress);
    }

    // Mild tie-break: prefer bins whose residual deviates from the mean in a useful way
    // (filling below-average-residual bins consolidates waste).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 40.0 * dev;

    // Slight preference to use existing bins over opening new ones overall.
    if bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone_max: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone_max {
        score += (dead_zone_max - post_residual as f64) * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills a large fraction of the bin's residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Penalize bins whose residual is much larger than needed (wasteful use of big space).
    if (post_residual as f64) > (item_size as f64) {
        score += (post_residual as f64 - item_size as f64) * 0.35;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits, small penalty for blocking it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins, but ease up near stream end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).powf(1.2) * (0.6 - 0.4 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good fit exists; penalize default opening otherwise.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 55.0 * large_item;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild alignment with mean residual: prefer bins that keep residual distribution balanced.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too: mild reward proportional to leftover after both.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item does not fit: penalize dead space relative to next item.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize very small unusable post_residual (dead space), unless it's an exact-ish fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize bins far below mean residual only mildly; prefer tighter-than-average bins.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Early in stream: slight preference to fill existing bins densely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    // New-bin candidate: make it costly unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual non-linearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            // Dead space that the next item cannot use is penalized,
            // especially when it is small (unusable sliver).
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - waste);
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to keep options open.
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Global state coupling: prefer filling bins when mean residual is high
    // (fragmentation risk), prefer new bins when open bins are nearly full.
    let frag = if mean_residual > 0.0 { post_residual as f64 / mean_residual } else { 1.0 };
    score += 2.0 * (frag - 1.0).clamp(-2.0, 3.0);

    // Time horizon: late in the stream, consolidate aggressively;
    // early, allow opening bins more freely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 10.0 + 25.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Prefer bins that are already heavily loaded (low residual) slightly,
    // to drive bins toward closure.
    score += 0.05 * bin_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 20.0
        - norm_pr * progress * 10.0;
    score += coupling;
    // Reward tight fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * 0.05;
    // Penalize near-empty residual waste
    if post_residual > 0 {
        score += (cap / pr).ln() * 2.0;
    }
    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }
    // New-bin candidate: mildly discouraged early, allowed late
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) - 10.0 * progress;
    }
    // Lookahead: favor bins whose post residual fits next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    // Smooth dispersion penalty vs mean residual
    score += ((pr - mean_residual) / cap).powi(2) * 10.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (low post_residual).
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes
    // modulo common item sizes (1..100 unknown distribution -> use several moduli).
    let pr = post_residual;
    // Dead-space penalty grows superlinearly for leftovers that no typical item
    // (size <= 80) can split nicely into. Penalize leftovers in "awkward" classes.
    let class_penalty = if pr == 0 {
        -30.0 // perfect fit, strongly reward
    } else if pr < 10 {
        12.0 // tiny unusable sliver
    } else if pr % 10 == 0 {
        -8.0 // aligned with common granularity, likely reusable
    } else if pr % 5 == 0 {
        -3.0
    } else if pr % 3 == 0 {
        2.0
    } else {
        6.0 // coprime-ish leftover, awkward class
    };
    score += class_penalty;

    // Integer-division threshold on post_residual: leftover >= half capacity is
    // still a "full class" bin, leftover < half is degraded.
    if pr * 2 >= bin_capacity {
        score -= 5.0;
    } else {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual
    // (harmonic pairing), reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 25.0;
        } else if diff <= 10 {
            score -= 10.0;
        } else {
            score -= (10.0 - diff.min(10) as f64) * 0.5;
        }
    } else if next_item_size > pr {
        // next item cannot use this bin's leftover anyway; slight penalty for
        // wasting the pairing opportunity.
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current bin's fit is bad. Penalize fresh bins moderately.
    if bin_residual == bin_capacity {
        score += 20.0
            - (fitting_bins_count as f64) * 2.0
            + (open_bins_count as f64) * 1.5;
        // Early in the stream, new bins are cheaper; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mean-residual coupling: when open bins are already roomy on average,
    // be pickier about fits (add spread-aware term).
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Fraction-of-capacity phase of item: items in the top quarter of capacity
    // should go into the emptiest possible bins.
    if item_size as f64 > 0.75 * cap {
        score += (bin_capacity - bin_residual) as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post_residual gaps are the enemy.
    // Any gap that cannot hold even the smallest plausible item is a total loss.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // unusable sliver -> heavy penalty
    }
    // Medium gaps (usable only by tiny items) get a graded penalty.
    if post_residual >= dead_threshold && post_residual < 20 {
        score += 18.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that can still accommodate the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps future options alive
        } else if post_residual > 0 {
            score += 6.0; // blocks the next item -> dead space for it
        }
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones,
    // penalize the empty new-bin candidate more as open_bins_count grows.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Mean-residual coupling: a bin far below mean residual is underfilled;
    // favor placing into it to balance load across bins.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Early in the stream, be slightly more willing to open bins (future flexibility);
    // late in the stream, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit).
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        // Reward tight two-item packing; stronger if the pair fills the bin well.
        score -= 12.0 + (slack_after_next as f64) * -0.15 - (post_residual as f64 - next_item_size as f64).abs() * 0.05;
        // Extra reward for a perfect chain (post_residual == next_item_size).
        if slack_after_next == 0 {
            score -= 25.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot follow here: penalize creating stranded small gaps.
        if post_residual < 10 {
            // Dead space that likely can never be used (items >= 1... small gap still usable).
            score += 0.0;
        } else {
            score += 6.0;
        }
    }

    // Penalize post residuals that are unusable for typical items (too small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open
    // bin offers a decent fit. Make the empty bin moderately attractive.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline for a fresh bin: cost of consuming fresh capacity.
        score = cap * 0.55;
        // If the next item is large and current item leaves a bad gap, new bin is fine.
        if next_item_size > 0 && next_item_size > item_size.max(post_residual) {
            score -= 8.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins already: discourage more.
        score += open_bins_count as f64 * 0.5;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor)
        // scaled against the mean residual across open bins.
        let tightness = (bin_residual as f64 - item_size as f64);
        score += (tightness - mean_residual).abs() * 0.08;
        // Slight preference for fuller bins when many bins are open.
        score -= (cap - bin_residual as f64) * 0.02 * (open_bins_count as f64).min(10.0) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * fit_ratio;
    }

    // Penalize tiny dead space that nothing small can use later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 45.0;
        } else if nxt <= post_residual as f64 {
            score -= 15.0 * (nxt / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty for wasting the slot
            score += 8.0 * (1.0 - post_residual as f64 / nxt);
        }
    }

    // Time horizon: early in stream, prefer keeping bins flexible (mild);
    // late in stream, squeeze hard into open bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / cap);

    // Global state: many open bins with high mean residual -> prefer consolidating
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and nothing else fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 35.0 - 30.0 * pressure - 0.2 * item_size as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 8.0 * x * x * cap
        - 4.0 * x * x * x * cap;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, prefer tight fits less aggressively; late, tighten more
    let coupling = 10.0 * (x - 0.5) * (x - 0.5) * (progress - 0.5);
    score += coupling * cap;

    // Reward using nearly-full bins more strongly as stream progresses
    score -= progress * (cap - pr) * 0.5;

    // Last-chance bin bonus (avoid opening new bin when only one fits)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize mildly, more when open bins fit well
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Lookahead: if next item could reuse this post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 12.0 * (1.0 - (nxt / pr.max(1.0)) - 0.5).abs();
        } else {
            score += 5.0;
        }
    }

    // Slight penalty for bin deviating from mean residual (balance)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose leftover lies in
    // "useful" residue classes (divisible by small item sizes) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Modulo-based dead-space penalty: residual not divisible by 10 wastes space.
    let residue_class = post_residual % 10;
    score += (residue_class as f64) * 1.5;

    // Integer-division thresholds on post_residual: classify leftover utility.
    let class = post_residual / 10; // 0..10
    match class {
        0 => score += 60.0,          // nearly full bin: excellent, reward strongly
        1 => score -= 20.0,          // very small leftover, still good
        2 | 3 => score -= 8.0,       // moderate leftover
        4 | 5 => score += 4.0,       // half-empty: mediocre
        _ => score += 10.0,          // large leftover: poor use
    }

    // Capacity-fraction coupling: penalize leaving > half capacity unused.
    let frac = post / cap;
    if frac > 0.5 {
        score += (frac - 0.5) * 40.0;
    } else {
        score -= (0.5 - frac) * 10.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic compatibility: next item divides post residual evenly.
        if post_residual % next_item_size == 0 {
            score -= 15.0;
        }
        score += (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / cap;
        // New bin becomes attractive when mean residual across bins is low
        // relative to the item, or stream is early and many bins open.
        score = 55.0 + (1.0 - crowding) * 30.0 - progress * 10.0
            + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 20.0;
        }
    } else {
        // Prefer tighter existing bins slightly (best-fit flavor).
        score += (bin_residual as f64) * 0.05;
    }

    // Mean-residual coupling: penalize placements that deviate from mean badly.
    score += ((post - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (sizes >= 1, but practically anything < ~10 is nearly
    // unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward tight fits proportionally to fill ratio.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill;

        // Penalize leaving a gap just below the next item size: that gap
        // is wasted because the lookahead item cannot use it.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving a gap that exactly (or nearly) fits the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 5.0 {
                score -= 20.0 - slack * 2.0;
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; makes new-bin opening less attractive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // and slightly early in the stream.
        score += 25.0 + 6.0 * pressure;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress);
        // If other bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 30.0 * fitting_bins_count as f64;
        }
    } else {
        // Existing bin that fits: reward being one of few options (last chance).
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Reward bins tighter than average (good fits).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can still host the next item (chained placement), penalize dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits after this placement: reward proportionally
            // to how tightly the pair packs the bin.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * (bin_capacity as f64 - pair_waste);
        } else {
            // Next item won't fit here: penalize, worse if the leftover is
            // a small unusable sliver.
            let sliver = post_residual as f64;
            let sliver_penalty = if sliver < 10.0 {
                25.0 + (10.0 - sliver) * 2.0
            } else {
                sliver * 0.15
            };
            score += sliver_penalty;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Coupling with mean residual: prefer bins tighter than the average
    // (best-fit style), but not when it creates a tiny dead zone.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it attractive only when no open bin offers
    // a good chained fit. Bias it so it's chosen for large items that
    // would otherwise leave big residuals elsewhere unusable.
    if bin_residual == bin_capacity {
        // Neutral-ish base: full residual; discount when item is large
        // (large items are better placed in a fresh bin) or when current
        // open bins are crowded (high mean residual).
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 25.0;
        let crowded_bonus = if open_bins_count > 0 { mean_residual / bin_capacity as f64 * 15.0 } else { 15.0 };
        score -= large_item_bonus + crowded_bonus;
        // Penalize opening a new bin for tiny items early in the stream.
        if item_size < 30 && (step_index as f64) / (total_items.max(1) as f64) < 0.5 {
            score += 20.0;
        }
    }

    // Mild preference for filling bins more completely overall.
    score -= 0.1 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fit quality: how tightly the item fills the bin
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let post_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: subtract proportional to how much of the residual is consumed
    let consumed = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= consumed * 40.0;

    // Penalize dead space nonlinearly: small post-residuals (< 10) are nearly unusable
    // since items are >= 1; treat very small residuals as wasted.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - post_ratio);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * post_ratio;
        }
    } else {
        // Last item: closing a bin as fully as possible is pure gain
        score -= 10.0 * (1.0 - post_ratio);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin (which wastes this bin's residual forever).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate handling: opening a new bin should be penalized when open bins
    // have decent residual mass, but allowed when the item is large and residuals are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_cost = 30.0;

        // If mean residual across open bins is large, opening a new bin is wasteful
        new_bin_cost += mean_residual * 0.5;

        // Early in the stream, prefer consolidating; later, spreading is safer
        new_bin_cost += 10.0 * (1.0 - progress);

        // If many bins can fit the item, opening a new one is clearly bad
        if fitting_bins_count > 0 {
            new_bin_cost += 8.0 * fitting_bins_count as f64;
        }

        // If the item is large relative to capacity and mean residual is small,
        // a new bin may be justified: reduce the cost.
        let residual_deficit = (item_size as f64 - mean_residual).max(0.0);
        new_bin_cost -= residual_deficit * 0.8;

        // If no open bin can fit (defensive), the new bin is the only option
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0;
        }

        score += new_bin_cost.max(0.0);
    }

    // Mild penalty for using bins with already-low residual when other options exist:
    // preserves flexibility if this bin isn't the only choice.
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score += tightness * 5.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Global state coupling: many open bins with high mean residual suggests fragmentation;
    // encourage filling existing bins harder.
    if open_bins_count > 3 {
        score -= mean_residual * 0.05 * (open_bins_count as f64).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize leftover space, with a superlinear term
    let mut score = pr + (pr / cap).powi(2) * 20.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (favor new bins); late, waste is costly.
    let prog_poly = 3.0 * progress * progress - 2.0 * progress * progress * progress; // smoothstep in [0,1]
    score -= prog_poly * pr * 0.6;
    score += (1.0 - prog_poly) * pr * 0.25;

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - pr / (item_size as f64 + 1.0);
    score -= tightness * 8.0 * (0.5 + prog_poly);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + prog_poly * 10.0;
    }

    // Penalize bins with residuals far from the mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 10.0;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * prog_poly + 3.0;
    }

    // Mild penalty when many bins are open (discourage sprawl)
    score += (open_bins_count as f64).sqrt() * 0.3;

    // New-bin candidate baseline: keep it competitive but not dominant
    if bin_residual == bin_capacity {
        score += 4.0 + prog_poly * 12.0 - (mean_residual / cap) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small moduli capture
    // "usable" leftover sizes that future items (10..80 typical) can still fill.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect fit bonus: zero residual is ideal.
    if pr == 0 {
        score -= 40.0;
    }

    // Modulo classes: leftover that is a multiple of common item granularities
    // (10, 20, 25, 50) is more reusable than odd dead space.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 2.0; }
        // Odd/unusual residues are dead-space prone.
        if pr % 10 != 0 && pr < 10 { score += 8.0; }
    }

    // Integer-division thresholds: classify leftover into usefulness bands.
    if pr >= 60 {
        score -= 4.0; // big leftover still highly usable
    } else if pr >= 30 {
        score -= 1.0;
    } else if pr >= 10 {
        score += 2.0; // small leftover, only tiny items can use
    } else {
        score += 5.0; // near-dead space
    }

    // Coupling with lookahead: if next item fits exactly into the post residual,
    // strongly reward; if next item cannot ever fit, penalize lightly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // harmonic compatibility: next item leaves a nice residue too
            let nr = pr - next_item_size;
            if nr % 10 == 0 { score -= 8.0; }
            score -= (nr as f64) / (cap * 4.0);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin by its would-be residual,
    // relaxed when many open bins are already fragmented.
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 0.5 * mean_residual + (open_bins_count as f64) * 0.4;
        if fitting_bins_count == 0 { score -= 30.0; }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // room for the lookahead in a fresh bin
        }
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (tighter packing), above mean implies fragmentation.
    let resid_f = post_residual as f64;
    if resid_f > mean_residual {
        score += (resid_f - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - resid_f) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual >= 1 && post_residual <= 10 {
        // Unusable dead space: heavy penalty.
        score += 45.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 20 {
        // Marginal gap: moderate penalty scaled by how close it is to dead range.
        score += (20 - post_residual) as f64 * 1.2;
    }

    // Reward bins whose residual is nearly consumed (tight packing).
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 25.0;

    // Open-bin pressure: mild penalty to avoid bin proliferation,
    // stronger early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 0.4 * (1.0 - progress));

    // Last-chance bin: strong reward to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item exactly consumes the remaining space.
        if post_residual == next_item_size {
            score -= 18.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to lookahead: penalize if gap can't hold next item.
        if post_residual < 10 {
            score += 10.0;
        }
    }

    // Slight aversion to placing into bins far above mean residual when
    // mean residual is large (keeps large bins available for big items).
    if mean_residual > 40.0 && post_residual as f64 > mean_residual {
        score += 4.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fit (post_residual == next_item_size)
    if next_item_size > 0 {
        let chain_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item exactly fills the bin after this placement
        if post_residual == next_item_size {
            score -= 60.0 + 40.0 * progress;
        } else {
            // Penalize deviation from a perfect 2-step chain
            score += 0.35 * chain_gap;
            // Extra penalty if next item cannot fit at all in the leftover space
            if post_residual < next_item_size {
                score += 0.5 * (next_item_size - post_residual) as f64;
            }
        }
        // Lookahead coupling with mean residual: if this bin is tighter than average,
        // placing here is good (keeps roomier bins flexible)
        if (bin_residual as f64) < mean_residual {
            score -= 0.4 * (mean_residual - bin_residual as f64);
        } else {
            score += 0.25 * (bin_residual as f64 - mean_residual);
        }
    } else {
        // Last item: reward filling as tightly as possible
        score -= 0.5 * item_size as f64;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Dead-space penalty: small unusable residuals are bad
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when existing bins would leave large waste
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream
        score += 70.0 - 30.0 * progress;
        // If a perfect 2-step chain is achievable in a fresh bin, allow it
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 80.0;
        }
        // Discourage new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 && post_residual < next_item_size {
            score += 40.0;
        }
    }

    // Mild preference for bins with low residual (best-fit flavor)
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero residuals).
    if post > 0.0 && post < 10.0 {
        score += 6.0;
    } else if post >= 10.0 && post < 20.0 {
        score += 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 5.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // next item cannot use this residual; penalize proportionally
            score += 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Global state: when mean residual is large, prefer reusing existing bins over new ones.
    if bin_residual < bin_capacity {
        score -= 0.3 * (mean_residual / cap);
    }

    // New-bin candidate handling: opening a bin is only attractive early in the stream
    // or when existing residuals are too fragmented to absorb future items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // Penalize new bins more as stream progresses and when fragmentation is low.
        score += 4.0 + 10.0 * progress * (1.0 - fragmentation);
        // If fragmentation is high, a fresh bin is valuable (reset the pool).
        if fragmentation > 0.5 {
            score -= 6.0 * (fragmentation - 0.5);
        }
        // Avoid opening new bins when many are already open with usable space.
        if open_bins_count > 2 && fitting_bins_count > 0 {
            score += 3.0;
        }
    }

    // Mild time-horizon coupling: later in the stream, consolidation matters more,
    // so slightly prefer bins with smaller post residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual (waste), non-linearly squashed.
    let pr_norm = pr / cap; // in [0,1]
    let mut score = 10.0 * pr_norm.powf(1.7) * cap;

    // Smooth polynomial coupling: waste penalized more when many bins are open.
    let open_norm = (open_bins_count as f64).ln1p();
    score += 3.0 * pr_norm * pr_norm * open_norm * cap * 0.1;

    // Stream progress coupling: late in the stream, prefer tighter fits (larger residual waste penalized).
    let tightness = pr_norm.powf(2.0 + 3.0 * progress);
    score += 8.0 * tightness * cap * 0.1;

    // Lookahead: reward leaving residual that can host the next item (smooth coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = ((pr - nx).max(0.0)) / cap;
        let exact_next = 1.0 - ((pr - nx).abs() / cap);
        score -= 4.0 * exact_next * (1.0 - fit_next);
        // Penalize leaving residual just above next item (dead space risk), smoothed.
        let gap = (pr - nx) / cap;
        if gap > 0.0 {
            score += 5.0 * gap * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * (1.0 - pr_norm);
    }

    // Mean residual context: bins far from mean residual get mild penalty (encourage uniformity).
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * cap * 0.1;

    // New-bin candidate: penalize slightly so it's only chosen when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 7.0 + 3.0 * (1.0 - progress);
    } else {
        // Reward filling existing bins proportionally to item usage.
        score -= 1.5 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands in "usable"
    // classes (multiples of 10, or >= 20) are rewarded.
    let pr = post_residual;
    let usable = pr % 10 == 0;
    if usable {
        score -= 6.0;
    }
    // Dead-space penalty: tiny residuals that few future items can use.
    if pr > 0 && pr < 10 {
        score += 12.0;
    } else if pr < 20 {
        score += 3.0;
    }

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Fractional capacity coupling: how much of the bin this item consumes.
    let fill_frac = item_size as f64 / cap;
    score -= 10.0 * fill_frac;

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            // next item fits: mild reward scaled by leftover class
            let nxt_left = pr - next_item_size;
            if nxt_left % 10 == 0 { score -= 8.0; } else { score += 2.0; }
        } else {
            // next item won't fit here: penalize slightly more if this bin
            // would be left with awkward residual
            if pr > 0 && pr < 10 { score += 6.0; }
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full on average or this bin is the only option.
    if bin_residual == bin_capacity {
        score = 55.0;
        if open_bins_count == 0 {
            score = 0.0;
        } else if mean_residual < 15.0 {
            score = 20.0;
        }
        // Late in stream, prefer filling existing bins harder.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        if fitting_bins_count == 0 { score -= 30.0; }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packs).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to fit even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item * 10 {
        score += 50.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Non-linear penalty for medium-dead space (gap that likely fits nothing useful).
    if post_residual > 0 && post_residual <= 20 {
        score += (21 - post_residual as f64).powi(2) * 0.5;
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio * fill_ratio;
    }

    // Perfect-fit lookahead: if the next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If next item fits in the post residual, mild reward (keeps bin useful).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item would NOT fit the leftover, mild penalty (bin becomes dead weight).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Open-bins pressure: discourage spreading across many bins when pressure is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64 / (1.0 + progress * 5.0)).min(10.0);
    score += pressure * 1.5;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins fit poorly.
    if bin_residual == bin_capacity {
        // A new bin is neutral-ish; make it attractive only when current fit is bad.
        let fit_badness = post_residual as f64;
        score = 55.0 + fit_badness * 0.3 - (fitting_bins_count as f64) * 0.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin is fine for any next item
            score -= 5.0;
        }
    } else {
        // Existing bin: bonus for keeping mean residual low (compactness).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if next <= post {
            // Next item fits in leftover: strong reward, best when near-exact.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 50.0; // perfect 2-step chain
            }
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally.
            score += 10.0 * diff / bin_capacity as f64;
        }
    }

    // Prefer tight fits relative to current residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Penalize bins far from the mean residual (avoid fragmenting typical fill levels).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, consolidate: favor bins that end up nearly full.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual already does this).

    // Lookahead: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving awkward gaps.
        score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize large dead space relative to smallest useful item (assume ~1..100, use item_size as proxy scale).
    if post_residual > 0 && post_residual < item_size {
        // Fragmentation risk: gap smaller than typical item size.
        score += 15.0 * (1.0 - post_residual as f64 / item_size as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            // poor fit in the only bin — allow new bin consideration
            score += 25.0;
        }
    }

    // Time horizon: early in stream, be conservative with bins (pack tight);
    // late in stream, closing bins cleanly matters less, prefer tight fits still.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer reusing bins with below-average residual usage.
    if open_bins_count > 1 {
        let dev = mean_residual - post_residual as f64;
        score += 0.3 * dev;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Only favor opening a new bin when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        if item_size >= 60 && post_residual as f64 <= 40.0 {
            score -= 5.0;
        } else {
            score += 12.0; // default penalty: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual)
    let mut score = x;

    // Smooth polynomial coupling: penalize large dead space more aggressively as stream progresses
    let p = progress;
    score += 0.8 * x * x * (0.5 + p);
    score -= 0.35 * x * (1.0 - x) * (1.0 - p); // reward moderately full bins early

    // Cubic smooth term: strongly punish near-empty post residuals late
    score += 0.6 * x * x * x * p;

    // Lookahead coupling: if next item fits in post residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 0.5 * (1.0 - nx / cap) * (1.0 + p);
        } else {
            score += 0.25 * (nx / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // New-bin candidate: mildly penalize so we only open when existing fits are bad
    if bin_residual == bin_capacity {
        score += 0.9 - 0.4 * p;
    }

    // Slight preference for bins with residual below mean (consolidate fuller bins)
    score += 0.15 * ((pr as f64) - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "dead" (small but
    // unfillable) get penalized; residues that are harmonic multiples of common
    // item sizes get rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space bands: post_residual in 1..10 is nearly unusable.
    if post_residual >= 1 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic reward: post_residual divisible by common small item sizes.
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50].iter() {
            if post_residual % d == 0 {
                score -= 8.0 + (post / *d as f64);
            }
        }
    }

    // Lookahead coupling: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0; // chain fit: excellent
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Harmonic classes of the leftover slack after the lookahead fit.
            score -= 15.0 * (1.0 - slack / cap);
            if slack < 10.0 {
                score += 12.0; // creates dead space after next item
            }
        } else {
            // Next item cannot use this residue: residue should be harmonic-large
            // or zero to be worth keeping.
            if post_residual < next_item_size && post_residual > 0 {
                score += 0.05 * post as f64;
            }
        }
        // Modulo-class affinity between next item and current residue.
        let m = (post_residual % 20) as i32 - (next_item_size % 20) as i32;
        score -= 2.0 * (m.abs() as f64).min(5.0) as f64 * 0.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current bin would
    // leave a bad harmonic class and the item is large.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slightly prefer new bin for large items that
        // would leave tiny residues in existing bins.
        score = 12.0 + item_size as f64 * 0.1;
        if item_size >= 60 && post_residual < 10 {
            score -= 20.0;
        }
    }

    // Late in the stream: consolidate harder, discourage opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
        score += 0.03 * (open_bins_count as f64) * (1.0 - progress);
    }

    // Penalize residues far below mean (wasteful bins) mildly.
    if post < mean_residual - 20.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
