    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically small gaps waste space)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead coupling: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit in post_residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean residual context: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: empty bin gets moderate baseline; prefer
    // it only when the item is large relative to capacity and no tight fit exists.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * item_size as f64 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless it enables a
    // perfect 2-step chain (item + next item exactly fills capacity).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual == next_item_size {
            return -1000.0; // perfect lookahead chain in a fresh bin
        }
        // Base cost of a new bin; soften late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = bin_capacity as f64 * (1.2 - 0.4 * progress);
        // If this bin is the only fitting option, opening new is acceptable.
        if fitting_bins_count == 0 {
            new_bin_cost -= 200.0;
        }
        // If next item is huge and no open bin likely fits it, fresh bin is fine.
        if next_item_size > 0 && next_item_size > mean_residual {
            new_bin_cost -= 60.0;
        }
        return new_bin_cost;
    }

    // Lookahead matching: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0; // perfect 2-step fill
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64); // next still fits
            // Extra reward if after the next item the bin closes exactly.
            if post_residual == next_item_size { score -= 50.0; }
        } else {
            // Next item won't fit here; penalize the stranded dead space,
            // scaled by how close post_residual is to the smallest useful size.
            let dead = post_residual as f64;
            score += dead * 0.8;
            if dead < 10.0 {
                score -= 30.0; // tiny sliver, effectively full bin: good
            }
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 100.0;
    }

    // Reward bins whose residual is well below the mean (tight bins close fast).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.5;
    // Penalize bins far above mean residual (loose bins hoard space).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Mild pressure to use open bins when many are open.
    score -= open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    score -= 2.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3) * 10.0;

    // Exact or near-exact fill is extremely desirable.
    if post_residual < 5 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item: penalize proportionally.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_exists = fitting_bins_count > 0 && (bin_residual - item_size) as f64 > mean_residual;
        let mut penalty = 30.0;
        if fitting_bins_count == 0 {
            penalty -= 60.0; // must open a bin anyway
        }
        if post_residual as f64 > mean_residual {
            penalty -= 10.0; // fresh bin keeps more usable space than average
        }
        // Late in the stream, prefer consolidating into open bins.
        penalty += 20.0 * progress;
        penalty += 0.5 * open_bins_count as f64;
        let _ = tight_exists;
        score += penalty;
    }

    // Prefer bins below-mean residual to keep a spread of usable gaps.
    if bin_residual < bin_capacity {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits mildly; Late: strongly punish residual waste.
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;
    let w = 1.0 + 2.5 * progress * progress;
    score += w * (pr2 * 30.0 + pr3 * 60.0) * cap * 0.1;

    // Exact-ish fit reward (smooth, no piecewise): small post_residual gets big discount.
    score -= 40.0 * (1.0 - pr).powi(6);

    // Penalize bins whose residual is far from the item (bad coupling).
    let br = bin_residual as f64;
    score += 0.15 * (br - item_size as f64).abs();

    // Lookahead: if next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            score -= 12.0 * (1.0 - (post_residual as f64 - nx) / cap);
        } else {
            score += 8.0 + 10.0 * progress;
        }
    }

    // Last-chance bin: strong discount to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Mean residual context: bins below mean residual are more precious.
    score += 0.1 * (mean_residual - br);

    // New-bin candidate: neutral-ish baseline, made less attractive when decent fits exist.
    if bin_residual == bin_capacity {
        score = cap as f64 * 0.5 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= cap * 0.5 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Classify post_residual into harmonic "slots" of capacity/4 (25-unit classes)
    let quarter = (bin_capacity / 4).max(1) as f64;
    let class = (pr / quarter).floor(); // 0..4 harmonic class
    // Reward low classes (tight fits): subtract more for lower class
    score -= class * 8.0;

    // Exact-fill harmonic bonus: post_residual in {0, 25, 50, 75} classes divisible
    if post_residual % (bin_capacity / 4).max(1) == 0 {
        score -= 12.0;
    }
    // Perfect fill
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo-10 dead-space penalty: residuals not divisible by 10 are harder to reuse
    let dead = (post_residual % 10) as f64;
    score += dead * 1.5;

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward: chain potential; stronger when next nearly fills remaining
            let next_fill = next_item_size as f64 / pr.max(1.0);
            score -= 15.0 * next_fill;
            // Harmonic match: next item lands on same modulo class
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // Penalize: leftover unusable for lookahead item
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean
    // (consolidate small residuals into fewer bins)
    let dev = mean_residual - pr;
    score += dev * 0.3;

    // New-bin candidate: neutral baseline tuned against mean residual of open bins
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when many open bins exist
        // and when the stream is early (future reuse likely)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to be useful for typical items.
    if post_residual > 0 {
        let dead_threshold = 20.0f64;
        if (post_residual as f64) < dead_threshold {
            // Quadratic penalty ramping up as the gap shrinks toward 0.
            let gap = post_residual as f64;
            score += (dead_threshold - gap) * (dead_threshold - gap) * 0.35;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to item size (wasted fraction of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Pressure from number of open bins: with many open bins, prefer
    // consolidating into existing bins over opening new ones.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: penalize it by open-bin pressure
        // so we only open new bins when existing fits are truly bad.
        score += 30.0 + open_pressure;
    } else {
        score -= open_pressure * 0.5;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item would fit exactly in the
    // post-residual, reward this placement strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit in the leftover: mild penalty for stranding space.
            score += 6.0;
        }
    }

    // Mean residual context: if this bin's residual is far below the mean,
    // it is already tight; encourage filling it further.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.3;
    } else {
        score += (bin_res_f - mean_residual) * 0.15;
    }

    // Stream progression: later in the stream, be slightly more aggressive
    // about closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial lookahead credit: how close post_residual is to next item.
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + gap / 5.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual too small for next item: penalize dead space relative to mean residual.
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.8;
    }

    // Reward tight fits relative to mean residual across open bins.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when good open bins exist (new bin has residual == capacity).
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // But if no open bin fits well (post_residual large), allow new bin.
        if post_residual as f64 >= mean_residual * 1.5 {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small bonus for leaving round/moderate residuals usable by typical items.
    if post_residual >= 10 && post_residual <= 40 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with quadratic penalty on waste.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            // next item fits, but leave some slack preference
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual < 0.5 * bin_capacity as f64;
        let poor_fit = (item_size as f64 / bin_residual as f64) < 0.15;
        if crowded || poor_fit {
            score -= 30.0;
        } else {
            score += 45.0; // discourage opening new bins when existing ones work
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 0.0 {
        score += 0.15 * mean_residual * (1.0 - progress);
    }

    // Time horizon: early stream, be greedy for tight fits; late stream, consolidate harder.
    score -= (1.0 - progress) * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual was already small (avoid fragmenting large residuals).
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear penalty on large leftover space
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tightening fits matters more (weight grows smoothly)
    let tighten = (norm_pr * norm_pr) * (0.5 + 1.5 * progress * progress);
    score += 40.0 * tighten;

    // Reward near-perfect fits smoothly (quadratic bowl around zero residual)
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin: smooth bonus scaled by scarcity of fitting bins
    if fitting_bins_count <= 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: penalize wasting space the next item could use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (nx - pr).abs() / cap;
        score += 15.0 * usable * usable;
        if nx <= pr && nx > 0 {
            score -= 8.0 * (nx / cap) * (1.0 - progress);
        }
    }

    // Mild penalty for leaving this bin far below mean residual (dead space)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: prefer keeping item in an open bin unless residual is bad
    if bin_residual == bin_capacity {
        score += 18.0 - 12.0 * progress + 0.05 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals in the same class
    // (mod small divisors) are more likely to be fillable by future items.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Exact-fit reward: zero residual is perfect.
    if pr == 0 {
        score -= 1000.0;
    }

    // Class the residual into harmonic buckets: 0, tiny (1..10), small
    // (10..25), medium (25..50), large (50..). Dead space is worst when
    // it is small-but-nonzero (unusable slivers).
    let class_penalty = if pr == 0 {
        -50.0
    } else if pr < 10 {
        // sliver: almost certainly dead space
        60.0 + (10 - pr) as f64 * 3.0
    } else if pr < 25 {
        15.0
    } else if pr < 50 {
        // medium residual: could fit a mid-size item
        5.0
    } else {
        0.0
    };
    score += class_penalty;

    // Coupling with lookahead: reward residuals that exactly or nearly
    // match the next item's size class.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) >= nxt {
            let waste = pr as f64 - nxt;
            // prefer bins whose leftover after this item matches next item
            score -= 20.0 * (1.0 - waste / cap);
            if pr == next_item_size {
                score -= 80.0; // perfect chaining
            }
        } else {
            // next item cannot use this residual at all
            score += 10.0;
        }
    }

    // Integer-division thresholds: residual in [item_size, item_size + k)
    // classes — bins whose residual is a multiple of common item sizes
    // (10/20/25/50) are more reusable.
    let harmonics = [10u32, 20, 25, 40, 50];
    for h in harmonics.iter() {
        if pr >= *h && pr % h == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin for a single item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // early in the stream or when all existing fits are terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a fresh bin grows with progress (waste matters more
        // later since fewer items remain to fill it).
        let fresh_cost = 30.0 + 70.0 * progress;
        // If the current item would leave a sliver in every open bin,
        // a fresh bin is competitive.
        let sliver_risk = if pr > 0 && pr < 10 { 45.0 } else { 0.0 };
        score += fresh_cost - sliver_risk;
        // A fresh bin taking the item leaves residual = capacity - item,
        // which is fine if large enough for typical follow-ups.
        if pr >= 50 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter bins among equals (best-fit bias)
    // via mean_residual comparison: bins below mean residual are already
    // tight; placing there keeps loose bins flexible.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Fractional capacity utilization bonus: reward high fill fraction.
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any plausible item are worthless.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0; // heavy penalty for unusable slivers
    }

    // Reward near-perfect fits (small but usable residual is fine).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 25.0;

    // Penalize large leftover space that will likely become dead space anyway.
    if post_residual > 40 {
        score += (post_residual - 40) as f64 * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; mildly penalize wasting residual
        score += 2.0;
    }

    // Prefer bins whose residual is already below mean (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 - tightness * 0.0 + fitting_bins_count as f64 * 4.0;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when leftover exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // leftover can still host the next item: partial reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + slack / 10.0);
        } else {
            // leftover too small for next item: penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Compare post_residual to mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Penalize large unusable residuals more aggressively (dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 60.0; // tiny residual is effectively a perfect fill
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive late in the stream or when it beats
    // a bad fit; otherwise penalize opening extra bins.
    if bin_residual == bin_capacity {
        score += 300.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // opening fresh bin allows pairing current+next cleanly
            score -= 350.0;
        }
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference for tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small residual is good, but avoid tiny useless slivers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space penalty
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // residual too small for next item: mild penalty proportional to wasted potential
        score += (post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: prefer tightest (score already tracks post_residual), slight diversity bonus
    if fitting_bins_count > 2 {
        score += 2.0;
    }

    // Global state: if mean residual is high, prefer filling existing bins aggressively
    let tightness = (bin_residual as f64) / (bin_capacity as f64);
    score += tightness * 5.0 * (1.0 - (mean_residual / bin_capacity as f64).min(1.0));

    // Time horizon: early in stream, be more willing to open new bins (keep residuals large);
    // late in stream, consolidate into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 6.0 * (1.0 - tightness);
    score -= progress * 4.0;

    // New-bin candidate: opening a new bin costs; only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let open_cost = 30.0 + (open_bins_count as f64) * 2.0 - progress * 10.0;
        score += open_cost;
        if item_size >= 60 {
            // large items fit cleanly in fresh bins
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: post_residual scaled by progress-dependent polynomial
    let pr = post_residual as f64;
    let poly = 1.0 + 2.0 * progress - 3.0 * progress * progress;
    score += poly * pr * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - (pr / bin_capacity as f64);
    score -= tightness * tightness * 10.0 * (0.5 + progress);

    // Penalize large dead space non-linearly
    score += (pr / bin_capacity as f64).powi(3) * 50.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += gap * 0.1 * (1.0 - progress);
        if pr >= next_item_size as f64 {
            score -= 5.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Mean residual alignment term
    score += (mean_residual - pr) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: tighter fit wins.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64);

    // Harmonic class of post_residual: residuals that are "nice" fractions
    // of capacity are more reusable. Class by integer division on 10-wide bands.
    let band = post_residual / 10;
    let band_penalty: f64 = match band {
        0 => -6.0,   // 0..9 : nearly perfect fill
        1 => -3.0,   // 10..19: fits any small item
        2 => -1.5,
        3 => 0.0,
        4 => 1.0,
        5 => 2.0,
        6 => 3.0,
        7 => 4.5,
        _ => 6.0,    // large dead space
    };
    score += band_penalty;

    // Modulo harmony: residual divisible by common item granularities (10, 20, 25)
    // is more likely to be exactly filled later.
    if post_residual % 10 == 0 { score -= 2.0; }
    if post_residual % 20 == 0 { score -= 1.0; }
    if post_residual % 25 == 0 { score -= 1.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            // harmonic pairing: next item leaves a small tail again
            let tail = post_residual - next_item_size;
            if tail <= 10 { score -= 3.0; } else { score -= (10.0 / tail as f64).min(2.0); }
        } else {
            // next item cannot use this bin's leftover: slight penalty for awkward class
            if post_residual < 10 { score += 1.0; }
        }
    } else {
        // last item: prefer filling as much as possible
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so that
    // only genuinely bad fits into open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 12.0;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (keeps a spread of usable gaps).
    if (post_residual as f64) < mean_residual {
        score -= 0.5;
    } else {
        score += 0.5 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Penalize many open bins slightly to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Small but potentially usable gap: mild penalty scaled by tightness.
        score += 0.5 * (20 - post_residual) as f64;
    }

    // Reward tight fits: the smaller the waste relative to the item, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // (especially the last-chance bin) over opening new ones.
    score += 3.0 * open_bins_count as f64;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins have poor fit potential.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 && fill_ratio > 0.7 {
            score += 30.0;
        }
    }

    // Lookahead: if the next item exactly fits the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover gap; penalize leaving awkward space.
        score += 0.3 * post_residual as f64;
    }

    // Mean-residual coupling: bins far below the mean residual are less urgent.
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // Early stream: slightly prefer consolidation; late stream: fill aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Aggressive 2-step lookahead matching ---
    // Reward bins whose post_residual exactly matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();

        // Exact match: strong bonus (subtract a lot).
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Smooth proximity reward: the closer post_residual is to next_item_size,
            // the better, scaled relative to the mean residual for normalization.
            let scale = 1.0 + mean_residual / bin_capacity as f64;
            score -= 25.0 * (-diff / (10.0 * scale)).exp();
        }

        // Penalize post_residuals that are too small to ever fit a typical next item
        // (dead space), but slightly less if the next item actually fits.
        if post < next_item_size && diff > 0.5 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 8.0 + 12.0 * (1.0 - post / bin_capacity as f64) * (1.0 - progress);
        }

        // If next item fits after this placement, mild extra reward.
        if next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // --- Tightness reward: prefer minimal post residual overall ---
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    // --- Last-chance bin bonus: if this is the only bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; make it unattractive unless every
        // open bin would leave a terrible fit (large dead space).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_residual - item_size) as f64;
        // Cost grows with expected waste and stream position (late bins are
        // more likely to be reusable).
        score = 45.0 + 0.5 * waste + 20.0 * progress;

        // If the new bin would enable a perfect 2-step chain, discount it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
        // If very few bins are open and mean residual is high, prefer reusing.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // --- Mild penalty for spreading across many bins ---
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Lookahead: penalize if the leftover space is just barely unusable by the next item
    // (dead space), but reward if the next item fits exactly into the leftover.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: reward proportionally to how well it fills.
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * chain_fill;
        } else {
            // Leftover is dead space relative to the next item: penalize.
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as bins accumulate and stream progresses.
        score += 8.0 + 10.0 * progress + 0.4 * open_bins_count as f64;
        // But if mean residual is very low (open bins are full), opening a bin is fine.
        if mean_residual < 8.0 {
            score -= 12.0;
        }
    } else {
        // Reward filling existing bins when they are above-average full.
        if (bin_residual as f64) < mean_residual {
            score -= 2.5;
        }
        // Slight bonus for using bins as the stream nears its end (avoid new bins late).
        score -= 2.0 * progress;
    }

    // Mild penalty for leaving residuals in the awkward 1..10 range (likely unusable).
    if post_residual >= 1 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: best-fit preference (smaller post residual -> lower score)
    let mut score = pr as f64;

    // Smooth polynomial coupling: as the stream progresses, tighten the
    // preference for small post residuals (dead space matters more later).
    let progress_gain = t * (x * x * cap) * 0.5;
    score += progress_gain;

    // Reward scarcity of fitting bins (last-chance bin) with a smooth decay
    let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
    score -= scarcity * cap * 0.15 * (1.0 - t * 0.5);

    // Penalize bins whose residual is far from the mean (outliers) smoothly
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap * 0.05;

    // Lookahead: bonus if the post residual accommodates the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Mild penalty for opening a brand-new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (capacity fractions) ----
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class boundaries: dead space (< 10) is nearly unusable; classes 10..20,
    // 20..34, 34..50, 50..100 have decreasing value per unit.
    let class_value: f64 = if post_residual == 0 {
        -40.0 // perfect closure: huge reward
    } else if post_residual < 10 {
        60.0 // dead space, heavily penalized
    } else if post_residual < 20 {
        30.0
    } else if post_residual < 34 {
        15.0
    } else if post_residual < 50 {
        5.0
    } else {
        0.0
    };
    score += class_value;

    // Modulo arithmetic: residuals that are multiples of common small sizes
    // (10, 20, 25) remain "harmonic" and reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
    }

    // Integer-division threshold on next item fit: reward if next item fits
    // exactly or nearly into the resulting residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 { score -= 10.0; } else { score -= 2.0; }
        } else {
            // next item cannot fit here: residual quality matters more
            score += 4.0;
            // penalize if residual falls into a narrow useless band
            if post_residual >= 10 && post_residual < 20 { score += 6.0; }
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when this bin
    // would be left with awkward small residual and many bins are open.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * mean_residual - (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big-then-big streams favor fresh bins
        }
        if step_index as f64 / total_items as f64 > 0.9 {
            score += 5.0; // late stream: prefer closing out open bins
        }
    }

    // Slight preference for fuller bins overall (tight packing pressure).
    score -= 0.05 * (cap - pr - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

