        // new-bin candidate: penalize proportionally to open bins, reward if item is large
        score += pressure * 8.0 - fill_ratio * 25.0;
        // opening a new bin is only attractive if no existing bin fits well
        if fitting_bins_count > 0 && (bin_residual - item_size) as f64 > mean_residual * 0.5 {
            score += 30.0;
        }
    }

    // Lookahead coupling: if next item fits snugly into the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 45.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover: dead space likely
        score += (post_residual as f64) * 0.5;
