    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space that the next item cannot use.
        score += 8.0;
    }

    // Strongly favor the last chance bin: placing here avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild preference for bins tighter than the fleet average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Penalize leaving very small unusable slivers (waste creation).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when few bins fit the item or the
    // stream is early and residual fragmentation is high.
    if bin_residual == bin_capacity {
        let base = 45.0;
        let scarcity = 30.0 * (fitting_bins_count as f64).min(3.0);
        let fragmentation = (mean_residual - 50.0).max(0.0);
        score = base + scarcity - fragmentation * 0.4 - 20.0 * (1.0 - progress);
    }

    // Slight tie-breaking toward using more of the bin overall.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = prn * (1.0 + 0.6 * progress + 0.9 * progress * progress);

    // Penalize tiny dead space quadratically (waste grows super-linearly)
    score += 0.35 * prn * prn * (1.0 + progress);

    // Reward tight fits: item fills a large fraction of the residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 1.2 * fill * fill * (1.0 - progress * 0.5);

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 1.5 * (nxt / cap) * (1.0 + progress);
        } else {
            score += 0.4 * (nxt / cap) * prn;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.5 * (1.0 + progress);
    }

    // Coupling with mean residual: prefer bins deviating from mean (fragmentation control)
    let dev = (pr - mean_residual) / cap;
    score += 0.25 * dev * dev;

    // Mild preference for keeping bin count low early on
    score += 0.05 * (open_bins_count as f64 / (1.0 + total_items as f64)) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are "clean".
    let class = post_residual / 10;
    let harmonic_bonus = match class {
        0 => -30.0,                       // perfect fit
        1 => -12.0,
        2 => -6.0,
        3 => -3.0,
        4 => 0.0,
        5 => 2.0,
        6 => 4.0,
        7 => 7.0,
        8 => 10.0,
        9 => 13.0,
        _ => 15.0,
    };
    score += harmonic_bonus;

    // Integer-division threshold coupling: if next item can exactly fill post_residual
    // (mod-10 compatibility), strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= 10 {
            score -= 8.0;
        } else {
            score += gap as f64 * 0.3;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual anyway; small penalty scaled by waste
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize fragmenting a large residual with a tiny item (mod mismatch).
    if item_size < 20 && post_residual > 60 {
        score += 15.0;
    }

    // New-bin candidate handling: prefer reusing tight bins; new bin only when
    // no good fit exists (item small relative to mean residual, many open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let reuse_pressure = open_bins_count as f64 * 2.0;
        score = 110.0 - progress * 10.0 + reuse_pressure
            + if fitting_bins_count == 0 { -60.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= item_size && post_residual == bin_capacity { 0.0 } else { 0.0 };
        // allow new bin if it would hold both current and next item harmonically
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Mean residual coupling: keep residual close to mean to preserve balance.
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize residuals that cannot fit even the smallest future item,
    // scaled by how "wasted" the gap is relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Open-bin pressure: discourage spreading across many bins,
    // but allow new bins when current bin would leave a bad gap.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // New-bin candidate: neutral baseline with mild penalty so it is
    // chosen only when all open bins score badly.
    if bin_residual == bin_capacity {
        score = 30.0 + (open_bins_count as f64) * 0.3;
        // Late in the stream, opening new bins is cheaper than dead space.
        if step_index as f64 / total_items.max(1) as f64 > 0.7 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / tight fits (low post_residual relative to item size).
    let tightness = post_residual as f64 / item_size.max(1) as f64;
    score -= (1.0 - tightness.min(1.0)) * 12.0;

    // 2-step lookahead: reward when post_residual matches next item size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 25.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            score -= (18.0 - (diff / 8.0).min(15.0)).max(0.0);
        } else {
            // next item can't fit: penalize dead space, especially large leftovers
            score += (post_residual as f64 / 10.0).min(15.0);
        }

        // Perfect chain: post_residual == next_item_size and then zero left.
        if post_residual == next_item_size {
            score -= 5.0;
        }
    }

    // Relative-to-mean coupling: bins with residuals near mean are "average" targets;
    // favor bins whose residual is well above item size but not excessively wasted.
    score += (bin_residual as f64 - mean_residual).clamp(-30.0, 30.0) * 0.15;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 && next_item_size <= bin_capacity {
            (bin_capacity - next_item_size) as f64
        } else {
            bin_capacity as f64
        };
        // New bin attractive only if all existing fits are poor (high post_residual).
        score += 8.0 + best_possible * 0.3;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins with low residual among many open bins (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.35;

    // Bin-count pressure: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: neutral residual, but penalized more
        // as the stream progresses and as open-bin count grows.
        score += 8.0 + 6.0 * progress + 0.6 * open_bins_count as f64;
        // If nothing else fits well, opening a fresh bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else if fitting_bins_count == 0 {
        // This open bin is the only fit; use it regardless.
        score -= 25.0;
    }

    // Mild late-stream consolidation: reuse bins more aggressively near the end.
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: waste after placement, scaled by a smooth polynomial in progress.
    // Later in the stream, waste is punished more aggressively (less slack time to fill gaps).
    let progress_curve = 1.0 + 2.0 * progress * progress;
    let mut score = pr * progress_curve;

    // Non-linear coupling: quadratic dead-space penalty that grows with progress.
    score += progress * (pr * pr) / cap;

    // Reward tight fits: near-zero post_residual gets a strong discount.
    let tightness = 1.0 - (pr / cap).min(1.0);
    score -= 6.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin;
    // if post_residual is too small for the next item, mildly penalize (dead space for lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 3.0 * fit_quality * fit_quality;
        } else {
            score += 1.5 * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins; encourages consolidation.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Deviation from mean residual: prefer bins whose residual is close to the mean
    // (balanced packing) unless the fit is very tight.
    let dev = (pr - mean_residual).abs();
    score += 0.3 * dev * (1.0 - tightness);

    // New-bin candidate: make an empty bin slightly attractive early (fresh capacity),
    // but progressively less so as the stream advances and consolidation matters.
    if bin_residual == bin_capacity {
        score += 4.0 * progress - 1.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on "usable"
    // classes (multiples of common item sizes) are more valuable to keep.
    let usable = |r: u32| -> f64 {
        let mut w = 0.0;
        for m in [10u32, 20, 25, 50, 100].iter() {
            if m <= r && r % m == 0 { w += 3.0; }
        }
        // integer-division threshold: residual in [1,9] is near-dead space
        if r < 10 && r > 0 { w -= 6.0; }
        w
    };
    score -= usable(post_residual) * 2.0;
    score += usable(bin_residual) * 0.5;

    // Penalize creating residual that cannot host the lookahead item
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        if post_residual >= next_item_size {
            score -= 4.0;
        }
        // modulo coupling: post_residual and next item share a harmonic class
        if next_item_size <= post_residual && post_residual % next_item_size.max(1) == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Empty new-bin candidate: only attractive when few bins fit or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        score += 8.0 + progress * 4.0 - pressure * 0.3;
        if fitting_bins_count == 0 { score -= 20.0; }
    }

    // Waste fraction penalty (non-linear)
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 10.0;

    // Tight fit reward
    if post_residual < 5 { score -= 5.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are unusable "dead" space — penalize heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit: reward strongly.
        score -= 1000.0;
    } else if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Nonlinear penalty growing as residual becomes unusably small
        // relative to typical item sizes.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 8.0; // tiny gap: dead space
        } else if pr < 20.0 {
            score += (20.0 - pr) * 3.0;
        }
    }

    // Reward tight fits relative to bin residual (best-fit reinforcement).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over opening new ones; with few bins, opening new is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + pressure * 12.0;
        // If only one bin can fit the item, strongly avoid opening a new bin.
        if fitting_bins_count <= 1 {
            score += 200.0;
        }
    } else {
        // Reward using an existing bin, especially when bins are scarce.
        score -= 10.0;
        if fitting_bins_count == 1 {
            // Last-chance bin: place here to avoid opening a new bin.
            score -= 120.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit in leftover: mild penalty for wasteful gap.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Early in the stream, allow slightly more freedom to spread items;
    // later, tighten packing (dead space becomes costlier).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item (harmonized packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match for the next item is a jackpot.
        if post_residual == next_item_size {
            score -= 500.0;
        } else {
            // Penalize proportional to how far post_residual is from fitting next item.
            score += gap * 2.0;
        }
        // If next item cannot fit here at all, mild penalty (bin less useful).
        if post_residual < next_item_size {
            score += 20.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor),
    // penalize bins with unusually large residuals relative to the fleet.
    if mean_residual > 0.0 {
        score += (post_residual as f64 - mean_residual) * 1.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins exist and fit reasonably well:
    // the new-bin candidate has bin_residual == bin_capacity; add a fixed offset
    // so it's only chosen when open bins score poorly (dead-space avoidance).
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in the stream, avoid proliferating bins even more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 40.0;
        }
    }

    // Slight preference for tighter bins overall (waste-awareness).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor minimal post-residual (best-fit core).
    score -= (1.0 - (post_residual as f64) / cap) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 20.0 + 15.0 * chain_tightness;
    }
    // Penalize leftover that is too small for the next item (dead space risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer placing into bins with small residual relative to the global mean
    // (consolidate nearly-full bins; keep large holes for large items).
    let res_frac = (bin_residual as f64) / cap;
    score += (res_frac - mean_residual / cap) * 30.0;

    // Don't waste a big hole on a small item unless few bins are open.
    let fill_ratio = (item_size as f64) / (bin_residual as f64);
    if fill_ratio < 0.5 {
        score += (0.5 - fill_ratio) * 50.0;
    }

    // Time horizon: later in the stream, be greedier about closing bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - res_frac);

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large, few bins fit it, or the stream is early.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        let mut new_bin_score = 45.0;
        if item_size >= 70 { new_bin_score -= 25.0; }
        if fitting_bins_count <= 1 { new_bin_score -= 30.0; }
        new_bin_score -= early * 15.0;
        if open_bins_count == 0 { new_bin_score -= 100.0; }
        // If next item is large and this item is small, keep holes open instead.
        if next_item_size > 50 && item_size < 40 { new_bin_score += 25.0; }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: penalize remaining residual, non-linearly (dead space hurts more as it grows).
    let mut score = pr * (1.0 + 0.008 * pr / cap);

    // Smooth polynomial coupling: residual squared normalized by capacity.
    score += 0.35 * (pr * pr) / cap;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Stream progress coupling: later in the stream, prefer filling bins more aggressively.
    score -= 10.0 * progress * tightness;

    // Lookahead: bonus if the leftover residual can fit the next item exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            // Leftover too small for next item: penalize unusable slivers.
            score += 3.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins when
    // all open bins are poor fits (high post_residual there).
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.3 * mean_residual - 5.0 * progress;
        // If no bin fits, opening is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild tie-break: prefer bins whose residual is close to the mean (balance).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity fractions (1/8 granularity) — dead space classes.
    let cap = bin_capacity as f64;
    let eighth = cap / 8.0;
    let post_class = (post_residual as f64 / eighth).floor() as u32; // 0..8

    // Reward small post_residual classes (tight fits), super-linearly.
    match post_class {
        0 => score -= 12.0,           // perfect / near-perfect fit
        1 => score -= 7.0,            // leftover < 12.5 -> likely reusable by small items
        2 => score -= 3.0,
        3 => score -= 1.0,
        4 => score += 1.5,            // half-full-ish: mediocre
        5 => score += 3.0,
        6 => score += 5.0,
        7 => score += 7.5,            // nearly empty bin used: wasteful
        _ => {}
    }

    // Integer-division coupling: does post_residual exactly accommodate the
    // lookahead item (or a small multiple)? Strong bonus for chained fit.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if post_residual >= nxt {
            let chain = post_residual / nxt; // integer division = harmonic multiplicity
            let rem = post_residual % nxt;
            if rem == 0 {
                score -= 6.0 + 2.0 * (chain as f64).min(4.0); // exact divisor: great chaining
            } else if rem <= 5 {
                score -= 3.0; // near-exact chain
            }
            // Penalize if post_residual fits next item but leaves a nasty class
            let rem_class = ((post_residual - nxt) as f64 / eighth).floor() as u32;
            if rem_class >= 6 {
                score += 2.5;
            }
        } else {
            // post_residual too small for next item: dead space unless tiny
            if post_residual > 0 && post_residual < 10 {
                score -= 2.0; // negligible waste
            } else if post_residual < nxt {
                score += 2.0; // stranded medium dead space
            }
        }
    }

    // Modulo arithmetic on residual: bins whose residual is a "friendly"
    // multiple of common small sizes (5,10,20,25) are more reusable.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 2.5; }
        else if r % 5 == 0 { score -= 1.2; }
        if r % 20 == 0 { score -= 1.0; }
        if r % 25 == 0 { score -= 1.0; }
        // Prime-ish / awkward residuals get a mild penalty
        if r % 10 != 0 && r % 5 != 0 && r % 2 != 0 { score += 0.8; }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but prefer keeping
    // items in open bins when mean residual is healthy.
    if bin_residual == bin_capacity {
        // New bin: baseline score equals item footprint waste (100 - item).
        score = (bin_capacity - item_size) as f64 + 4.0;
        // Early in stream or many items expected: new bins are cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 3.0 * (1.0 - progress);
        // If no open bin fits well, opening fresh is attractive.
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    } else {
        // Existing bin: reward keeping mean residual balanced (avoid many
        // half-empty bins). Penalize if this bin is far below mean residual.
        if mean_residual > 0.0 {
            let dev = mean_residual - bin_residual as f64;
            score += 0.05 * dev; // prefer bins with residual below average (fuller bins)
        }
        // Many open bins: encourage consolidation into fuller bins.
        if open_bins_count > 4 {
            score -= 0.3 * (open_bins_count.min(20) as f64) * (1.0 - post_residual as f64 / cap);
        }
    }

    // Small harmonic nudge on item size classes (mod 10 buckets).
    let item_class = item_size % 10;
    if item_class == 0 {
        // Decade items (10,20,...) align well with capacity 100: reward tight packing.
        if post_residual % 10 == 0 { score -= 1.5; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste — penalize them heavily, proportionally to how "dead" they are.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable dead space (min item size baseline): harsh penalty.
        score += 500.0 + (10 - post_residual) as f64 * 50.0;
    } else {
        // Usable gap: mild reward scaled by how much room remains relative to capacity.
        score -= (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from current bin count.
        score += 80.0 + (open_bins_count as f64) * 12.0;

        // If the next item could pair with this item in a fresh bin, mild discount.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0;
        }

        // Early in the stream, opening bins is cheaper (exploration).
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= (1.0 - progress) * 40.0;
        }
    } else {
        // Existing bin: small reward when its residual is near the mean (balanced usage),
        // penalty when this bin is an outlier with much more space than average.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.5;

        // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
        if next_item_size > 0 && post_residual >= next_item_size {
            let lookahead_waste = post_residual - next_item_size;
            if lookahead_waste < 10 {
                score -= 200.0;
            } else {
                score -= 20.0;
            }
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            // This placement kills the bin for the lookahead item — extra penalty.
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // with the next item's size (perfect chaining of two items).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // perfect 2-step fit
        } else if post_residual > next_item_size {
            // leftover after next item would fit too; mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack);
        } else {
            // next item cannot follow: penalize dead space growth
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Reward tight fits relative to current bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Penalize bins whose residual is far below the mean (already fragmented),
    // reward bins with residual above the mean (absorbing capacity).
    let dev = post_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // (would leave little useful residual anyway) or when no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        let poor_fits = next_item_size == 0 || (post_residual as f64) < 0.5 * (next_item_size as f64);
        if large_item || poor_fits {
            score -= 15.0;
        } else {
            score += 40.0; // discourage wasting a fresh bin on small items
        }
    }

    // Mild preference to consolidate into fewer bins as the stream progresses.
    score += 0.5 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: small post residual relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 / (1.0 + tightness);

    // Dead space penalty: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize wasting large residuals on small items
        score += 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer fuller bins among many open bins (best-fit bias)
    score -= 0.2 * (bin_capacity - bin_residual) as f64 / open_bins_count.max(1) as f64;

    // Global pressure: if mean residual is low, conserve open capacity
    if mean_residual < item_size as f64 {
        score += 15.0;
    }

    // New-bin candidate logic: only attractive early in stream or when open bins are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = post_residual as f64; // = capacity - item_size
        let desperation = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        // favor new bin when existing fits are bad and item is large
        let badness = (post_residual as f64).min(50.0);
        score = fit_quality + desperation - 40.0 * (1.0 - progress) - (item_size as f64 * 0.3) + badness * 0.1;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 50.0;
        }
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when a unique fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;

    // Smooth polynomial base: reward tight fits (small post_residual) with cubic shaping
    let mut score = 3.0 * x - 3.0 * x * x + x * x * x;
    score += 1.7 * x * x * x * x - 0.9 * x * x;

    // Stream-progress coupling: late in the stream, tighten fits more aggressively
    let t = progress * (1.0 - progress) * 4.0; // peak mid-stream
    score += (0.8 * t + 1.4 * progress) * x * x;

    // Dead-space penalty scaled by item size occupancy
    let fill = item_size as f64 / cap;
    score -= 2.2 * fill * (1.0 - x) * (1.0 - x);

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = (nx <= x) as i32 as f64;
        score -= 1.5 * usable * (1.0 - (nx - x).abs());
    }

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Mean-residual coupling: penalize bins far from the pack mean
    score += 0.4 * ((mean_residual - pr) / cap).abs();

    // New-bin candidate: prefer it only when it yields a genuinely better fit
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * x * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "dead zone" (tiny slivers 1..=9) are heavily penalized; leftovers that
    // can host future mid-size items (class by tens) are rewarded.
    let post = post_residual as i64;
    let class = post / 10; // integer-division threshold class

    // Penalize dead-space slivers superlinearly.
    if post > 0 && post < 10 {
        score += 25.0 + (10 - post) as f64 * 3.0;
    } else if post == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Reward leftovers in "usable" harmonic bands (multiples of 10-ish).
        // Classes 1..=4 (residual 10..49) are moderately useful; larger
        // residuals mean we wasted space placing a small item.
        match class {
            1 => score -= 12.0,
            2 => score -= 15.0,
            3 => score -= 14.0,
            4 => score -= 10.0,
            5 => score -= 4.0,
            6 => score -= 1.0,
            7 => score -= 3.0,
            8 => score -= 2.0,
            9 => score -= 4.0,
            _ => {}
        }
        // Sub-class fine tuning via modulo 5: residuals like 25, 35 host
        // many item sizes; odd slivers slightly worse.
        let m = post % 5;
        if m == 0 {
            score -= 3.0;
        } else if m == 4 {
            score += 1.5;
        }
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 && next_item_size <= post as u32 {
        let slack = post as f64 - next_item_size as f64;
        // Tight lookahead fit is best.
        score -= 18.0 - (slack / 10.0).min(10.0);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize if this bin becomes a dead bin.
        if post > 0 && post < next_item_size as u32 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is a fine default but should
    // lose to good fits in open bins; it should win over terrible fits.
    if bin_residual == bin_capacity {
        // Mild penalty so good existing fits win; also slightly cheaper to
        // open new bins early in the stream (amortize over many items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 6.0 * (1.0 - progress);
    } else {
        // Prefer the fullest (best-fitting) open bins: reward small pre-residual.
        score += (bin_residual as f64) * 0.05;
    }

    // Crowd awareness: with many open bins, discourage spreading.
    if open_bins_count > 4 {
        score += 0.3 * (open_bins_count as f64).ln();
    }

    // Tie-break toward tight mean-residual matching.
    score += ((mean_residual - post_residual as f64) / 10.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 80.0;
    } else {
        // Usable gap: mild reward proportional to how tight the fit is.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tightness;
    }

    // Reward bins whose residual exactly accommodates the known next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual < next_item_size {
            // Gap too small for the lookahead item: dead space for the future.
            score += 15.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; encourage
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln() * 4.0 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + bin_pressure;
        // But if no open bin fits well (large dead space elsewhere), allow opening.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        score -= bin_pressure * 0.5;
    }

    // Slight preference for bins below the mean residual (emptier bins absorb
    // the item, keeping tight bins for small future items).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: post_residual == next_item_size means the next
    // item can exactly fill this bin (2-step lookahead match).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward proportional to closeness of the match.
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        // Exact match: massive bonus.
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Next item cannot fit here anyway: mildly penalize leaving a
        // residual that neither fits the next item nor is useful.
        if next_item_size > post_residual {
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.0;
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving a residual well below average wastes capacity.
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (item barely fits or nothing fits); penalize otherwise.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64 / bin_capacity as f64) > 0.8;
        let no_fit = fitting_bins_count == 0;
        if tight || no_fit {
            score -= 15.0;
        } else {
            score += 25.0;
        }
    }

    // Penalize tiny dead space (<10) that is hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> prefer consolidation into open bins;
    // late stream -> keep flexibility (dead space more costly later).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let time_pressure = 0.5 + t;

    // Perfect fit reward: strong bonus for exact closure.
    if post_residual == 0 {
        score -= 60.0 * time_pressure;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily;
    // if next item can't use the residual at all, penalize dead space.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste * time_pressure;
        }
        // Chain fit: residual also fits next item's complement
        if next_item_size + item_size == bin_residual {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding: many open bins -> encourage filling existing ones;
    // few open bins -> tolerate opening new bins less.
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.15 * crowd * (post_residual as f64 / bin_capacity as f64);

    // Penalize leaving tiny unusable fragments (below min item size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * time_pressure;
    }

    // Mild penalty for very low fill relative to bin mean: prefer balanced packing.
    let fill_ratio = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // New-bin candidate: neutral-ish base so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * t;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: post_residual scaled by progress-dependent factor
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    // Smooth progress-driven weighting of residual waste
    let w = 1.0 + 0.6 * progress * progress;
    score = pr * w + 8.0 * prn * prn * (1.0 + 2.0 * progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: penalize if next item fits the post-residual (keep room), reward otherwise
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score += 6.0 * (1.0 - progress);
        } else {
            score -= 3.0;
        }
    }

    // New-bin candidate: prefer keeping it closed early; allow opening when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let mean_fit = mean_residual / cap;
        score += 20.0 - 12.0 * mean_fit - 1.5 * crowd * progress;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: penalize deviating far from average residual state
    let dev = (post_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "size class" of future item
    // (1..100) could still land here. Residuals in [0,9] are dead space.
    let dead = (post_residual < 10) as i32 as f64;
    score += dead * 60.0;

    // Integer-division thresholds: residual bucket 10..=19, 20..=34, 35..=49, 50+
    let bucket = post_residual / 20; // 0..=5
    let bucket_penalty = match bucket {
        0 => 25.0,               // 10..19: only tiny items fit
        1 => 8.0,                // 20..39
        2 => 0.0,                // 40..59: flexible
        _ => -6.0,               // 60+: large usable space
    };
    score += bucket_penalty;

    // Modulo-10 harmonic class: residuals divisible by 10 align with the
    // item-size grid, making exact future fills more likely.
    let aligned = (post_residual % 10 == 0) as i32 as f64;
    score -= aligned * 4.0;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // prefer residual that leaves next item in a good class
            let next_dead = (post_residual - next_item_size < 10) as i32 as f64;
            score += slack * 0.3 + next_dead * 15.0;
        }
        // If next item cannot fit this residual, mild penalty when residual is tiny
        if next_item_size > post_residual && post_residual < 20 {
            score += 10.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost that
    // scales with how many bins are already open, so we prefer packing into
    // existing bins unless the fit is terrible.
    if bin_residual == bin_capacity {
        score = 55.0 + 3.0 * open_bins_count as f64;
        // If every fit elsewhere is bad (high mean residual waste) allow opening
        if mean_residual < 15.0 && post_residual == bin_capacity {
            score -= 10.0;
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 12.0 * (fill - 0.8) * 5.0;
    }

    // Late-stream consolidation: near the end, avoid leaving many scattered bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual % 15) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: residuals too small for the smallest item (1) don't exist,
    // but residuals smaller than a "useful" threshold are dead space.
    // Treat gaps < 10 (below min item size in classic setting) as unusable.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 500.0; // heavy penalty: creates unusable sliver
    }

    // Penalize gaps that can't fit the lookahead item if they could have
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0; // reward leaving room for the next item
    }

    // Perfect lookahead fit bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so this hits it).
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more when many bins already open
        score += 80.0 + 15.0 * open_bins_count as f64;
        // But allow new bins early in the stream or when existing residuals are poor
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 20.0 && progress > 0.2 {
            score -= 60.0; // existing bins are nearly full; new bin is fine
        }
    } else {
        // Favor bins with tighter residuals (best-fit coupling)
        score += (bin_residual as f64) * 0.1;
    }

    // Mild preference for bins below mean residual (consolidate fuller bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Slight late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain: residual consumed exactly by next item
        } else if next_item_size <= post_residual {
            // partial lookahead fit: reward closeness to a perfect chain
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 0.15 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Reward leaving residuals near mean (balanced fragmentation) slightly
    score += 0.05 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when several bins already fit the item
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But allow opening a new bin if the item fits perfectly (no waste)
        if post_residual == 0 {
            score -= 100.0;
        }
        // If no open bin is a tight fit and item is large, new bin is attractive
        if item_size >= 50 && next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 15.0;
        }
    }

    // Progress-based mild pressure: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize dead space: residuals too small for likely future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasting space that could hold it
            let gap = (next_item_size - post_residual) as f64;
            score += 0.08 * gap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin when current
    // open bins are crowded and the stream is early/mid.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // fresh bin baseline: attractive early, less so late
        score -= 3.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 20.0;
        }
    } else if fitting_bins_count > 1 {
        // mild preference to fill existing bins when alternatives exist
        score -= 1.0;
    }

    // Global state coupling: when mean residual is low (bins nearly full),
    // favor placements that leave usable residual above the mean.
    if post_residual as f64 > mean_residual {
        score -= 0.5;
    } else {
        score += 0.5 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Large items: prefer bins where they leave a mid-range residual (~20-30)
    // that is still usable for typical small items.
    let pr = post_residual as f64;
    if pr >= 10.0 && pr <= 40.0 {
        score -= 2.0 * (1.0 - (pr - 25.0_f64.abs()) / 25.0);
    }

    score += 0.01 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let fit_ratio = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 0.0 };

    let mut score = pr as f64;

    // Smooth non-linear coupling of post residual with stream progress
    let progress_term = (1.0 - progress) * (1.0 - progress);
    score -= progress_term * 8.0 * (norm_post * norm_post - 0.25 * norm_post);

    // Reward tight fits more strongly as stream progresses (quadratic in item size)
    score -= progress * 12.0 * norm_item * (1.0 - norm_post);

    // Penalize dead space non-linearly: cubic in normalized post residual
    score += 10.0 * norm_post * norm_post * norm_post * cap * 0.1;

    // Lookahead coupling: bonus if post residual matches next item smoothly
    if next_item_size > 0 {
        let match_term = 1.0 - ((norm_post - norm_next) / 0.5).abs();
        let match_smooth = match_term.max(0.0);
        score -= 6.0 * match_smooth * match_smooth * (1.0 - progress * 0.5);
        // Penalize if next item cannot fit into post residual
        if norm_next > norm_post {
            score += 4.0 * (norm_next - norm_post) * cap * 0.1;
        }
    }

    // Last-chance bin: strong smooth reward when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 7.0 * scarcity * (1.0 + progress);

    // Mean residual interaction: prefer bins near mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * 0.1;

    // New-bin candidate handling: neutral-ish baseline with smooth progress penalty
    if bin_residual == bin_capacity {
        score = cap * 0.35 + 20.0 * progress * progress - 5.0 * fit_ratio;
        if next_item_size > 0 && norm_next > 0.0 {
            score -= 3.0 * norm_next;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 act as "waste classes".
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    // Penalize awkward residues (dead space hard to fill by typical small items).
    let residue_penalty = match pr % 10 {
        0 => -6.0,          // perfect decade boundary: very reusable
        5 => -2.0,          // half-decade: decent
        1 | 9 => 4.0,       // near-full: mostly dead
        2 | 8 => 2.5,
        3 | 7 => 1.0,
        _ => 0.0,
    };
    score += residue_penalty;

    // Integer-division threshold on post_residual: classify leftover size.
    let leftover_class = pr / 10; // 0..=9
    // Reward small-but-usable leftovers; punish large wasted space.
    score += (leftover_class as f64) * (leftover_class as f64) * 1.5;

    // Capacity-fraction coupling: how full the bin becomes with this item.
    let fill_fraction = item_size as f64 / cap;
    if fill_fraction > 0.6 {
        score -= 12.0 * (fill_fraction - 0.6); // reward near-full packing
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 4.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item cannot follow here: slight penalty for tight choices
            score += 1.5;
        }
        // Harmonic modulo check: next_item_size and post_residual share class
        if next_item_size % 10 == pr % 10 && next_item_size <= pr {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin mildly attractive only when
    // open bins are congested (high mean residual usage) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = mean_residual / cap;
        score += 10.0;              // base cost of opening a new bin
        score -= 20.0 * congestion; // cheaper when existing bins are full-ish
        score -= 5.0 * progress;    // slightly cheaper late in the stream
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // allows pairing current+next in fresh bin
        }
    }

    // Mean residual anchoring: prefer bins whose residual is below average
    // (concentrate waste in few bins).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 3.0 * (mean_residual - bin_res_f) / cap;
    } else {
        score += 2.0 * (bin_res_f - mean_residual) / cap;
    }

    // Tie-break by tightness of fit: reward small residual gap.
    score -= (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Items range 1..100, so a residual gap of
    // < 10 is nearly unusable dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual < 25 {
            score += 12.0 * (25.0 - post_residual as f64) / 15.0;
        } else {
            // Larger leftovers are valuable; reward them mildly.
            score -= 0.15 * post_residual as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to the bin residual (fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill;

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over spreading; penalize less when few bins are open.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement; if next item cannot use the leftover, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mean-residual anchoring: prefer bins whose leftover stays near the mean
    // (keeps the fleet balanced), unless it's the last-chance case.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when the item is large relative to typical residuals or many bins
    // already exist. Otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild stream-progression term: early on, be more open to new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically fitting next item
            score += slack * 0.5;
            // bonus if next item fits snugly-ish
            if slack <= 5.0 {
                score -= 300.0;
            }
        } else {
            // next item won't fit here afterwards; penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let resid = post_residual as f64;
    if mean_residual > 0.0 {
        score += (resid - mean_residual) * 0.4;
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when decent open bins exist
    if bin_residual == bin_capacity {
        score += 120.0 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 200.0;
        }
    }

    // Late-stream tightening: waste matters more toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += resid * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit), scaled non-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize large dead space that becomes stranded.
            score += 5.0 + 0.1 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer filling bins whose residual is already small relative to the mean
    // (concentrate waste in few bins).
    if mean_residual > 0.0 {
        let ratio = bin_residual as f64 / mean_residual;
        score += 8.0 * (ratio - 1.0);
    }

    // Penalize bins with very large residuals when many bins are open (spread usage),
    // unless it's a fresh empty bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are quite full or item is large.
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Favor new bin when existing bins are tight (low mean residual) and item is large.
        score += 30.0 * pressure + 10.0 * (1.0 - progress) - 0.2 * (item_size as f64);
        if item_size > 50 {
            score -= 10.0;
        }
        let _ = tightness;
    }

    // Mild reward for using bins later in the stream (consolidate early).
    score -= 0.01 * (bin_capacity - bin_residual) as f64;

    // Small penalty for opening extra bins when many already exist.
    if bin_residual == bin_capacity {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = pr as f64;

    // Non-linear polynomial coupling: quadratic + cubic terms on normalized residual,
    // weighted by stream progress so late in the stream we push harder for tight fits.
    let poly = x * x - 1.5 * x * x * x;
    score += poly * cap * (0.2 + 0.8 * t);

    // Reward bins whose residual was already small (good density), scaled smoothly.
    let density = 1.0 - (bin_residual as f64 / cap);
    score -= 12.0 * density * density * (0.3 + 0.7 * t);

    // Last-chance bin: strong smooth reward to avoid wasting a scarce fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x * x);
    } else {
        // Mild penalty when many bins compete, decaying smoothly.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0) * x;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    // with a smooth saturating function of the match quality.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - slack * slack);
    } else if next_item_size > post_residual {
        // Penalize leaving residual that cannot host the next item, smoothly.
        score += 6.0 * (1.0 - t) * x;
    }

    // New-bin candidate: penalize opening a new bin, more strongly early/late
    // when open bins can already fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 + 20.0 * t;
    }

    // Slight preference to spread load when mean residual is high (smooth coupling).
    score -= 3.0 * (mean_residual / cap) * density;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small, reusable" residue classes are rewarded (negative adjustment).
    let c = bin_capacity as f64;

    // Class A: post residual fits next item exactly or leaves a perfect split.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        // Reward chain placements, stronger when the double placement is tight.
        score -= 12.0 + (after_next as f64).min(20.0) * 0.3;
        if after_next == 0 {
            score -= 15.0; // perfect two-item packing
        }
        // Harmonic residue classes of after_next: multiples of common item
        // sizes (10, 20, 25, 50) are highly reusable.
        let an = after_next;
        if an > 0 && (an % 10 == 0 || an % 25 == 0) {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Dead space: cannot host the lookahead item.
        score += 8.0;
    }

    // Integer-division thresholds on post_residual (capacity fractions).
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // exact fill is ideal
    } else if pr <= bin_capacity / 10 {
        score -= 10.0; // tiny unusable remnant, fine
    } else if pr <= bin_capacity / 4 {
        score -= 4.0;
    } else if pr <= bin_capacity / 2 {
        score += 2.0; // half-full leftovers are mediocre
    } else {
        score += 6.0; // large leftover wastes a bin slot
    }

    // Modulo arithmetic: leftover in "harmonic" buckets 0/5/10 mod 20 tends
    // to combine with typical item granularities.
    if pr % 20 == 0 || pr % 20 == 5 || pr % 20 == 10 {
        score -= 3.0;
    } else if pr % 20 == 15 {
        score -= 1.0;
    } else {
        score += 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize mildly, but relax late in the stream or
    // when the item is huge and open bins are congested.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 14.0 - 10.0 * progress;
        if item_size >= bin_capacity * 3 / 4 {
            score -= 8.0; // big items deserve fresh bins
        }
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 5.0; // nothing usable open anyway
        }
    }

    // Congestion-aware nudge: when many bins compete, tighten discrimination.
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 0.4 * (post_residual as f64 / c);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are heavily penalized (unusable gap).
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // small but potentially usable gap: moderate penalty
        score += 6.0;
    }

    // Reward tight fits (low waste ratio) nonlinearly.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading items
    // into a new bin; favor consolidating into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 8.0 + 5.0 * open_pressure;
    } else {
        // Existing bin gets a mild discount that grows with open-bin count.
        score -= 2.0 * open_pressure;
    }

    // Prefer bins whose residual is close to the current need (avoid
    // dumping small items into large-residual bins).
    let resid_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * resid_gap;

    // Lookahead: if the next item could exactly use this bin's post residual,
    // reward the placement (chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    // Early in the stream, be slightly more conservative about opening bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity && progress < 0.2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (-gap / 20.0).exp();
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + gap * 0.5;
        }
    }

    // Penalize unusable dead space (residual too small for any plausible item)
    if post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits relative to capacity
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it unattractive unless no good open bin exists
    if bin_residual == bin_capacity {
        score += 250.0 + 2.0 * open_bins_count as f64;
        // If nothing fits well, allow opening a new bin
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Mild preference for bins below mean residual (use up emptier bins first)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Early-stream: be slightly conservative about filling bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic decay of post residual.
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 0.25 * bin_residual as f64;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.3 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < 10 {
            // Small dead space is fine if next item is large anyway.
            score += 2.0;
        }
        // Penalize leaving a residual just barely below the next item size (trap state).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening bins mildly; heavier penalty when many bins are open
        // and the item could still fit somewhere with small waste.
        let mut open_cost = 8.0 + 1.5 * open_bins_count as f64 * (1.0 - progress);
        if fitting_bins_count > 0 {
            let best_possible = fitting_bins_count;
            // If alternatives exist, discourage new bin unless item is large.
            open_cost += (best_possible as f64) * 6.0;
        }
        // Large items near the end: opening a fresh bin is more acceptable.
        open_cost -= 0.05 * item_size as f64;
        // If mean residual across open bins is large, prefer reusing bins.
        open_cost += 0.15 * mean_residual;
        score += open_cost.max(0.0);
    }

    // Slight preference for filling bins with larger residual (consolidation).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Time-horizon modulation: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: prefer small post residual, with non-linear polynomial shaping.
    let mut score = pr
        - 12.0 * x * (1.0 - x) * cap * 0.25   // reward mid-range tight fits (smooth bump)
        + 30.0 * x * x * x * cap * 0.1;       // penalize large wasted space cubically

    // Smooth coupling with stream progress: later in stream, tolerate less waste.
    let prog_term = 1.0 + 0.8 * progress;
    score += 20.0 * x * x * prog_term * cap * 0.05;

    // Lookahead: reward residual that can hold the next item (smooth polynomial match).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_margin = pr - nx;
        if fit_margin >= 0.0 {
            let m = fit_margin / cap;
            score -= 15.0 * (1.0 - m * m) * (1.0 - progress * 0.5);
        } else {
            let m = (-fit_margin) / cap;
            score += 10.0 * (m * m) * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x * x);
    }

    // Prefer filling bins in bins with below-mean residual (smooth attraction).
    let mean_term = (mean_residual - pr) / cap;
    score += 8.0 * mean_term * mean_term * cap * 0.02 - 6.0 * mean_term;

    // Mild pressure to reuse open bins rather than open new ones as bins accumulate.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by small
    // denominators (2,4,5,10) are more likely to be filled by future items.
    let r = post_residual;
    if r > 0 {
        let mut harmonic_bonus = 0.0;
        if r % 10 == 0 { harmonic_bonus += 18.0; }
        else if r % 5 == 0 { harmonic_bonus += 12.0; }
        else if r % 2 == 0 { harmonic_bonus += 6.0; }
        // Very small odd dead space is bad; slightly penalize.
        if r < 10 && r % 2 == 1 { harmonic_bonus -= 8.0; }
        score -= harmonic_bonus;
    }

    // Integer-division thresholds: post_residual bucketed by capacity eighths.
    let bucket = r / (bin_capacity / 8);
    score += match bucket {
        0 => 4.0,          // nearly full: excellent, but tiny risk
        1 => 0.0,          // good
        2 => 2.0,
        3 => 5.0,
        _ => 0.0,
    };

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (perfect harmonic pair).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r {
            let new_r = r - next_item_size;
            if new_r % 5 == 0 { score -= 10.0; }
            if new_r < 10 { score -= 6.0; }
        } else {
            // next item cannot use this bin's remainder; mild penalty if
            // remainder is awkward (odd, small).
            if r % 2 == 1 && r < 20 { score += 6.0; }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when current
    // open bins are mostly full or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64 * 1.2;
        if tight && open_bins_count > 0 {
            score -= 10.0 + 15.0 * progress;
        } else {
            score += 8.0; // keep filling open bins by default
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * tightness * tightness;

    // Slight preference for bins below mean residual (consolidating fullness).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (below a minimum useful gap) are heavily penalized.
    let min_useful_gap = 10.0f64; // smallest plausible item footprint
    if (post_residual as f64) < min_useful_gap && post_residual > 0 {
        // Unusable sliver: penalize proportional to how close it is to wasted.
        score += 40.0 + (min_useful_gap - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Non-linear dead-space shaping: mid-sized gaps are the most valuable,
    // very large gaps waste capacity, tiny gaps are dead.
    let pr = post_residual as f64;
    score += 0.02 * pr * pr; // convex penalty: big leftovers cost increasingly more

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (pr / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open
    // (applies to the new-bin candidate whose residual == capacity).
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
    } else {
        // Mild reward for using existing bins, scaled by how open the fleet is.
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits into this bin's post_residual,
    // reward the placement (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; if post_residual is dead space, add penalty.
        if (post_residual as f64) < min_useful_gap {
            score += 10.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling the emptier bins less, conserving tight bins)... actually
    // prefer consuming bins with residual BELOW mean to keep large gaps available.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev; // bins with residual below mean get lower score
    }

    // Slight stream-progression adaptation: later in the stream, be more
    // conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: minimize wasted space, but weight it against mean residual context.
    score += (pr - mean_residual.max(0.0)) * 0.5;

    // Lookahead: reward if the next item exactly fills post_residual (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if diff < 1.0 {
            score -= 60.0; // exact 2-step chain: excellent
        } else if pr >= nxt {
            score -= 25.0 * (1.0 - diff / cap).max(0.0);
        } else {
            // next item won't fit here: dead space unless very small
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bonus: only bin that fits the item — avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when item is large
    // relative to all residuals and next item is small enough to pair later.
    if bin_residual == bin_capacity {
        let is_new = true;
        let _ = is_new;
        let tight_open = open_bins_count as f64 * (item_size as f64 / cap);
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0; // new bin can also host next item
        }
        if item_size >= 50 && fitting_bins_count >= 1 {
            score += 15.0; // discourage opening new bin when fits exist
        }
        let _ = tight_open;
        // early stream: be lenient about new bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
    }

    // Slight preference for filling tighter bins overall.
    score -= (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 2.0 * tightness * (item_size as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // risky small gap
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 15.0;
        // Extra reward if next item fills the remaining space almost exactly.
        let next_leftover = post_residual as i64 - next_item_size as i64;
        if next_leftover < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && (next_item_size as f64) > (post_residual as f64) {
        // Next item won't fit here anyway; slightly penalize leaving large gaps.
        score += 0.15 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If many bins can fit the item, discourage opening a new one.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    // Global state coupling: prefer bins whose residual is near the mean
    // (keep residuals balanced across bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Late in the stream, consolidate: strongly avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    // Slight preference for fuller bins (smaller residual) overall.
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer bins with smaller post-residual (tight fits).
    let mut score = post;

    // Non-linear tightness reward: strongly reward very small post-residual.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness.powf(2.5);

    // Dead-space penalty: post-residuals that are too small to host typical
    // future items are wasted; penalize the "unusable" band smoothly.
    let unusable = (1.0 - post / cap) * (1.0 - (post / 10.0).min(1.0));
    score += 8.0 * unusable * (0.5 + 0.5 * progress);

    // Exact-fit bonus (post_residual == 0).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits the post-residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - gap).powf(2.0);
    } else if next_item_size > post_residual {
        // Next item won't fit here; mild penalty for leaving awkward residue.
        score += 3.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Stream-progress coupling: later in the stream, be more conservative,
    // favoring filling existing bins over opening new ones.
    let progress_coupling = (progress * std::f64::consts::PI).sin();
    score -= 5.0 * progress_coupling * (item / cap);

    // New-bin candidate handling: empty bin gets a mild penalty that grows
    // with how many bins are open and how well other bins could fit.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.6 * open_bins_count as f64 + 20.0 * (1.0 - item / cap);
    }

    // Prefer bins whose residual is below the mean residual (denser bins).
    let dens = (mean_residual - post) / cap;
    score -= 4.0 * dens.max(-1.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction classes
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = if pr == 0 { 0u32 }
        else if pr <= eighth { 1 }
        else if pr <= quarter { 2 }
        else if pr <= 2 * quarter { 3 }
        else { 4 };

    // Penalize dead space in low classes (unusable small residuals)
    match class {
        0 => score -= 30.0,                       // perfect fit
        1 => score += 25.0,                       // tiny dead space is bad
        2 => score += 8.0,
        3 => score -= 5.0,                        // quarter+ residual still reusable
        _ => {}
    }

    // Modulo coupling: does next_item_size divide into post_residual nicely?
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx <= pr {
            let slack = (pr - nx) as f64;
            // exact / near-exact fit for the lookahead item is highly desirable
            if slack == 0.0 {
                score -= 40.0;
            } else if slack < eighth as f64 {
                score -= 12.0;
            } else {
                score += slack * 0.3;
            }
            // modulo harmonic bonus: next item leaves a clean class boundary
            let rem = pr % nx.max(1);
            if rem == 0 && nx >= eighth {
                score -= 10.0;
            }
        } else {
            // next item won't fit here regardless; mild penalty scaled by gap
            score += (nx - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a new bin should only win if this bin would
    // be left with badly fragmented residual. Penalize fresh bins mildly.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.25;
    }

    // Late in the stream, tighten packing (dead space matters more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.2;

    // Prefer bins already below mean residual (consolidating space)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space threshold: gaps too small for the smallest plausible item.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
        // Penalize residual that cannot fit the lookahead item (potential dead space).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Perfect fill is highly rewarded.
        score -= 40.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bins have poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
        if mean_residual < item_size as f64 {
            score -= 45.0; // no open bin fits well; open new bin
        }
    }

    // Progression: as stream advances, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Penalize residuals that are dead space: too small for the smallest possible next item (1).
    if post_residual == 0 {
        score -= 50.0; // perfectly packed bin is great
    } else if post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    }

    // If next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize mildly so we don't waste this bin's space.
        score += 10.0;
    }

    // Last-chance bonus: only one fitting bin; avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize deviating far below mean residual (keeps residuals balanced).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && fitting_bins_count > 0
            && open_bins_count > 0
            && (post_residual as f64) >= mean_residual;
        if good_fit_exists {
            score += 25.0;
        } else {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero post-residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let pair_eff = (item_size + next_item_size) as f64 / bin_residual as f64;
            score -= 22.0 * pair_eff;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when few bins fit the item or stream is young,
    // or when the item is large and would leave open bins too fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let mut nb = 5.0;
        if fitting_bins_count == 0 {
            nb -= 20.0;
        }
        if large_item && fitting_bins_count <= 2 {
            nb -= 12.0;
        }
        if progress < 0.25 && open_bins_count < 4 {
            nb -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            nb -= 10.0;
        }
        if mean_residual > 30.0 && fitting_bins_count > 2 {
            nb += 15.0;
        }
        score += nb;
    }

    // Mild global pressure: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 3 && mean_residual > 20.0 && bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: late in stream, prefer tighter fits
    let coupling = norm_pr * (1.0 - progress) - norm_pr * norm_pr * progress;
    score += 8.0 * coupling;

    // Reward near-perfect fits smoothly via cubic falloff
    let fit_gap = (pr as f64).ln_1p();
    score -= 6.0 * (-fit_gap * fit_gap).exp() * (0.5 + progress);

    // Last-chance bonus when this bin is the only fitting one
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * progress;
    }

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr as f64 {
            score += 3.0 * (nx - pr) * (0.5 + progress);
        } else {
            score -= 2.0 * (1.0 - (nx / cap).powi(2)) * progress;
        }
    }

    // Penalize proliferating bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (1.0 - (mean_residual / cap).clamp(0.0, 1.0));

    // New-bin candidate: mild penalty so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: how "reusable" is the leftover space.
    // Residuals divisible by common item sizes (10, 20, 25, 50) are easier to fill.
    let r = post_residual;
    let mut harmony_bonus = 0.0;
    if r == 0 {
        harmony_bonus -= 40.0; // perfect fit
    } else {
        if r % 10 == 0 { harmony_bonus -= 6.0; }
        if r % 20 == 0 { harmony_bonus -= 3.0; }
        if r % 25 == 0 { harmony_bonus -= 3.0; }
        if r % 50 == 0 { harmony_bonus -= 3.0; }
        // dead-space penalty for tiny unusable leftovers
        if r < 5 { harmony_bonus += 25.0; }
        else if r < 10 { harmony_bonus += 12.0; }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            harmony_bonus -= 30.0;
        } else if next_item_size < r {
            // next item fits but leaves another gap: mild reward scaled by fit quality
            let fill = next_item_size as f64 / r as f64;
            harmony_bonus -= 10.0 * fill;
        } else {
            // next item won't fit here: slight penalty
            harmony_bonus += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        harmony_bonus -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins have poor fits.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // opening a fresh bin is fine for large items, bad for small ones
        harmony_bonus += 20.0 * (1.0 - tightness);
        if fitting_bins_count > 0 {
            harmony_bonus += 10.0;
        }
    }

    // Prefer filling bins that are already low (tight packing), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_fraction = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    harmony_bonus -= 5.0 * fill_fraction * (0.5 + 0.5 * progress);

    // Slight preference for bins below mean residual (more filled than average).
    harmony_bonus -= 0.5 * (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) / 50.0;

    score += harmony_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10)
    // are pure waste -> heavy quadratic penalty.
    if post_residual >= 1 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Moderately awkward gaps (10..20) that only tiny items can use.
    else if post_residual < 20 {
        score += 12.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 18.0;
        }
        // Penalize leaving a gap that just barely fails the next item.
        if post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity, so this term
    // naturally penalizes the fresh-bin option when bins are plentiful).
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 3.0;
        // But if the item is large relative to mean residual space in open
        // bins, opening fresh may be wiser: soften the penalty.
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 12.0;
        }
    } else {
        // Slight preference for filling the emptiest existing bins first
        // (large residual -> slightly higher score keeps tight bins alive).
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Early in the stream, be a bit more willing to open bins (exploration);
    // late in the stream, consolidate aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += (1.0 - progress) * 10.0 - 5.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: the fuller the bin becomes, the better.
    score -= (cap - post) / cap * 30.0;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post) * 0.6;
    } else if next_item_size > 0 {
        // Reward leaving room exactly useful for the next item.
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Mild global pressure: many open bins with small mean residual -> prefer reusing.
    score -= mean_residual * 0.08;
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 45.0; // default penalty: prefer existing bins
        if fitting_bins_count == 0 {
            score -= 70.0; // no open bin fits -> must open new bin
        } else if fitting_bins_count == 1 {
            score -= 15.0; // weak alternative exists
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, waste in a fresh bin is less recoverable.
        score += progress * 8.0;
        // Large item relative to capacity favors a fresh bin.
        if item_size as f64 > 0.7 * cap {
            score -= 12.0;
        }
        // If next item is huge, a fresh bin leaves a clean large residual.
        if next_item_size as f64 > 0.6 * cap {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize leftover space, non-linearly (quadratic waste grows faster).
    let mut score = post * (1.0 + 0.9 * (post / cap).powi(2));

    // Smooth polynomial coupling of waste with stream progress:
    // early on, keep bins flexible (mild waste penalty); late, squeeze hard.
    let coupling = 1.0 + 1.6 * progress * (1.0 - progress) + 2.2 * progress.powi(3);
    score *= coupling;

    // Reward tight fits: subtract for small post_residual, amplified late.
    let tightness = (1.0 - post / cap).powi(3);
    score -= 14.0 * tightness * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / cap).powi(2);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that blocks the known next item: penalize.
        score += 4.0 + 6.0 * (post_residual as f64 / cap);
    }

    // Mild preference for fuller bins relative to the fleet mean residual.
    score += 0.05 * (mean_residual - post);

    // New-bin candidate: make it unattractive unless it is genuinely better
    // (empty bin has large post_residual, so base term already penalizes it;
    // add a fixed opening cost that fades as the stream nears its end).
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of post_residual: residues near capacity fractions
    let frac = pr / cap;
    // Penalize "dead zone" residuals that are too small for typical items (1..100 unknown)
    if pr > 0 {
        // residual usable only if next item can pair into it
        if next_item_size > 0 {
            if (next_item_size as u32) <= post_residual {
                // perfect harmonic pairing: strongly reward
                score -= 12.0 + 0.5 * pr as f64;
            } else {
                // dead space relative to lookahead: penalize non-linearly
                score += 6.0 * ((next_item_size as f64 - pr) / cap).powf(1.5);
            }
        }
    } else {
        // exact fit: best possible
        score -= 30.0;
    }

    // Modulo-class thresholds on post_residual: quarter classes
    let quarter = post_residual / (bin_capacity / 4).max(1);
    match quarter {
        0 => score -= 4.0,             // tiny leftover, near-perfect
        1 => score += 2.0,             // awkward small residual
        2 => score += 5.0,             // half-full leftover, moderately reusable
        _ => score += 1.0,             // large residual, still flexible
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // opening a new bin wastes nothing now but forgoes consolidation
        let pressure = if fitting_bins_count == 0 {
            -100.0 // forced: no open bin fits
        } else {
            // prefer open bins unless their residuals are all poor
            let avg_bad = (mean_residual / cap - frac).abs();
            10.0 + 20.0 * avg_bad
        };
        score += pressure;
        // late in stream, avoid opening bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid proliferation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Reward tight fits relative to bin residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness;

    // Coupling with mean residual: prefer bins below mean (consolidate emptier bins)
    score += 0.15 * (mean_residual - pr);

    // Slight penalty on many open bins to encourage closing them out
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // gap too small for the smallest plausible item is pure waste
        if dead < 10.0 {
            score += 60.0 * (10.0 - dead) / 10.0;
        } else if dead < 20.0 {
            score += 25.0 * (20.0 - dead) / 20.0;
        }
        // perfect fit bonus
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // leftover gap the next item cannot use
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportional to open bins and mean residual
        score += 15.0 + 4.0 * open_bins_count as f64 + 0.3 * mean_residual + 20.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer tighter fits overall
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
