    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // penalize leftover after hypothetical next placement
            let chain_residual = post_residual - next_item_size;
            score += chain_residual as f64 * 0.5;
            // bonus if chain leaves small residual
            if chain_residual < 10 {
                score -= 50.0;
            }
        } else {
            // next item can't chain here; penalize proportionally
            score += 20.0;
        }
