    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless item is huge relative to residual pattern
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && item_size >= 60 {
            score -= 100.0;
        }
    }

    // Slight preference for tighter bins (small pre-residual)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item cannot fit in the post-residual, penalize slightly;
    // if it fits perfectly, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a new bin only when the best existing fit is bad.
    if bin_residual == bin_capacity {
        let openness = 1.0 - (step_index as f64) / (total_items.max(1) as f64);
        // Early in stream, new bins are cheap; later, discourage waste.
        score += 35.0 * (1.0 - openness) + 0.4 * open_bins_count as f64;
        if item_size >= 60 {
            score += 15.0; // big items keep fresh bins useful
        }
    } else {
        // Favor bins whose residual deviates from the mean (consolidate outliers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Prefer fuller bins slightly as stream progresses.
        score -= (bin_capacity - bin_residual) as f64 * 0.02 * ((step_index as f64 + 1.0) / (total_items.max(1) as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness * (1.0 + progress);

    // Penalize large post-residual non-linearly (dead space that likely can't be reused)
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / bin_capacity as f64;

    // Reward exact or near-exact fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let reuse = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * reuse * (0.5 + progress);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize leaving residuals smaller than the next item
        score += 10.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (fill fuller bins first)
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev * (1.0 - progress);

    // New-bin candidate: penalize mildly, more when good fitting bins exist or early in stream
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class: fraction of capacity left after placement
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that fall into "dead space" classes:
    // residuals smaller than the minimum item size (1..=10) are unusable
    if post_residual < 10 {
        score += 500.0;
    }

    // Modulo-class logic on post_residual: residuals that are multiples
    // of common item sizes (10, 20, 25, 50) are more likely to be filled later
    let harmonic_bonus = if post_residual % 50 == 0 {
        40.0
    } else if post_residual % 25 == 0 {
        30.0
    } else if post_residual % 20 == 0 {
        25.0
    } else if post_residual % 10 == 0 {
        20.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 300.0;
        } else {
            let chain_waste = post_residual - next_item_size;
            score -= 50.0 - (chain_waste as f64).min(50.0);
        }
    } else if next_item_size > post_residual {
        // next item cannot chain here; penalize large leftover
        score += frac * 30.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all too fragmented (all open bins leave large unusable gaps)
    if bin_residual == bin_capacity {
        let fragmented = mean_residual > 0.0 && mean_residual < 15.0;
        if fragmented {
            score -= 100.0; // open bins are nearly full anyway
        } else {
            score += 60.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Late in the stream, consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot fit even the smallest plausible item (<= 10)
    // is pure waste; a residual in the "dead zone" (1..=9) is heavily taxed.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // Moderately small gaps are risky too.
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 * (1.0 - fit_ratio.min(1.0));

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure plus expected waste.
        score += 30.0 + pressure * 2.0;
    } else {
        // Existing bin: slight reward proportional to pressure to consolidate load.
        score -= pressure * 0.5;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement strands space the next item could have used elsewhere.
        score += 5.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first),
    // keeping large-residual bins flexible for larger future items.
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (dead space = 0)
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward scaled by how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does NOT fit in the leftover: penalize large leftovers
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit, reward any fit
        score -= 30.0;
    }

    // Reward tight fits relative to mean residual across open bins
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) < mr {
        score -= 0.5 * (mr - post_residual as f64);
    } else {
        score += 0.3 * ((post_residual as f64) - mr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (fitting_bins_count as f64).min(3.0);
        score += 55.0 + 40.0 * (1.0 - progress) - 10.0 * pressure;
        // allow new bin if item is huge and would leave tiny unusable gap elsewhere
        if item_size >= 80 {
            score -= 70.0;
        }
    }

    // Slight penalty for leaving small awkward gaps (1..10) that rarely fit items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, penalize awkward mid-range leftovers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tightness = 1.0 - pr / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot host the next item (lookahead-aware).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            // leftover too small for next item -> dead space penalty, scaled by how close it is
            let waste = (nxt - pr) / nxt;
            score += 25.0 * waste;
        } else {
            // leftover can host next item: reward proportional to how well next fits
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack.min(1.0));
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is expensive; penalize it
    // moderately, more when many bins are open (consolidation pressure) and
    // early in the stream when consolidation is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // If current item is huge, a fresh bin is actually attractive.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Global fragmentation pressure: if mean residual is high, prefer bins
    // that absorb more space (i.e., larger item placement reduces waste).
    let fill_ratio = item_size as f64 / cap;
    score -= 8.0 * fill_ratio * (mean_residual / cap).min(1.0);

    // Mild late-stream consolidation: as the stream ends, prefer filling
    // existing bins tighter to avoid straggler bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like coupling
    score -= poly * (pr * pr / (cap * cap)) * 30.0;

    // Penalize very small dead space more as stream progresses (non-linear)
    let dead = if pr > 0.0 { (cap / pr).ln() } else { 10.0 };
    score -= dead * (0.5 + t);

    // Reward tight fits: quadratic in utilization
    let util = 1.0 - base;
    score -= util * util * item_size as f64 * 0.5;

    // Last-chance bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - t * 0.3);
    }

    // Lookahead coupling: reward leaving space for the next item (smooth)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mean-residual interaction: prefer bins close to mean residual (quadratic)
    let dev = (pr as f64 - mean_residual) / cap;
    score += dev * dev * 20.0;

    // Mild penalty for bin proliferation
    score += (open_bins_count as f64).ln() * 2.0 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are "harmonic"
    // and more likely to be filled by future items from a decimal-ish distribution.
    let harmonic = if post_residual % 10 == 0 { 0.0 } else { 1.0 };
    score += harmonic * (post_residual as f64) * 0.35;

    // Integer-division thresholds: classify post_residual into dead-space bands.
    let dead_band = post_residual / 25; // 0: tight, 1: medium, 2+: very loose
    score += dead_band as f64 * 4.0;

    // Reward near-perfect fits strongly.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this bin becomes a perfect two-item chain — heavily favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let lookahead_post = post_residual - next_item_size;
            if lookahead_post % 10 == 0 {
                score -= 15.0;
            }
            score += lookahead_post as f64 * 0.25;
        } else {
            // Next item won't fit here; penalize slightly if post_residual is small
            // (wasted potential) but less if it's already dead space.
            if post_residual < 10 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // item is huge relative to capacity or all open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if item_size >= 70 || (fitting_bins_count > 0 && mean_residual < item_size as f64 + 5.0) {
            score -= 20.0;
        } else {
            // Prefer reusing an existing bin when a reasonable fit exists.
            score += 30.0 + fragmentation * 0.5;
        }
    }

    // Modulo arithmetic on item size: items in "harmonic" classes (multiples of 10, 20)
    // pack predictably; slightly reward bins whose post_residual shares the item's class.
    if item_size % 10 == 0 && post_residual % 20 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty proportional to number of open bins to discourage sprawl
    // when this placement leaves lots of residual behind.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals that are too small to hold even the smallest item are pure waste.
    if post_residual < 10 {
        // Dead space: penalize harder the smaller it is (it can never be used).
        score += 40.0 + (10.0 - post_residual as f64) * 6.0;
    } else if post_residual == 0 {
        // Perfect fill is ideal.
        score -= 30.0;
    } else {
        // Usable residual: reward proportional to how reusable it is.
        // A residual that can hold the next item is valuable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0 + (post_residual as f64 - next_item_size as f64) * 0.15;
        }
        // Residuals just above a "hard to pair" size band (e.g. >50) are less attractive.
        if post_residual > 50 {
            score += (post_residual as f64 - 50.0) * 0.25;
        }
    }

    // --- Tightness reward: fraction of bin consumed ---
    let fill_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_frac * 25.0;

    // --- Open bins pressure ---
    // Encourage using existing bins when many are open; encourage opening a new bin
    // (empty candidate has post_residual == bin_capacity) when few are open.
    let pressure = (open_bins_count as f64).ln() * 4.0;
    if bin_residual == bin_capacity {
        // New bin candidate: its base post_residual is large, so subtract pressure
        // to make it competitive when open bins are few.
        score -= pressure * 0.6;
    } else {
        score -= pressure;
    }

    // --- Last-chance bin: strongly favor filling it rather than leaving it stranded ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- Mean residual coupling: penalize deviating far from the fleet mean ---
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * 0.08;

    // --- Lookahead guard: if next item cannot fit after placement and this bin
    // would be left with an awkward gap, penalize. ---
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // reward proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does NOT fit here: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 15.0 + 0.5 * over;
        }
    }

    // Prefer tighter fits overall: small post_residual is good (already baseline),
    // but add nonlinear penalty for large dead space.
    let pr = post_residual as f64;
    if pr > 0.0 {
        score += 0.15 * pr * pr / bin_capacity as f64;
    }

    // Relative-to-mean coupling: a bin with residual far above mean is "loose";
    // placing here when it's much looser than average wastes space.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no good fit exists elsewhere. Penalize it moderately so existing bins win,
    // but less when the item is huge (poor fit candidates everywhere).
    if bin_residual == bin_capacity {
        let base = 35.0;
        let huge_item_bonus = if item_size > 70 { 25.0 } else { 0.0 };
        let many_open_penalty = 2.0 * open_bins_count as f64;
        score += base + huge_item_bonus + many_open_penalty;
    }

    // Late-stream consolidation: near the end, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: strongly reward bins where the next item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize mildly, more if this was a tight fit.
            score += 8.0 + 0.1 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when
    // open bins are fragmented (high mean residual spread) or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Early stream: opening new bins is cheap and flexible.
        // Late stream: prefer reusing unless item is large relative to mean residual.
        let new_bin_bias = 30.0 * (1.0 - progress) + 0.3 * item_size as f64 - 0.2 * fragmentation;
        score += new_bin_bias;
        // Large items with no good fit: opening a fresh bin is attractive.
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    } else {
        // Reward using bins whose residual is close to item size (best-fit flavor).
        let fit_gap = (bin_residual - item_size) as f64;
        score += 0.15 * fit_gap;
        // Penalize bins that deviate strongly from mean residual (keeps pool uniform).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Time horizon: as stream progresses, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open (encourage filling existing ones).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer small post residual, with a non-linear convex penalty
    let mut score = pr * (1.0 + 0.02 * (pr / cap).powi(2));

    // Smooth coupling: as stream progresses, penalize large residuals more strongly
    score += 0.35 * (pr / cap) * (pr / cap) * (1.0 + progress) * cap * 0.1;

    // Perfect-fit reward (smooth bump around small residuals)
    score -= 12.0 * (-(pr as f64) / 8.0).exp();

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 8.0 * gap * gap * cap;
        // Reward leaving exactly enough room for the next item
        score -= 6.0 * (-(pr - nxt).abs() / 10.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when many bins are open and residual is wasted
    score += 0.05 * (open_bins_count as f64) * (pr / cap) * (1.0 - progress);

    // Encourage tighter-than-mean fits
    score += 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot width" class the leftover belongs to.
    // Classes via integer division thresholds (capacity fractions).
    let pr = post_residual;
    let class = match pr {
        0 => 0u32,                       // perfect fit: best possible
        1..=10 => 1,                     // tiny dead space
        11..=25 => 2,                    // small-item slot
        26..=50 => 3,                    // medium slot
        _ => 4,                          // large slot (mostly empty)
    };
    score += match class {
        0 => -60.0,
        1 => 8.0,
        2 => 0.0,
        3 => -6.0,
        _ => 5.0,
    };

    // Modulo arithmetic coupling: leftover that is a multiple of common small sizes
    // (e.g. divisible by 10 or 5) is more reusable.
    if pr > 0 {
        if pr % 10 == 0 { score -= 10.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        // penalize awkward leftovers (prime-ish, coprime with small sizes)
        if pr % 10 != 0 && pr % 5 != 0 && pr % 2 != 0 { score += 3.0; }
    }

    // Lookahead: does next item fit into the post residual? Harmonic class match.
    if next_item_size > 0 && next_item_size <= pr {
        // exact-ish lookahead fit is excellent
        if pr == next_item_size { score -= 35.0; }
        else if pr - next_item_size <= 10 { score -= 18.0; }
        else { score -= 6.0; }
    } else if next_item_size > pr {
        // next item cannot use this leftover: penalize proportional to wasted potential
        score += (next_item_size - pr) as f64 * 0.25;
    }

    // Last chance: only this bin can fit the item -> strong bonus unless leftover is huge waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        // prefer new bin for big items when existing bins are fragmented
        score += 25.0;
        score -= tightness * 30.0;
        if fitting_bins_count == 0 { score -= 50.0; }
        // late in the stream, avoid opening unnecessary bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 10.0; // existing bins have room; don't open
        }
    }

    // Slight preference for tighter bins overall (less residual before placement).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Mean-residual coupling: bins far below mean residual are "odd" bins; slight nudge.
    score += (mean_residual - bin_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 1 {
        score += 1000.0;
    }
    // Dead-space curve: penalize small non-zero residuals super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let dead = (bin_capacity as f64 * 0.25 - pr).max(0.0);
        score += 3.0 * dead * dead / bin_capacity as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover -> dead space likely
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: apply pressure + require that no open bin fits well.
        score += 40.0 + pressure * 5.0;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= pressure * 2.0;
        // Prefer bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += tightness * 15.0;
        // Slight preference for bins below mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that can host the next item exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - 0.5 * slack;
        } else {
            // next item can't fit here: penalize leftover dead space
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize new-bin candidate unless current bin is a poor fit
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score += 50.0 + 0.4 * waste;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0; // fresh bin can host next item too
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress) * (open_bins_count as f64 / 50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Penalize post-residuals that are small-but-unusable dead space
    // (below the minimum item size); perfectly full bins are fine.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins whose residual is closest to item size.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward; if post-residual can't fit next item but bin could have,
    // consider mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement "consumes" a bin that the next item could use.
            score += 10.0;
        }
    }

    // Global state: when many bins are open with large mean residual,
    // encourage consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins have slack
        // and early in the stream; slight discount late when fragmentation high.
        score += 25.0 + 20.0 * (1.0 - progress)
            + 0.3 * mean_residual * (open_bins_count as f64).sqrt();
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    } else {
        // Existing bin: mild reward when its residual is below mean residual
        // (i.e., it's one of the fuller bins — good consolidation target).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
        // Late in the stream, be extra frugal with new bins; prefer best fits.
        score -= 10.0 * progress * tight;
    }

    // Prefer bins whose residual is a "complementary" size to the item
    // (residual close to item size means near-perfect fill).
    let complement = (bin_residual as f64 - item_size as f64).abs();
    score += 0.25 * complement;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Base: raw post residual, with a super-linear penalty on wasted space.
    let mut score = pr + 60.0 * fit_norm * fit_norm;

    // Smooth non-linear coupling of waste with stream progress:
    // later in the stream, dead space becomes increasingly costly.
    score *= 1.0 + 0.8 * progress * fit_norm;

    // Tightness reward: smooth sigmoid-like bonus for very small residuals.
    let tightness = (-pr / 8.0).exp();
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if the next item exactly fills the post residual, big reward;
    // smooth partial credit for close fits.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (-gap / 10.0).exp();
        // Penalize leaving residual that is too small for the next item (near-dead space)
        if (post_residual as i64) < (next_item_size as i64) {
            score += 12.0 * (-((post_residual as f64).max(1.0)) / 15.0).exp();
        }
    }

    // Mild penalty for spreading across many open bins vs consolidating.
    score += 0.05 * open_bins_count as f64 * (1.0 - fit_norm);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps bin population balanced), with smooth quadratic coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Slight preference against opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space?
    // Class 0: perfect fit (0) -> strong reward.
    // Small leftovers (1..=9) are dead space -> penalize.
    // Mid leftovers divisible by common item sizes (10/20/25/50) are reusable -> reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score += 25.0; // dead space penalty
    } else {
        // reusability bonus: leftover divisible by coarse granularity
        if post_residual % 10 == 0 { score -= 12.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 5.0; }
        if post_residual % 50 == 0 { score -= 8.0; }
    }

    // Tight fit reward: fraction of bin consumed
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill;

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0; // chain placement possible
            // extra reward if it fills perfectly too
            if post_residual == next_item_size { score -= 20.0; }
        } else {
            // next item won't fit here; penalize leftovers just below common sizes
            score += 8.0;
        }
    } else {
        // last item: prefer tightest packing
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by stream progress and congestion
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 45.0 + 25.0 * progress;
        if open_bins_count > 4 { new_bin_cost += 10.0; }
        // if mean residual is large, open bins are fragmented -> cheaper to open new bin
        if mean_residual > 40.0 { new_bin_cost -= 15.0; }
        score += new_bin_cost;
    }

    // Mild penalty for many open bins relative to tight fits (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item are unusable dead space -> strong penalty.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0;
    }

    // Non-linear dead-space penalty: mid-size gaps that few item sizes can use.
    let usable = post_residual >= 50 || post_residual == 0;
    if !usable && post_residual >= dead_threshold {
        score += (post_residual as f64) * 0.35;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If next item cannot fit into post_residual but post_residual is small,
    // this placement strands the gap -> mild penalty.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins; penalize opening new bins.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins or huge item.
        score += 25.0 + open_pressure * 4.0;
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: placing into a bin with residual far below the
    // mean tightens the packing; reward that.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    } else {
        score += (-dev) * 0.25;
    }

    // Stream progression: late in the stream, be more conservative about
    // wasting space in open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item also fits in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward proportionally to how well the leftover pairs with the next item.
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 200.0 - pair_waste.min(200.0);
        // Exact two-item fill (item + next == residual) is ideal.
        if post_residual == next_item_size {
            score -= 500.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit in leftover: penalize dead space, worse if tiny.
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += 50.0 + (next_item_size as f64 - dead) * 2.0;
        }
    }

    // Penalize residuals too small for any realistic item (below minimum size 1..100 range floor guess).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit style).
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Slight preference for opening new bins early in the stream when many bins are open
    // and this bin's fit is poor (large post_residual relative to capacity).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base score with mild early-stream bonus.
        score += 20.0 - 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0; // bin will be closed after this placement
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    if open_bins_count > 2 {
        score -= 0.6 * open_bins_count as f64;
    }

    // Global residual pressure: if mean residual is large, avoid wasting it.
    if mean_residual > item_size as f64 {
        score += 0.1 * (mean_residual - post_residual as f64).abs();
    }

    // Time horizon: early in the stream, be conservative (prefer new bins
    // for large items to keep flexibility); late, squeeze everything in.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (bin_residual - item_size) as f64 / bin_capacity as f64;

    // New-bin candidate: mildly penalize so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 14.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let tightness = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr * (1.0 + 0.8 * progress * progress - 0.5 * progress * (1.0 - progress));

    // Reward tight fits, more aggressively later in the stream
    let fit_reward = -8.0 * tightness * tightness * (1.0 + 2.0 * progress);

    // Penalize residual that matches next item size (wasted perfect-fit space)
    let lookahead_penalty = if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1.0 {
        -6.0
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -12.0 } else { 0.0 };

    // Slight penalty for spreading across many open bins
    let spread = 0.15 * open_bins_count as f64 * progress;

    poly + fit_reward + lookahead_penalty + last_chance + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Penalize residuals in "dead zones" — small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // too small for any item (min size 1..100 unknown, but tiny slivers are risky)
    }

    // Modulo-10 class logic: residuals divisible by common item granularities are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Integer division thresholds: large residuals are flexible
    if post_residual >= bin_capacity / 2 {
        score -= 20.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 5.0;
    } else if post_residual > 0 {
        // small residual class: penalize mildly, worse when many bins open
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    // Lookahead coupling: can next_item_size fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or snugly here — reward
            let snug = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 25.0 - snug.min(25.0);
            // harmonic bonus if next fills it exactly
            if next_item_size == post_residual {
                score -= 80.0;
            }
        } else {
            // next item won't fit here; penalize leaving a gap next item can't use
            score += 12.0;
            // worse if this bin was the last chance
            if fitting_bins_count == 1 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current fit is terrible
    if bin_residual == bin_capacity {
        // base neutral; penalize opening new bins when decent fits exist
        if post_residual < bin_capacity {
            score += 30.0;
        }
        // early in stream, opening bins is cheap-ish; late in stream, consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if mean residual across bins is low, a new bin is more attractive
        if mean_residual < 20.0 {
            score -= 25.0;
        }
    }

    // Mild global pressure: many open bins -> prefer tight packing
    score += 0.3 * open_bins_count as f64;

    // Fractional non-linearity on residual fraction
    score += 10.0 * (frac * std::f64::consts::PI).sin().abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize gaps too small for typical items.
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 1000.0;
        }
        // Non-linear penalty for small unusable gaps (below ~10 units).
        if post_residual < 10 {
            score += (10.0 - post_residual as f64) * 8.0;
        }
        // Squared component: tight fits are rewarded quadratically.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward filling bins with high residual (use big gaps first for big items).
    score -= (bin_residual as f64) * 0.05;

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.4;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // the item would leave a large residual in every open bin, or mean residual
    // across open bins is already fragmented.
    if bin_residual == bin_capacity {
        // Base new-bin cost: discourage unless placement elsewhere is bad.
        score += 5.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && (next_item_size as f64) > (post_residual as f64) {
            // Next item won't fit in this fresh bin either after placement;
            // slightly discourage.
            score += 3.0;
        }
        // Early in stream, new bins are cheap; late in stream, consolidation matters.
        score -= (1.0 - progress) * 4.0;
        if mean_residual < item_size as f64 {
            // Open bins are too full on average; a new bin is justified.
            score -= 20.0;
        }
    } else {
        // Prefer bins where the lookahead item still fits after placement.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 6.0;
        } else if next_item_size > 0 {
            score += 4.0;
        }
    }

    // Mean-residual coupling: favor bins whose residual deviates from the mean
    // in the direction of a better fit (larger residual bins get slight boost).
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.08;
