}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below
    // the minimum plausible item size is pure waste.
    if post_residual < 10 {
        score -= 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize leaving residuals that are awkward (just above small sizes).
    for awkward in [11u32, 21, 31, 41, 51, 61, 71] {
        if post_residual >= awkward && post_residual < awkward + 4 {
            score += 6.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves more dead space -> mild penalty
            score += (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; a large post-residual is less useful
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has no scarcity value yet.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins by default; only open a new bin when
        // existing residuals are small or the item is large.
        score += 12.0 + 0.35 * mean_residual;
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Large items benefit from a fresh bin.
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Prefer filling bins whose residual is far below the mean (consolidate
    // small residuals into fewer bins).
    if bin_residual < bin_capacity {
        score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Many open bins: encourage closing out small-residual bins.
    if open_bins_count > 5 {
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap; // 0..1

    // Base: reward small post residual (tight fit), non-linearly.
    let mut score = post.powf(1.3);

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, mild tightness preference; later, strong tightness preference.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Penalize large dead space quadratically when normalized residual is high.
    score += 40.0 * norm_post * norm_post * (1.0 - 0.5 * progress);

    // Lookahead: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let waste_gap = post - nxt;
            score -= 30.0 * (1.0 - waste_gap / cap);
        } else {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for proliferation of open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    // Slight preference for bins with residual near mean (balance residuals).
    let dev = (post - mean_residual).abs() / cap;
    score += 15.0 * dev * dev;

    // New-bin candidate: neutral-ish score so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score = post + 60.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual classes of 10 (capacity/10).
    // Small post-residuals are good (tight fit) -> reward via subtractive term.
    let class = post_residual / 10;
    score -= (10 - class.min(10)) as f64 * 6.0;

    // Dead-space penalty: residuals that are unusable for typical items (1..100)
    // are worst when small but nonzero. Penalize residuals in (0, 10) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual class of the resulting two-step leftover
            let two_step = post_residual - next_item_size;
            score -= (two_step as f64) * 0.3;
        } else {
            // next item won't fit here: mild penalty proportional to overflow gap
            score += ((next_item_size - post_residual) as f64) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline preference only
    // when current bins are very full on average; otherwise discourage opening.
    if bin_residual == bin_capacity {
        if mean_residual < 15.0 {
            score -= 20.0;
        } else {
            score += mean_residual * 1.5;
        }
    }

    // Prefer filling bins with low residual relative to the mean (tightest bins first).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.5;

    // Progress scaling: as the stream advances, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

