    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Next item fits here too; mild bonus proportional to how snugly it fits.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use the leftover; penalize dead space relative to next size.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Prefer bins tighter than the current mean residual (compact packing).
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Perfect closure: item exactly fills the bin.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize opening a new bin slightly, so a decent existing fit wins.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual dominates).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Exact or near-exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_use = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * leftover_use;
    }
    // Penalize leaving a residual that no plausible next item (>=10) can use,
    // i.e. unusable dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
        if fit_ratio > 0.5 {
            score -= 5.0;
        }
    }

    // Penalize new-bin candidate mildly; it should win only when open bins
    // accept the item with large waste.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Opening new bins is more attractive early (more future to fill them)
        // and when many bins are already open with low mean residual.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score += 3.0;
        }
    } else {
        // Prefer bins with residual close to what's needed among open bins;
        // discourage dipping into large-residual bins with tiny items.
        if fit_ratio < 0.25 {
            score += 3.0;
        }
    }

    // Slight preference for filling bins that are already mostly full
    // (keeps large residuals available for large items).
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
