    let norm_post = post_residual as f64 / cap;
    score += 40.0 * norm_post * (1.0 - norm_post) * (0.5 + 0.5 * progress);

    // Reward tight fits with a cubic discount.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - slack * slack);
    } else if next_item_size > post_residual {
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Slight preference for reusing bins over opening new ones as stream progresses.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (denser bins).
    score += 3.0 * ((post_residual as f64 - mean_residual) / cap).max(-1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions and modulo structure
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fills using capacity-fraction harmonics (1/1, 1/2, 1/3, 1/4 of capacity)
    for k in 1..=4u32 {
        let harmonic = cap / k as f64;
        let dist = (pr - harmonic).abs();
        score -= 6.0 / (k as f64) * (1.0 - dist / cap).max(0.0);
    }

    // Modulo classes: post_residual divisible by common item sizes is reusable
    let post = post_residual;
    if post > 0 {
        for m in [10u32, 20, 25, 50] {
            if post % m == 0 {
                score -= 4.0 + (post / m) as f64;
            }
        }
        // Penalize dead space in awkward residue classes (prime-ish / odd small remainders)
        if post < 10 {
            score += (10 - post) as f64 * 1.5;
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size < post {
            score -= (next_item_size as f64) * 0.3;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += ((next_item_size - post) as f64) * 0.15;
        }
        // Harmonic pairing: post_residual + next item near capacity fraction
        let combined = pr + next_item_size as f64;
        for k in 1..=3u32 {
            let harmonic = cap / k as f64;
            if (combined - harmonic).abs() < 5.0 {
                score -= 5.0 / k as f64;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it mildly attractive only when few bins fit or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) * 0.5;
        let fit_pressure = (fitting_bins_count as f64) * 2.0;
        score += 8.0 - progress * 4.0 - pressure - fit_pressure;
        if post_residual == bin_capacity && next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin is good
        }
    }

    // Mean residual context: prefer bins whose residual deviates favorably from mean
    score += (pr - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (min item size is 1, but tiny gaps rarely get filled usefully) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps just above 10 are marginal: moderate penalty proportional to waste.
    else if post_residual >= 10 && post_residual < 20 {
        score += 8.0 + 0.5 * (post_residual as f64);
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin count pressure: prefer filling existing bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // Deviation from mean residual: bins tighter than average are better targets.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: only attractive when open bins are congested and mean
    // residual is small; otherwise penalize opening a fresh bin.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64 - 0.2 * mean_residual;
    }

    // Early stream: slightly favor consolidating items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_bonus = 40.0 / (1.0 + (post_residual as f64 - nxt).abs() / 10.0);
        score -= match_bonus;

        // Perfect chain: item + next item exactly fills the bin.
        if post_residual as f64 == nxt {
            score -= 60.0;
        }
        // Penalize residuals too small for the next item (dead space) unless tiny.
        if (post_residual as f64) < nxt && post_residual > 0 {
            score += 0.25 * (nxt - post_residual as f64);
        }
    }

    // Exact fill is always excellent.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (compact them),
    // penalize dipping into large-residual bins unless fit is tight.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last chance: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if next_item_size > 0 {
            (item_size + next_item_size > bin_capacity) as f64
        } else {
            0.0
        };
        score += 45.0 - 20.0 * progress - 30.0 * pressure;
        if open_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins whose leftover still fits the next item.
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (consolidation pressure).
    score += 0.15 * open_bins_count as f64;

    // Coupling with global mean residual: prefer bins below mean residual
    // (i.e., fuller bins than average) to keep residuals balanced-low.
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);
    score -= 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    // Time-horizon modulation: early in the stream, be more selective about
    // opening new bins; late in the stream, allow new bins more freely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later; also penalize if
        // open bins exist that could fit (fitting_bins_count > 0).
        score += 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 8.0 * (1.0 - progress) + 2.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 15.0; // next item needs a fresh bin anyway
        }
    }

    // Prefer using bins with residual close to item size (perfect packing).
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += 5.0 * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = r * (1.0 + 0.8 * rn * rn);

    // Polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are more tolerable; late in the stream,
    // punish leftover space increasingly (quadratic/cubic coupling).
    let prog_term = 1.0 + 2.5 * progress * progress + 3.0 * progress * progress * progress;
    score += rn * rn * cap * prog_term;

    // Reward tight fits: bonus when post_residual is small relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 8.0 + 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: mildly penalize leaving awkward gaps.
        score += 4.0 * (r / cap);
    }

    // Mean-residual coupling: penalize bins far below mean residual (odd gaps),
    // smooth quadratic deviation.
    let dev = r - mean_residual;
    score += 0.05 * dev * dev;

    // Mild bonus for consolidating into many open bins.
    score -= 0.5 * open_bins_count as f64;

    // New-bin candidate: neutral baseline with slight late-stream penalty.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + prog_term) + 25.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bands capture "usable" residual sizes
    let post = post_residual as i64;
    let class = post % 10;

    // Penalize residuals that fall into "dead zones" (1..9) more strongly when small
    if post > 0 && post < 10 {
        score += 12.0 - (post as f64); // tiny unusable slivers are bad
    }

    // Reward post_residual that is an exact multiple of common item granularities
    if post % 25 == 0 {
        score -= 6.0;
    } else if post % 10 == 0 {
        score -= 3.0;
    }

    // Perfect fit: huge reward
    if post == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // next item fits: reward proportional to how well it fills afterwards
        let after = post_residual - next_item_size;
        if after < 10 {
            score -= 15.0;
        } else {
            score -= 8.0 * (1.0 - (after as f64) / bin_capacity as f64);
        }
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // unreachable guard
    }
    if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: penalize small leftovers that strand space
        score += 5.0 * (post_residual as f64) / 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline cost of opening a bin; make it attractive only when
    // the item is large relative to capacity or existing bins are crowded
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - 30.0 * frac; // ~70 for small items, ~50 for large
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if post > 0 && post < 10 {
            score += 0.0; // fresh bin has full residual, no dead zone
        }
    }

    // Stream progression: later in the stream, be more conservative about opening bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Coupling with mean residual: if this bin's residual is far below mean, it's a good filler
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Slight preference for fuller bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item (1..100,
    // but small gaps below ~10 are almost never fillable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver: strong penalty
    } else if post_residual >= 10 && post_residual < 25 {
        // Small gaps: risky, may become dead space depending on remaining stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Later in the stream, small gaps are harder to fill -> penalize more.
        score += 20.0 + 25.0 * progress;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 80.0;
    }

    // Exact match with next item: reserve-friendly reward.
    if next_item_size > 0 && post_residual == next_item_size as f64 {
        score -= 45.0;
    }

    // Open bins pressure: discourage spreading across many bins when
    // this placement wastes little; encourage closing tight bins.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
    score += 0.8 * bin_pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., this bin's residual is full capacity and mean residual is small
    // relative to item size, meaning open bins are nearly full / bad fits).
    if bin_residual == bin_capacity {
        let mean_badness = mean_residual.max(0.0);
        // Opening a new bin is penalized mildly by default; the penalty shrinks
        // when open bins have tiny residuals (nothing fits anyway).
        let shrink = (mean_badness / 50.0).min(1.0);
        score += 25.0 * (1.0 - shrink) + 10.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space relative to mean residual across open bins.
    let post_f = post_residual as f64;
    let mean_r = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    score += 0.5 * (post_f - mean_r).max(0.0);

    // Aggressive 2-step lookahead: reward when the next item fits into post_residual.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly consumes remaining space -> strong reward.
            let slack_after_next = post_f - next_f;
            if slack_after_next == 0.0 {
                score -= 60.0;
            } else {
                score -= 30.0 - 0.3 * slack_after_next;
            }
        } else {
            // Next item won't fit here; penalize proportionally to the overshoot,
            // but less if post_residual is small (unavoidable waste).
            let overshoot = next_f - post_f;
            score += 0.4 * overshoot;
            if post_f < 10.0 {
                score -= 5.0; // tiny residual is nearly closed anyway
            }
        }
    } else {
        // Last item: pure tightness reward.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if the item is huge
    // relative to residual space in typical open bins, or no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: capacity minus item (its post_residual),
        // plus a mild exploration penalty that shrinks as the stream matures.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);

        // Prefer opening a new bin when the item is large and would leave
        // an awkward small residual in existing bins.
        if item_size >= 60 {
            score -= 10.0;
        }
        // If next item also nearly fills a fresh bin alongside this one, encourage it.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity && (bin_capacity as f64 - item_size as f64 - next_item_size as f64) < 10.0 {
            score -= 20.0;
        }
    }

    // Mild pressure against accumulating too many open bins with slack.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score += 0.05 * (open_bins_count as f64);
    }

    // Slight preference for tighter fits overall (item fills a big chunk of the bin).
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward perfect/tight fits nonlinearly (waste is super-linearly bad).
    score += (post * post) / cap;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead (k=2): reward if next item also fits in the post residual.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            score -= 25.0;
        } else {
            // Dead space the next item can't use: penalize proportionally.
            score += 0.25 * (post / cap) * 30.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 {
        score += 0.08 * mean_residual;
    }

    // Time horizon: late in the stream, tighten placements to avoid sprawl.
    score += t * 6.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fill_frac = item / cap;
        // Base cost of opening a bin; cheaper only for large items.
        let mut nb = 95.0 - 70.0 * fill_frac;
        // Lookahead synergy: big item + next item packing together.
        if next_item_size > 0 && (next_item_size as f64) <= cap - item {
            nb -= 12.0;
        }
        // If no open bin fits, opening is much more acceptable.
        if fitting_bins_count == 0 {
            nb -= 45.0;
        }
        // Late in stream, avoid opening bins for small items.
        nb += t * 10.0 * (1.0 - fill_frac);
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    let mut score = norm_post;

    // Smooth non-linear coupling: post-residual cost amplified quadratically with stream progress
    score += norm_post * norm_post * (0.5 + 1.5 * progress);

    // Tight fits reward: penalize (subtract) when post_residual is small relative to item
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * norm_item * 2.0;

    // Dead-space penalty: residual too small for typical future items
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powi(3);
        score += dead * 3.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= fit_quality * 1.5;
    } else if next_item_size > post_residual {
        score += 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Mean residual deviation: prefer bins near mean to preserve diversity of residuals
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * dev * 0.5;

    // New-bin candidate handling: make empty bins moderately attractive early, costly late
    if bin_residual == bin_capacity {
        score = 0.4 + 0.8 * progress + 0.05 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items of size <=10 are "perfect fillers".
    // post_residual in 1..=10 is gold (next tiny item can fill it exactly-ish).
    if post_residual >= 1 && post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual <= 30 {
        score -= 3.0;
    } else if post_residual <= 50 {
        score += 4.0;
    } else {
        score += 10.0; // large dead space
    }

    // Modulo-10 harmonic class: residuals divisible by 10 align with common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    // Odd residuals in awkward bands are dead-space prone.
    if post_residual % 2 == 1 && post_residual > 10 && post_residual < 30 {
        score += 3.0;
    }

    // Coupling with lookahead: if next item fits post_residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            if new_post <= 10 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: residual likely stranded
            score += (post_residual as f64) * 0.15;
        }
    } else {
        // last item: fill as much as possible
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish, slightly penalized so decent fits win,
    // but attractive when all open bins leave bad residuals.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 0.5 - (item_size as f64) * 0.2;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0; // room for a bigger follower
        }
    }

    // Progress pressure: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0;

    // Prefer bins below mean residual (keeps residuals balanced toward fillable classes).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward filling bins whose residual is close to item size (tight fit).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }
    // Penalize leaving a gap just slightly larger than the next item (near-dead space).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 5 {
        score += 25.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        let worst_case_dead = if post_residual < 10 { 60.0 } else { 0.0 };
        score = bin_capacity as f64 * 0.9 + worst_case_dead + 2.5 * open_bins_count as f64 - 10.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - match_quality / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize dead space
        score += 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize tiny unusable residuals (dead space < smallest possible item)
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when nothing fits well
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 0.5;
    }

    // Late-stream consolidation: tighten bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.35 * gap;
        // Bonus if post_residual exactly accommodates next item (perfect chain).
        if post_residual == next_item_size {
            score -= 18.0;
        }
    } else {
        // Last item: only tightness matters, slight extra push.
        score -= 6.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are poor fits;
    // scale penalty down early when few bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 + 10.0 * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (fill the emptiest-fitting bins first
    // keeps tighter bins available).
    if bin_residual != bin_capacity {
        let diff = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 8.0 * diff;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;
    // Non-linear polynomial coupling: reward small residuals super-linearly
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);
    // Stream progress: tighten packing preference as stream advances
    score *= 1.0 + 0.8 * t * t;
    // Dead-space penalty grows non-linearly for mid-range residuals
    score += 12.0 * x * (1.0 - x) * (1.0 - x) * t;
    // Lookahead coupling: bonus if next item fits in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 15.0 * (1.0 - pr / (pr + nxt)) * (1.0 - t);
        } else {
            score += 5.0 * x * t;
        }
    }
    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - x);
    }
    // New-bin candidate: penalize unless current residuals are all poor
    if bin_residual == bin_capacity {
        let spread = (mean_residual - cap * 0.5).abs();
        score += 40.0 - 0.5 * mean_residual - spread * t * 10.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: modulo-10 buckets create discrete
    // "resonance" classes. Residuals near multiples of 10 are more likely
    // to be filled by future items drawn from a broad distribution.
    let harmonic = (post_residual % 10) as f64;
    // Penalize residuals in "dead" classes (small nonzero remainders after
    // integer division by 10, e.g. 1..4 -> hard to fill).
    let dead_zone = if post_residual % 10 >= 1 && post_residual % 10 <= 4 { 6.0 } else { 0.0 };
    score += dead_zone;

    // Integer-division threshold: classify post_residual into quarters of capacity.
    let quarter = (post_residual * 4) / bin_capacity; // 0..3
    let quarter_bonus = match quarter {
        0 => -8.0,  // nearly full bin: excellent, pack here
        1 => -3.0,  // small residual: good
        2 => 1.5,   // medium residual: neutral
        _ => 4.0,   // large residual: wasteful unless needed
    };
    score += quarter_bonus;

    // Perfect-fit harmonic: reward residuals that are exactly divisible
    // into likely item sizes (multiples of 5 and 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Coupling with lookahead item: if next item fits exactly into the
    // post residual, strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: mild reward,
            // scaled by how "harmonic" the double residual is.
            let chain_res = post_residual - next_item_size;
            score -= 6.0 - (chain_res % 10) as f64;
        } else {
            // next item won't fit here: penalize slightly, this bin
            // becomes a dead end for the lookahead.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + item_size as f64 * 0.05;
    }

    // New-bin candidate handling: brand-new empty bin. Prefer it only when
    // no open bin offers a tight fit (i.e. item leaves big residual everywhere)
    // or stream is early and spreading capacity is wise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread_bonus = 4.0 * (1.0 - progress) + (open_bins_count as f64).sqrt();
        // Penalize new bin when mean residual across open bins is large
        // (plenty of usable space already exists).
        score = cap - item_size as f64 + spread_bonus + mean_residual * 0.3;
        // If the item is huge relative to capacity, opening fresh bin is fine.
        if item_size as f64 > 0.7 * cap {
            score -= 10.0;
        }
    }

    // Tightness reward: the smaller the post residual relative to item,
    // the better the fit (best-fit core with sharpened scaling).
    score += (post / cap).powi(2) * 10.0;

    // Mean-residual coupling: if this bin's residual deviates favorably
    // (smaller than mean), reward it to consolidate space.
    score -= (mean_residual - post) * 0.15;

    // Modulo-3 class on item size: items in certain classes pair well
    // with residuals in matching classes (empirical harmonic pairing).
    if item_size % 3 == post_residual % 3 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item can ever use are pure waste.
    // Items are >= 1, but a gap smaller than the next item is likely unusable soon.
    if post_residual < next_item_size && next_item_size > 0 {
        score += 12.0 + 0.15 * (post_residual as f64);
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 8.0; // tiny dead gap, hard to fill
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading into many bins
    score += 2.5 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: prefer bins whose residual deviates from mean
    // toward fullness (small residual) when mean residual is high.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bin unless current item leaves a large usable residual
        // and open bins are congested.
        let congestion = (open_bins_count as f64) / (open_bins_count as f64 + 3.0);
        let usable = if post_residual >= next_item_size && next_item_size > 0 { 1.0 } else { 0.6 };
        score += 18.0 * congestion * usable + 10.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 6.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when next item fits perfectly in post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: next item seals this bin
        } else if next_item_size <= post_residual {
            // partial match: reward proportionally to how well next item fits
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fit_ratio;
        } else {
            // next item can't fit here: penalize large dead space slightly
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.5 * mean_gap;

    // Last-chance bin bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        // new bin baseline cost: opening wastes capacity for one item
        score = item_size as f64 * 0.6 + 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere, must open
        } else if fitting_bins_count == 1 {
            score += 40.0; // a last-chance bin exists, prefer it over new bin
        }
        // allow opening new bin if best existing fit would leave big awkward residual
        // (handled implicitly via comparison with open-bin scores)
    }

    // Mild late-stream tightening: consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize leaving dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 25.0; // perfect lookahead match
        } else {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins slightly; penalize bins far below mean residual (fragmentation).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        let poor_fit = if fitting_bins_count > 0 {
            (post_residual as f64 / bin_capacity as f64).max(0.0)
        } else {
            0.0
        };
        // Opening new bin costs; make it worse than a decent existing fit.
        score += 45.0 + 5.0 * pressure - 60.0 * poor_fit;
        // Late in stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress * poor_fit;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // later in stream, prefer tighter packing more aggressively
    let tightness = 1.0 + 0.8 * progress * progress;
    score *= tightness;

    // Non-linear interaction: post_residual vs mean residual across bins
    let mean_gap = norm_pr - mean_residual / cap;
    score += 4.0 * mean_gap * mean_gap * (1.0 + progress);

    // Reward near-perfect fits with a smooth quadratic bonus
    let perfect = norm_pr * (1.0 - norm_pr) * 4.0; // peaks at norm_pr = 0.5
    score -= 6.0 * perfect * (1.0 - progress * 0.5);

    // Last-chance bin: strong smooth penalty for leaving it unused
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Lookahead coupling: smooth reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let next_norm = next_item_size as f64 / cap;
        score -= 5.0 * fits_next * next_norm * (1.0 - next_norm) * 4.0;
    }

    // Mild penalty for many open bins, scaled smoothly by progress
    score += 0.3 * open_bins_count as f64 * (0.2 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: capacity fractions ---
    // Residuals in the lowest "class band" (0..=10) are nearly perfect fits.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted

    // Non-linear waste penalty: small residuals are heavily rewarded,
    // large residuals are quadratically punished.
    score += frac * frac * 40.0;

    // --- Modulo / integer-division classes on post_residual ---
    // Class A: post_residual <= 10  -> "dead space" class, reward strongly.
    if post_residual <= 10 {
        score -= 15.0;
    }
    // Class B: post_residual in 11..=25 -> mid band, mild reward.
    else if post_residual <= 25 {
        score -= 4.0;
    }
    // Class C: post_residual in 26..=50 -> awkward band, penalize (too big for
    // small items, too small for large ones).
    else if post_residual <= 50 {
        score += 8.0;
    }
    // Class D: post_residual > 50 -> half-empty bin, penalize moderately.
    else {
        score += 12.0;
    }

    // Integer division thresholds: quantized classes of post_residual.
    let q = post_residual / 10; // 0..=10 harmonic class
    score -= (10 - q.min(10)) as f64 * 1.5;

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        // Perfect chaining: next item exactly fills this bin.
        if next_item_size == post_residual {
            score -= 30.0;
        }
        // Next item fits exactly (harmonic modulo match on residual).
        else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let nxt_frac = nxt / cap;
            // Reward proportional to how tightly the next item nests.
            score -= (1.0 - (pr - nxt) / cap) * 6.0;
            // Modulo-class harmony: gcd-like alignment of sizes.
            let g = gcd(post_residual, next_item_size);
            if g > 1 && post_residual % g == 0 {
                score -= 3.0;
            }
            let _ = nxt_frac;
        }
        // Next item does NOT fit: this residual may become dead space.
        else {
            score += 6.0;
            // If residual is in the awkward class and nothing follows, extra penalty.
            if post_residual > 25 && post_residual < 50 {
                score += 4.0;
            }
        }
    } else {
        // Last item: prefer the tightest possible fit above all.
        score -= 20.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        // This is the only bin that can hold the item; opening a new bin
        // would waste the entire residual. Reward strongly.
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a fresh bin: base cost so it only wins when open bins fit poorly.
        score = cap * 0.9;
        // Late in the stream, keep bins closed (consolidation matters more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If only this bin fits, opening new is clearly better.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If many bins fit, discourage spreading.
        if fitting_bins_count > 3 {
            score += 15.0;
        }
    }

    // --- Contextual adjustments ---
    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score -= 2.0;
    }
    // If this bin's residual is far below the mean residual, it's already
    // tight — filling it further is good.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

// Helper: gcd for harmonic-class modulo checks (inlined, no external deps).
fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    if bin_residual == bin_capacity {
        score += 25.0 + pressure;
    } else {
        score -= 0.15 * pressure;
    }

    // Lookahead: prefer bins whose leftover could still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (good fill).
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Perfect chaining: next item exactly fills this bin afterwards.
            if diff < 1.0 {
                score -= 35.0;
            } else if diff <= 10.0 {
                score -= 15.0 * (1.0 - diff / 10.0);
            }
        } else {
            // Next item cannot reuse this bin; penalize leaving residual that
            // is too small to be useful (dead space).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 12.0 * (1.0 - dead / 10.0);
            }
            // Bonus if the next item still fits in some other sense: slight
            // penalty reduction when residual is large anyway.
            if dead > next {
                score -= 3.0;
            }
        }
        // Coupling with mean residual: prefer bins that bring residual
        // distribution toward balance, or exploit very large residuals.
        let mr = mean_residual;
        if (post_residual as f64 - mr).abs() < 5.0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize wasting a mostly-empty bin when many bins are open.
    if post_residual as f64 > 0.8 * bin_capacity as f64 {
        score += 8.0;
    }

    // Late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: keep neutral baseline; only attractive when residual
    // is full and item is large (avoid fragmenting many open bins).
    if bin_residual == bin_capacity {
        score += 5.0;
        if item_size > 60 && open_bins_count > 3 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: tighter fit wins (post_residual already encodes this).

    // Lookahead: reward bins whose leftover can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Bonus proportional to how well the next item also fits.
        let next_tightness = (post_residual - next_item_size) as f64;
        score -= 12.0 + 0.25 * next_tightness;
    }

    // Penalize leaving large dead space that nothing useful fits into.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0 + 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer consolidation.
    if open_bins_count > 4 {
        score += 0.8 * (open_bins_count as f64).ln();
    }

    // Time decay: early in stream, be more willing to open new bins
    // (long horizon amortizes); late in stream, consolidate aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * (1.0 - t);

    // New-bin candidate: only attractive when the item nearly fills it,
    // or when open bins are all quite full (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio >= 0.8 {
            score -= 20.0; // big item: fresh bin is great
        } else {
            score += 15.0 + 10.0 * (1.0 - fill_ratio); // small item: avoid waste
        }
        // If mean residual of open bins is large, opening new bins is wasteful.
        score += 0.15 * mean_residual;
    }

    // Mild reward for bins already tighter than the fleet average.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fill = 1.0 - norm_pr;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = norm_pr * (1.0 - 2.0 * t + t * t) + norm_pr * norm_pr * (t - t * t * 0.5);
    score += 8.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    score -= 30.0 * fill * fill * (0.4 + 0.6 * t);

    // Penalize small unusable residuals (dead space), stronger early
    let dead = norm_pr * (1.0 - norm_pr);
    score += 12.0 * dead * (1.0 - t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * fill;
    }

    // Lookahead: reward residual that can fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Slight penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual alignment: prefer bins near mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions (C/8 bands)
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let band = (pr / (c / 8.0)).floor(); // 0..8 harmonic class of leftover space

    // Reward tight fits: small post_residual gets strong discount
    if pr <= c / 16.0 {
        score -= 30.0; // near-perfect fill, dead space negligible
    } else if band <= 1.0 {
        score -= 18.0;
    } else if band <= 2.0 {
        score -= 8.0;
    } else if band >= 6.0 {
        // leaving a huge residual: only fine if it's a fresh bin
        if bin_residual != bin_capacity {
            score += 6.0;
        }
    }

    // Modulo arithmetic on post_residual: dead space that pairs badly with
    // small items (which are typically <= C/4) is penalized
    let small_max = bin_capacity / 4;
    if post_residual > 0 && post_residual < small_max {
        // unusable for a "small class" item unless exactly matching next item
        if next_item_size == 0 || next_item_size > post_residual {
            score += (small_max - post_residual) as f64 * 0.9;
        } else {
            score -= 12.0; // next item exactly plugs the leftover
        }
    }

    // Integer-division threshold on next_item_size classes (C/4 buckets)
    let next_class = (next_item_size as f64 / (c / 4.0)).floor() as u32;
    // If next item is large (class >= 2, i.e. > C/2), prefer keeping big residuals
    if next_class >= 2 && post_residual >= next_item_size {
        score -= 5.0;
    }
    // If next item is small, prefer bins whose residual is small (compact fill)
    if next_class == 0 && next_item_size > 0 {
        score += pr * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Fresh-bin candidate: default neutral; prefer it only when all open bins
    // would leave very poor fits (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        // base cost of a new bin: penalize mildly so it's chosen only when needed
        score += 20.0;
        // but if the stream is early and few bins open, opening is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Coupling with mean residual: if this bin is far below mean residual,
    // it is already fragmented; prefer filling fragmented bins
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    // Progress-based mild consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead space: residuals in 1..10 are nearly unusable (items >= 1, but
    // tiny gaps waste capacity); penalize quadratically within the danger zone.
    if post_residual >= 1 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 3.0;
    }

    // Tight fit reward: the smaller the leftover relative to capacity, the better,
    // with extra reward when the gap is below the typical small-item threshold.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual - next_item_size < 10 {
            score -= 60.0;
        }
    }
    // If next item cannot fit here, mildly penalize (this bin becomes dead-endish).
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Pressure from many open bins: when open_bins_count is large, prefer filling
    // existing bins over opening new ones.
    score += open_bins_count as f64 * 2.0;

    // Mean residual coupling: if this bin's residual is well below the mean
    // (it is one of the fuller bins), favor placing here to consolidate.
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 1.5;

    // New empty bin candidate: base high cost, waived only when nothing else fits.
    if bin_residual == bin_capacity {
        score += 250.0 + open_bins_count as f64 * 5.0;
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // If the item is large, a fresh bin is more acceptable.
        if item_size > bin_capacity / 2 {
            score -= 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward post_residual matching next_item_size exactly ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();

        // Perfect chain fit: post_residual == next_item_size => strong reward.
        if diff == 0.0 {
            score -= 60.0 + 40.0 * progress;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to closeness.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to the lookahead item: penalize unusable gap.
            let gap = nxt - post_residual as f64;
            // Small gaps (< 10) are nearly unusable dead space -> strong penalty.
            if gap < 10.0 {
                score += 25.0 + 0.5 * (10.0 - gap);
            } else {
                score += 0.3 * gap;
            }
        }
    }

    // --- Mean-residual coupling: prefer bins whose resulting residual sits near mean ---
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling: empty bin gets a mild default penalty ---
    // so we only open a new bin when existing fits are genuinely bad (large score).
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
    } else {
        // Reward tighter fits among open bins.
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_frac).powi(6);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + 0.3 * (post_residual as f64);
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // bin stays usable for lookahead item
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_gap = (mean_residual - item_size as f64).abs();
        score += 25.0 - 20.0 * progress;
        score += 0.4 * avg_gap;
        score += 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host next item too
        }
    }

    // Mild preference for bins below mean residual (balance avoidance of fragmentation).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Penalize very small residuals slightly more late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score += 8.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: post residual, with non-linear polynomial shaping.
    // Small post_residual is good (tight fit): reward via quadratic coupling.
    let mut score = post;
    score -= 40.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Penalize dead space that is too small to ever be useful, smoothly.
    let dead_weight = (norm_post * (1.0 - norm_post)).powi(2);
    score += 60.0 * dead_weight * (0.5 + progress);

    // Stream progress coupling: later in stream, prefer tighter packing.
    score += 30.0 * progress * norm_post * norm_post;

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 25.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: avoid worsening an already-fragmented fleet.
    score += 0.15 * (post - mean_residual).abs();

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quarter-band classification.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual <= cap/4  -> usable small pocket, mild reward.
    // Class 2: cap/4 < post_residual <= cap/2 -> mid pocket, neutral.
    // Class 3: post_residual > cap/2 -> wasteful, penalize.
    let q = (cap / 4.0).max(1.0);
    let half = cap / 2.0;

    if post_residual == 0 {
        score -= 30.0; // perfect fit: best possible outcome
    } else if (post_residual as f64) <= q {
        // Small pocket: reward proportionally to how small it is.
        score -= 8.0 * (1.0 - post_residual as f64 / q);
    } else if (post_residual as f64) > half {
        // Large leftover: dead-space penalty, worse the bigger it is.
        score += 6.0 * ((post_residual as f64 - half) / half);
    }

    // Harmonic compatibility: does next_item_size fit into post_residual?
    // Reward placements that leave room for the lookahead item (chain fit).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact harmonic match: next item fills this bin perfectly.
            if next_item_size == post_residual {
                score -= 22.0;
            } else {
                // Reward by fraction of pocket consumed by next item.
                let frac = next_item_size as f64 / post_residual as f64;
                score -= 12.0 * frac;
            }
        } else {
            // Next item cannot follow here: penalize if it could have fit
            // with a different (larger) leftover class.
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * (gap / cap).min(1.0);
        }
    }

    // Modulo-style residual rhythm: leftover mod (cap/10) near 0 means the
    // pocket aligns with typical item granularity (items are multiples-ish),
    // making it more reusable.
    let gran = (cap / 10.0).max(1.0);
    let r = (post_residual as f64) % gran;
    if post_residual > 0 && r < gran * 0.5 {
        score -= 2.0 * (1.0 - r / (gran * 0.5));
    } else if post_residual > 0 {
        score += 2.0 * (r / gran);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or all open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let item_frac = item_size as f64 / cap;
        // Penalize opening a new bin normally; discount when bins are full-ish.
        score += 25.0 - 20.0 * (1.0 - crowding).min(1.0) - 10.0 * item_frac;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
    }

    // Mild preference for the fullest bins (best-fit flavor) via mean pull.
    score -= 0.05 * (bin_residual as f64 - mean_residual).signum() * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Perfect or near-perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer tightest fit relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.4;

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Last-chance bin: penalize opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: discourage spreading across many bins,
    // but encourage opening a fresh bin when existing bins are cluttered.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 40.0;
        }
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Early stream: be slightly more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strong reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect 2-item packing bonus
        score -= 45.0 + 0.5 * slack.max(0.0) - 0.02 * slack * slack;
    } else if next_item_size > post_residual {
        // Next item cannot follow here: penalize leaving a residual that is too small to be useful
        let dead = post_residual as f64;
        score += 0.35 * dead.min(next_item_size as f64 - post_residual as f64);
    }

    // Prefer tight fits relative to mean residual
    score -= 0.6 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let best_lookahead = next_item_size > 0 && next_item_size <= post_residual;
        score += if best_lookahead { 60.0 } else { 12.0 };
        // penalize opening new bins early in the stream
        score += 8.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mild penalty for fragmenting large residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more strongly as item gets larger.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fit_ratio * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;

    // Penalize dead space: small post_residual that can't fit typical future items.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - t);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting the residual.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Prefer bins with residual below mean (consolidate fullness) early on.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff * (1.0 - t);

    // New-bin candidate: penalize opening a new bin unless current residual is poorly usable.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 { (post_residual as f64 - next_item_size as f64).abs() } else { 0.0 };
        score += 25.0 - 20.0 * fit_ratio - 0.1 * poor_fit;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: must open new bin
        }
    }

    // Mild penalty for proliferating bins mid-stream.
    score += 0.05 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;
    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }
    // Penalize new bin when open bins can fit, modulated by post_residual
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 30.0 * (1.0 - progress) - 10.0 * (norm_pr * 0.0);
    }
    // Lookahead: favor bins whose post_residual fits next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 12.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 8.0 * (ns - pr) / cap;
        }
    }
    // Mean residual coupling
    score += 0.1 * (mean_residual - pr).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: leftover that is too small to hold even the smallest
    // plausible item (assume ~1..100, so anything < ~10 is near-waste).
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    } else {
        score -= 2.0;
    }

    // Perfect fit reward: post_residual exactly divisible into harmonic classes
    // (capacity fractions 1/2, 1/4, 1/5, 1/10) are highly reusable.
    let harmonic = post_residual == 50 || post_residual == 25 || post_residual == 20
        || post_residual == 10 || post_residual == 75 || post_residual == 40
        || post_residual == 33 || post_residual == 30;
    if harmonic {
        score -= 15.0;
    }

    // Modulo-based smoothness: leftover divisible by 5 tends to pair with
    // common item sizes; reward divisibility classes.
    let m5 = post_residual % 5;
    score -= match m5 {
        0 => 6.0,
        1 | 4 => 2.0,
        _ => 0.0,
    };

    // Integer-division threshold: leftover in [next_item_size, next_item_size + 15]
    // can host the lookahead item -> strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual - next_item_size < 15 {
            score -= 8.0; // near-exact two-item chain
        }
    } else if next_item_size > 0 {
        score += 5.0; // lookahead cannot follow here
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; only open a new bin when existing
    // fits are bad (post_residual large) or few bins fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins early; allow late when mean residual is low.
        score += 18.0 - 20.0 * progress + 0.15 * mean_residual;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score += 10.0; // lookahead item pairs well with current item in fresh bin
        }
    }

    // Coupling with mean residual: bins far below mean residual are "emptier"
    // and better to fill; bins above mean are already tight.
    score -= 0.1 * (mean_residual - pr);

    // Slight preference for tighter bins overall.
    score += 0.02 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the minimum item
    // size are unusable "dead space". Penalize them heavily, scaled by how
    // dead they are (closer to 0 residual = more wasted).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0 + (min_item - post_residual) as f64 * 50.0;
    }
    // Soft zone: residuals only slightly above the minimum usable size are
    // risky — a future item likely won't match them exactly.
    if post_residual >= min_item && post_residual <= 10 {
        score += 60.0 * (11 - post_residual) as f64;
    }

    // Reward bins whose residual tightly matches the item (good fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 40.0;

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 300.0;
        } else {
            score -= 30.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this bin's leftover: penalize.
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit
    // would leave bad dead space; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score -= 150.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        if post_residual == 0 {
            score -= 200.0;
        }
    }

    // Open-bins pressure: mildly prefer consolidating into fewer bins as the
    // stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 2.0;

    // Mild preference for bins below mean residual (fill emptier bins first,
    // keeping tight bins for tight fits).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely matches
    // the next item's size (perfect chaining), penalize large unusable leftovers.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward closeness of match.
            score -= (30.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // Next item won't fit: penalize dead space proportional to leftover.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits now (small post_residual) with a non-linear bonus.
    if post_residual < 10 {
        score -= 25.0;
    } else {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (consolidating
    // space), penalize bins already much emptier than average.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.2 * item_size as f64;
        // But allow new bin if no open bin fits at all.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early in stream: slightly discourage proliferating bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits strongly (non-linear)
    score -= 40.0 * fill * fill * fill;

    // Penalize small dead space less than medium dead space (dead space curve)
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 15.0; // tiny leftover is fine
    } else if dead >= 10.0 && dead < 30.0 {
        score += 8.0; // awkward mid-range gap
    }

    // Lookahead coupling: if the next item fits the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty scaled by how close we were
        score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: prefer tighter bins via base residual
        score += 0.05 * bin_residual as f64;
    }

    // Global state: when many bins are open, prefer consolidation (fill existing)
    score += 1.5 * open_bins_count as f64 * (1.0 - fill);

    // Mean residual pull: bins far from the mean residual get a small penalty
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in stream, be more willing to open new bins (keep bins tidy);
    // late in stream, squeeze everything into existing bins.
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (60.0 - 80.0 * progress);

    // New bin bonus when current item is large relative to capacity
    score += new_bin * 0.2 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, slightly compressed non-linearly
    let mut score = pr - 0.35 * (pr * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less; later, prefer minimizing residual strongly.
    let coupling = 0.9 * progress * (1.0 - progress) * (pr / cap - 0.5).abs() * cap;
    score += 0.6 * coupling;

    // Non-linear reward for post_residual near zero (perfect fit), stronger late in stream
    let tightness = (1.0 - pr / cap).powi(6);
    score -= 18.0 * (0.5 + progress) * tightness;

    // Penalize large dead space with cubic term, weighted by progress
    score += (pr / cap).powi(3) * (20.0 + 30.0 * progress);

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item would fit in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // next item won't fit: penalize leaving residual that is too small to be useful
        score += 4.0 * (pr / cap);
    }

    // Slight penalty when many bins are open and residual is average (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * (1.0 - (pr / mean_residual.max(1.0)).min(2.0) * 0.5);

    // New-bin candidate: make empty bins mildly unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands on a
    // "small dead space" class are penalized, "usable" classes rewarded.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward when the next item fits exactly into the post-residual (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it nests.
            score -= 150.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use this leftover: penalize dead space,
            // worse when leftover is in a "useless" harmonic band.
            let dead = post_residual as f64;
            if post_residual < eighth {
                score += 60.0; // tiny sliver, unusable
            } else if post_residual > quarter * 3 {
                score -= 40.0; // still roomy, fine
            } else {
                score += 25.0 * (dead / cap);
            }
        }
    }

    // Modulo-class logic on post_residual: residuals congruent to small
    // multiples of a base granularity (e.g. 10) are more reusable.
    let base = 10u32;
    let cls = post_residual % (base * 5); // class in 0..50
    if cls == 0 {
        score -= 30.0; // clean multiple of 50: highly reusable
    } else if cls < base {
        score -= 10.0; // near-clean class
    } else if cls > base * 4 {
        score += 8.0;  // ragged class
    }

    // Integer-division thresholds: residual usable by typical item sizes.
    let fits_mid = post_residual / 20; // how many "medium" 20-slots remain
    score -= 20.0 * fits_mid as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: prefer it only when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base preference for fresh bins slightly worse than a decent fit.
        score -= 50.0;
        // But if many bins are open and mean residual is small, opening fresh
        // is attractive for future large items.
        score -= 30.0 * (mean_residual / cap).min(1.0);
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 40.0; // next big item: fresh bin valuable
        }
    } else {
        // Penalty for spreading across too many open bins.
        score += 2.0 * open_bins_count as f64;
    }

    // Stream progression: early on, keep bins tight; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * progress * (post_residual as f64 / cap);

    // Prefer bins below mean residual (tighter bins) mildly.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest item (1) are
    // impossible, but gaps that no realistic item can use are dead weight.
    // Penalize small-but-nonzero post_residuals harshly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fit: strongly favored
    }

    // Reward residuals that remain usable for future items (>= 10).
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Open-bin pressure: prefer filling existing bins over spawning new ones.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits (gap smaller than next item), slight penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mean residual coupling: when open bins are already slack, avoid adding
    // another slack bin; when residuals are tight, be more forgiving.
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent fit (large post
    // residual waste elsewhere) or when stream is early and slack is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a new bin.
        score = bin_capacity as f64 * 0.9;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        score -= (1.0 - progress) * 20.0;
        // If the item would leave a terrible gap in an existing bin, new bin wins.
        if post_residual < 10 && fitting_bins_count >= 1 {
            score -= 25.0;
        }
        // If many bins are open, discourage proliferation.
        score += open_bins_count as f64 * 3.0;
        // If next item is large, a fresh bin may serve it better.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match with the next item: this bin becomes ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match with next item (small gap).
    else if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 && gap <= 10.0 {
            score -= 25.0 - 2.0 * gap;
        }
    }

    // Penalize unusable dead space relative to the mean residual of open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    }

    // Small residuals are dead space unless they exactly match plausible next items.
    if pr < 10.0 && pr > 0.0 {
        score += 20.0;
    }
    if pr == 0.0 {
        score -= 15.0; // perfectly closed bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Discourage opening a new bin when decent fits exist, especially late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin still useful for lookahead
        }
    }

    // Slight preference for tighter bins overall.
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize residuals that are too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // moderately awkward
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            score -= 12.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            score += 4.0;
        }
        // Perfect two-item chain: item then next item fills bin
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin
        score += 15.0;
        // Cheaper to open bins early when stream is long (amortization)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Penalize new bins when many bins already open (fragmentation)
        score += 2.0 * open_bins_count as f64;
        // If the current bin would leave a very small residual elsewhere, new bin is fine
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins among open ones (deviation from mean residual)
    if !is_new_bin {
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.15 * dev;
    }

    // Slight global pressure: when many bins are open, consolidate
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress - 0.6 * progress * progress + 0.4 * progress * progress * progress);

    // Penalize dead space more as stream progresses (residual squared term)
    let dead = norm_pr * norm_pr * (0.5 + 1.5 * progress);

    let mut score = poly + dead;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    let tight = (1.0 - norm_pr).powi(3);
    score -= 2.0 * tight * (0.5 + 0.5 * progress);

    // Last-chance bin: smooth exponential pressure to use it
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - (-norm_pr).exp());
    }

    // Lookahead coupling: reward bins whose post residual fits next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= 0.8 * fit_frac * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 0.4 * (next_item_size as f64 / cap) * progress;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let cap = bin_capacity;

    // Reward exact-fitting residuals (perfect pack).
    if pr == 0 {
        score -= 60.0;
    }

    // Dead-space classes: residuals that few item sizes can fill are bad.
    // Class A: tiny unfillable slivers (1..=9) -> heavy penalty.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Class B: residuals in awkward mid-band (10..=24) -> moderate penalty.
    if pr >= 10 && pr <= 24 {
        score += 8.0;
    }

    // Harmonic bonus: post_residual divisible by common item-size classes
    // (mod 10 / mod 5 structure) keeps the bin reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residual: scale reward by tightness
            let leftover = (pr - next_item_size) as f64;
            score -= 18.0 * (1.0 - leftover / cap as f64);
        } else {
            // next item won't fit here: penalize slightly, more if this bin
            // ends up with a small useless remainder.
            if pr < next_item_size && pr < 15 {
                score += 10.0;
            }
        }
    } else {
        // Last item: prefer filling bins as full as possible.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Make the empty bin mildly unattractive
    // by default; reward it when the item is large relative to capacity.
    if bin_residual == cap {
        // base cost of opening a new bin
        score += 15.0;
        // large items (harmonic class >= half capacity) justify fresh bins
        if item_size * 2 >= cap {
            score -= 25.0;
        }
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if many bins are open and mean residual is small, avoid new bins
        if mean_residual < item_size as f64 {
            score += 5.0;
        }
    }

    // Mild preference for fuller bins (tighter fits) overall.
    score -= (cap - bin_residual) as f64 * 0.05;

    // Slight penalty for spreading across many bins when mean residual is high.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // Gap too small for any item (min size 1..100, but tiny gaps are waste)
        score += (10.0 - pr) * 8.0;
    } else if pr == 0.0 {
        // Perfect fit: strong reward
        score -= 60.0;
    } else {
        // Larger gaps: mild penalty scaled by how far from full utilization
        score += pr * 0.15;
    }

    // Reward tight fits: fraction of bin consumed by this placement
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 25.0;

    // Open-bin pressure: penalize spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that next item cannot use: penalize
        score += pr * 0.4;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (high open-bin pressure or huge dead space avoided)
    if bin_residual == bin_capacity {
        // Baseline neutral score; discourage unless existing bins are fragmented
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin anyway
        }
        // Early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item fits with room to spare: mild reward proportional to tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally.
        let dead = (next_item_size - post_residual) as f64;
