    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        // Penalize opening new bins when good fits exist.
        score += 10.0 + 8.0 * fitting_bins_count as f64;
        // Late in stream, opening a bin wastes residual; penalize more.
        score += 15.0 * progress;
        // If item is huge relative to capacity and no tight fit, new bin is okay.
        if item_size as f64 > 0.8 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 12.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize waste relative to mean residual of open bins
    score += 0.05 * (pr - mean_residual).abs() * (1.0 + progress);

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 {
