    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Penalize odd/unusable residue classes (pr_class in {1,3,7,9} are awkward leftovers).
    match pr_class {
        0 => score -= 5.0,
        1 | 3 | 7 | 9 => score += 4.0,
        5 => score -= 2.0,
        _ => {}
    }

    // Lookahead harmonic class: if next item exactly fills the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits: reward proportional to tightness of the two-item chain.
        let chain_waste = post_residual - next_item_size;
        score -= 15.0 * (1.0 - chain_waste as f64 / 50.0).max(0.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score = 55.0 + post_residual as f64;
        // If no other bin fits, the new bin must be attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in stream, prefer reusing open bins more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - (bin_residual as f64 / bin_capacity as f64));

    // Mean-residual coupling: if this bin's residual is far below mean, it's a laggard bin; favor consolidating into it.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= 0.15 * residual_gap.min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
