        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        } else if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            // an open bin chains with next item; don't open a new bin
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor small post-residual values.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small leftover is fine (near-perfect fill)
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // awkward gap zone
    } else if post_residual >= 20 {
        score += (post_residual as f64 - 20.0) * 0.15;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - next_fit / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = mean_residual / bin_capacity as f64;
        // Penalize new bins generally, less so when mean residual is low.
        score += 25.0 * (0.4 + crowding) - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
    }

    // Time horizon: late in the stream, consolidate harder into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins below mean residual (balance avoidance of fragmentation).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core waste term: squared normalized post-residual (dead space penalty).
    let pr = post / cap;
    let mut score = post * (1.0 + pr * pr);

    // Smooth stream-progress coupling: as the stream advances, waste becomes
    // increasingly costly (fewer chances to fill gaps later).
    score *= 1.0 + 0.5 * progress * (1.0 - pr);

    // Lookahead synergy: reward if the next item can exploit the leftover space.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let tight = (next_item_size as f64 / post).min(1.0);
        score -= 12.0 * tight * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item cannot use the gap: mild penalty scaled by gap size.
        score += 4.0 * pr * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize moderately so it wins only when
    // all open bins would create worse dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    // Slight preference for bins whose residual deviates favorably from the mean.
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "nice" residue classes (multiples of common item sizes) are reusable.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Reward near-perfect fits strongly.
    if post == 0 {
        score -= 500.0;
    } else if post <= 5 {
        score -= 120.0;
    } else if post <= 15 {
        score -= 40.0;
    }

    // Modulo-arithmetic reusability: leftover divisible by small harmonic
    // bases (10, 20, 25, 50) tends to be fillable by later items.
    let bases: [i64; 5] = [10, 20, 25, 50, 100];
    let mut reusability = 0.0;
    for (i, &b) in bases.iter().enumerate() {
        if post % b == 0 && post > 0 {
            reusability += 60.0 - (i as f64) * 8.0;
        }
    }
    score -= reusability;

    // Penalize awkward dead space: post_residual in (15, 30) is a classic trap.
    if post > 15 && post < 30 {
        score += 35.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if post >= nxt {
            if post - nxt <= 10 {
                score -= 90.0; // next item fills this bin nicely
            } else {
                score -= 25.0;
            }
        } else if post > 0 {
            score += 20.0;
        }
        // Harmonic match: next item size shares residue class with post residual
        if nxt > 0 && post % nxt == 0 && post > 0 {
            score -= 45.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post >= 0 {
        score -= 70.0;
    }

    // New-bin candidate handling: an empty bin should only win when the current
    // fit into open bins is poor. Make the empty bin moderately attractive.
    if bin_residual == bin_capacity {
        score -= 30.0;
        // Prefer opening a new bin early in the stream when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // But if many bins are open with large mean residual, discourage new bins.
        score += (mean_residual / cap as f64) * 25.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / cap as f64;
    score -= 50.0 * fill_ratio;

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residual is large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.5;

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.3;

    // Slight bias against opening a new bin when open bins exist with room.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-miss lookahead fits (post_residual just above next item size).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 20.0 {
            score -= 40.0 * (1.0 - slack / 20.0);
        } else {
            // Dead space that next item cannot use: penalize proportionally.
            score += slack * 0.3;
        }
    }

    // Penalize residuals far from the mean residual (keeps bins balanced).
    score += ((post_residual as f64) - mean_residual).abs() * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins early in the stream when open bins exist.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - progress);
    }

    // Small penalty for leaving tiny unusable fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large leftover dead space more than linearly (wasted capacity).
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * waste * 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // Prefer filling bins that are already mostly full (low residual).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * fill_ratio;
    score += (1.0 - progress) * 4.0;

    // Global state: many open bins with high mean residual -> favor consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 5.0;
    }
    if open_bins_count > 0 && mean_residual < item_size as f64 {
        // Few bins can absorb; opening a new bin is relatively attractive.
        score += 3.0;
    }

    // New-bin candidate handling: an empty bin has huge raw post_residual,
    // but allow opening a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If other bins can fit the item, discourage new bin unless they fit poorly.
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 12.0;
        }
        // Early in stream: new bins are cheaper to open.
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: strong preference for small post-residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: tighten fit preference as stream advances.
    score *= 1.0 + 0.8 * progress * progress;

    // Interaction: post_residual vs mean residual — penalize bins far above average slack,
    // reward bins whose residual is close to the mean (keeps bin pool homogeneous).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // Slight penalty scaled by abundance of alternatives (encourage best-fit discrimination).
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (1.0 + progress);
        } else {
            // Post-residual too small for next item: penalize wasted dead space, worse later.
            score += 6.0 * (1.0 - pr / nxt) * (0.5 + progress);
        }
    }

    // New-bin candidate: make opening a new bin costly unless it enables a perfect fit
    // or the stream is early and we need capacity diversity.
    if bin_residual == bin_capacity {
        let perfect = (item_size as f64 / cap - 1.0).abs() < 1e-9;
        let mut new_bin_score = 60.0 * (1.0 + progress);
        if perfect {
            new_bin_score -= 80.0;
        }
        // Early stream: slightly cheaper to open bins (builds a useful pool).
        new_bin_score *= 1.0 - 0.3 * (1.0 - progress);
        // If many bins already open, opening more is more expensive.
        new_bin_score += 3.0 * (open_bins_count as f64).sqrt();
        // If no open bin fits well (post_residual would be large elsewhere), new bin is competitive.
        new_bin_score -= 0.5 * mean_residual / cap;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which residue band of dead space is created.
    // Classes mod 10: tiny gaps (1..=9) are near-unusable, exact 0 is perfect.
    let residue_class = (post_residual % 10) as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0; // tiny dead slivers are worthless
    } else {
        // integer-division thresholds: usable gap bands
        let band = post_residual / 10; // 1..=9 for C=100
        // gaps >= 10 can host the smallest items; larger bands are more reusable
        score -= band as f64 * 2.5;
        // penalize odd/awkward residues (mod-2 coupling)
        if post_residual % 2 == 1 { score += 1.5; }
    }
    let _ = residue_class;

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a fresh bin wastes the mean residual spread.
    if bin_residual == bin_capacity {
        // penalize opening new bins unless mean residual across open bins is tiny
        score += 30.0 + mean_residual * 0.8 + (open_bins_count as f64) * 1.0;
        // late in the stream, prefer closing existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    }

    // Lookahead coupling: if the next item exactly fits the post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits here: residual is reusable
            let reuse = next_item_size as f64 / post_residual.max(1) as f64;
            score -= reuse * 20.0;
        } else {
            // next item cannot use this residual: dead space penalty scales with closeness
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // mean residual coupling: bins far from the mean residual are slightly discouraged
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are "dead" — penalize them heavily beyond their raw size.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: annihilate the score.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize a gap that almost-but-not-quite fits the next item (likely dead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Open-bin pressure: the more bins already open, the stronger the pull to
    // fill existing bins rather than spawn new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make the empty bin unattractive unless every open
    // alternative is terrible (large mean residual spread / high pressure).
    if bin_residual == bin_capacity {
        score += 120.0 + open_bins_count as f64 * 5.0;
        // Late in the stream, opening bins is less costly (fewer future items
        // to fill them), so ease the penalty slightly with progress.
        score -= progress * 40.0;
        // If mean residual of open bins is already large, a fresh bin is fine.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 30.0;
    }

    // Mild preference for bins with tighter-than-average residual (denser bins).
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += mean_gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // to the next item size (perfect chaining), scaled by lookahead availability.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Extra bonus for an exact match (diff == 0)
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual that is too small for next item (dead space for lookahead)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 20.0;
    }

    // Relative-to-mean residual coupling: prefer bins whose residual deviates
    // usefully from the mean (consolidation of slack).
    let resid = post_residual as f64;
    score += 0.3 * (resid - mean_residual).abs();

    // Penalize leaving large unusable gaps when next item is large
    if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins (lower post_residual relative to capacity)
    score += 0.2 * (bin_capacity as f64 - resid) / bin_capacity as f64;

    // Mild stream-progress scaling: later in the stream, tighten packing more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    // New-bin candidate: make empty bin moderately attractive only when open bins
    // are crowded; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let crowdedness = mean_residual / bin_capacity as f64;
        if crowdedness < 0.5 {
            score -= 15.0 * (0.5 - crowdedness);
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Lookahead: if the next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize leaving large dead space.
        score += 1.5 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild penalty for hoarding, prefer keeping flexible bins open.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (post_residual as f64) - (mean_residual - item_size as f64);
        // Penalize opening a new bin unless existing residuals are small relative to item.
        score += 4.0 + 8.0 * (1.0 - progress) - 0.05 * mean_residual;
        let _ = poor_fits;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        let density = mean_residual / bin_capacity as f64;
        score += 2.0 * density * (open_bins_count as f64).ln();
    }

    // Dead-space penalty: residual below minimum item size is wasted.
    if post_residual < 1 {
        score -= 8.0; // perfect fit bonus
    } else if post_residual < 10 {
        score += 5.0; // unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress
    let p = progress * progress;
    let coupling = 8.0 * p * (1.0 - p) * 4.0; // peaks mid-stream
    score += coupling * norm_pr * norm_pr * cap * 0.25;

    // Tight-fit reward: smooth sigmoid-like term on item_size / residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill * fill * fill;

    // Penalize tiny dead space that wastes bin utility (smooth quadratic)
    if post_residual > 0 {
        score += 6.0 * (1.0 - pr / cap) * (1.0 - pr / cap) * (1.0 - (pr / cap).powi(4));
    } else {
        score -= 15.0; // perfect closure
    }

    // Last-chance bin: reward strongly when only one bin fits
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Mean residual alignment: prefer bins close to mean (smooth quadratic)
    score += 0.5 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate handling: only attractive late or when fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = 1.0 - fill;
        score += 20.0 * (1.0 - progress) * (1.0 - progress);
        score -= 6.0 * progress * poor_fit;
        score += 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small post_residuals are valuable.
    // Class 0: post_residual == 0 -> perfect closure, strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Integer-division thresholds: treat residual in buckets of 10.
        let bucket = post_residual / 10;
        // Penalize "dead" residuals that few item classes can use.
        // Usable classes: residual >= 10 (min item). Modulo harmonic: residuals
        // that are multiples of 10 pair well with common item classes.
        if post_residual < 10 {
            score += 40.0; // unusable dead space
        } else if post_residual % 10 == 0 {
            score -= 8.0; // harmonic residual, aligns with decade item classes
        } else if post_residual < 20 {
            score += 15.0; // awkward sliver
        } else {
            score += (bucket as f64) * 1.5; // larger leftovers mildly penalized
        }
    }

    // Tightness reward: relative fill of the bin by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 30.0;
        } else {
            score -= 12.0;
        }
        // Harmonic bonus: next item + current item sum to a decade multiple.
        if (item_size + next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    }
    // If next item does NOT fit in the post-residual, penalize slightly
    // (chain break), scaled by how close the next item is to fitting.
    if next_item_size > post_residual && next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.15;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity of all open bins.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = bin_capacity as f64 * 0.9;
        // Prefer a new bin when existing residuals are poor fits for this item
        // (item large relative to mean residual) and many bins are open.
        if item_size as f64 > mean_residual * 1.2 {
            score -= 30.0;
        }
        // Late in the stream, avoid proliferating bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If many bins fit the item, opening a new one is wasteful.
        score += fitting_bins_count as f64 * 10.0;
        // If only one bin fits, prefer using it over a new bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Mild preference to fill bins with low residual among open set
    // (encourages closing near-full bins rather than spreading load).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item are heavily penalized.
    if post_residual > 0 {
        // Dead zone: leftover space below the smallest item (1..=10) plus a margin.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 15 {
            score += 25.0;
        } else if post_residual <= 25 {
            score += 8.0;
        }
        // Penalize residuals that cannot fit the lookahead item (wasted slot).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Reward residuals that can exactly host the next item (chain potential).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Perfect fill: strongly rewarded.
        score -= 40.0;
    }

    // Reward tight fits relative to item size (best-fit flavor).
    score -= (item_size as f64) * 0.3;

    // Open-bins pressure: prefer reusing existing bins as the bin count grows,
    // but give last-chance bins (fitting_bins_count == 1) an extra nudge.
    score += open_bins_count as f64 * 0.05;
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the item fits badly
    // everywhere else (i.e., this empty bin has maximal residual and the
    // item is large relative to the mean residual of open bins).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_tightness = if mean_residual > 0.0 {
            item_size as f64 / mean_residual
        } else {
            2.0
        };
        // Open a new bin only for large items or when open bins are too tight.
        if item_frac < 0.5 && mean_tightness < 1.0 {
            score += 45.0; // discourage opening a fresh bin for small items with room elsewhere
        } else {
            score += 5.0; // slight default penalty; reuse when reasonable
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference toward bins with residuals close to the mean (balanced load).
    score += (bin_residual as f64 - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual close to 0)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 25.0 - slack as f64 * 1.5;
            } else {
                score += (slack as f64 - 10.0) * 0.15;
            }
        } else {
            // next item won't fit here: penalize proportionally to the gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.4;
            // but if post_residual is tiny, the bin is "closed" cleanly anyway
            if post_residual <= 8 {
                score -= 10.0;
            }
        }
    } else {
        // last item: maximize tightness aggressively
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer space,
    // filling them tightly is more valuable
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, using it beats opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        // unless the fit is terrible (large dead space), then allow new bin
        if post_residual > 40 {
            score += 35.0;
        }
    }

    // New-bin candidate: mildly penalize so we only open when open fits are poor
    if bin_residual == bin_capacity {
        score += 25.0;
        // early in the stream, opening bins is cheaper (more items to come to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 15.0;
        // if next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Many open bins: prefer consolidating into existing ones
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= (open_bins_count.min(20) as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that cannot fit the next item (lookahead)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (post_residual - next_item_size).min(20) as f64;
        }
    } else {
        // Last item: just fill most-filled bin
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is very fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if mean_residual > 0.0 { (item_size as f64 / mean_residual).min(3.0) } else { 3.0 };
        // Open a new bin when existing residuals are poor fits and many bins open
        score += 15.0 - 10.0 * (1.0 - fragmentation / 3.0) - 4.0 * (open_bins_count as f64 / 20.0).min(1.0) - 6.0 * progress;
        // Large items prefer fresh bins
        if item_size >= 60 { score -= 8.0; }
        if item_size <= 20 { score += 6.0; }
    }

    // Slight preference for bins with residuals near common item sizes
    for anchor in [10u32, 20, 25, 30, 40, 50] {
        if post_residual == anchor {
            score -= 3.0;
        }
    }

    // Mild time pressure: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins far below mean residual (fragmented outliers) slightly
    score += 0.05 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * 0.5;
    score += poly * cap * 0.35;

    // Reward filling bins deeply, more so later in the stream
    let fill = it / cap;
    score -= fill * fill * (0.5 + 1.5 * progress) * cap * 0.25;

    // Lookahead: reward leaving space for the next item
    if nx > 0.0 && nx <= pr {
        score -= (nx / cap) * (1.0 - pr / cap) * 20.0;
    } else if nx > pr && nx > 0.0 {
        score += ((nx - pr) / cap) * 15.0;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 25.0 * progress;
    }

    // Penalize opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - pr_norm) + 15.0 * progress;
        // Allow opening a new bin when existing residuals are all poor
        let gap = (mean_residual - it) / cap;
        if gap < 0.05 {
            score -= 25.0;
        }
    }

    // Mild dispersion penalty relative to mean residual
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity-fraction band does it fall into?
    let quarter = bin_capacity / 4; // 25
    let item_class = item_size / quarter; // 0..3 (small, medium, large, huge)
    let next_class = (next_item_size as u32).saturating_sub(1) / quarter;

    // Reward tight fits: post_residual near 0 or exactly reusable classes
    let perfect = (post_residual == 0) as f64;
    score -= 40.0 * perfect;

    // Harmonic residue classes: post_residual divisible by 25 or 10 is reusable
    let reusable = (post_residual % quarter == 0 || post_residual % 10 == 0) as f64;
    score -= 12.0 * reusable * (post_residual > 0) as f64;

    // Penalize dead space: post_residual too small for any item (min size 1, but
    // practically below the smallest next-item class)
    let min_next = if next_item_size == 0 { 1 } else { next_item_size };
    if post_residual > 0 && post_residual < min_next {
        score += 25.0; // creates unusable dead space
    }

    // Pairing bonus: if next item fits exactly in post_residual (harmonic match)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 / (1.0 + slack / quarter as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when current bin
    // would leave large awkward residue and next item is large.
    if bin_residual == bin_capacity {
        let awkward = post_residual > (bin_capacity as f64 * 0.5) as u32;
        if awkward && next_class >= 2 {
            score -= 20.0; // open fresh bin for big next item
        } else {
            score += 35.0; // discourage wasting fresh bins
        }
    }

    // Late in stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (bin_residual < bin_capacity) as f64;

    // Prefer bins below mean residual (tighter bins get priority)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Modulo threshold: bins whose residual is in [50,75) are prime targets
    let r = bin_residual;
    if r >= 2 * quarter && r < 3 * quarter {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps disproportionately.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += (10.0 - gap) * 6.0; // tiny leftover = wasted capacity
    } else if gap <= 20.0 {
        score += gap * 0.8; // moderate dead space penalty
    } else {
        // Large residual is reusable; slight reward relative to linear baseline
        score -= 12.0;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and encourage filling existing ones.
    let bin_pressure = open_bins_count as f64 / 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual
        score += 30.0 + bin_pressure * 15.0 + mean_residual * 0.3;
        // Allow new bin only if current item is large relative to typical residual
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    } else {
        // Reward placing into existing bins when many are open
        score -= bin_pressure * 3.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item nearly fits but leaves a stranded gap
    if next_item_size > 0 && (post_residual as u32) >= next_item_size.saturating_sub(3)
        && (post_residual as u32) < next_item_size {
        score += 10.0;
    }

    // Stream progression: early on, be flexible; late, pack tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 - progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 30.0 - leftover_after_next as f64 * 0.8;
    }
    // Next item does NOT fit the post residual: penalize proportionally to dead space.
    else if next_item_size > 0 {
        let waste = post_residual as f64;
        score += waste * 0.35;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Penalize residuals far below mean residual (this bin is unusually empty).
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: be more tolerant of opening new bins later, reward consolidation now.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 8.0;

    // Bonus if bin becomes exactly full.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Penalize dead space relative to smallest possible future item (1..100 unknown, use item_size as proxy scale)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 120.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 150.0 - fragmentation.min(150.0);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 40.0; // fresh bin can host pair
        }
    }

    // Time horizon: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.3;

    // Slight preference for fuller bins (low residual before placement)
    score += 0.1 * bin_residual as f64;

    // Many open bins: encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = pr * (1.0 + 1.5 * progress) + 60.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 40.0 * (1.0 - norm_pr).powi(3) * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 25.0 * (1.0 - pr / nxt) * (0.5 + 0.5 * progress);
        } else {
            score -= 10.0 * (1.0 - (pr - nxt) / cap) * progress;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0 * (0.5 + 0.5 * progress);
    }

    // Mild dispersion penalty: avoid draining a bin far below the mean residual.
    score += 5.0 * (mean_residual - bin_residual as f64).abs() / cap;

    // Slight preference to keep number of open bins small early, fill them late.
    score += (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * 10.0 * (1.0 - progress);

    // Smooth new-bin tie-break: only prefer a fresh bin when this one would leave
    // a very small unusable gap and the item is large.
    if bin_residual == bin_capacity {
        score -= 8.0 * norm_item * (0.3 + 0.7 * progress);
        score += 6.0 * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residual mod 10 buckets
    let pr = post_residual;
    let phase = pr % 10;
    // Dead-space penalty: residuals that are "awkward" (small but nonzero) get punished
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Reward exact fits / harmonic alignment: post_residual divisible by 10 or 25
    if pr == 0 {
        score -= 60.0;
    } else if pr % 25 == 0 {
        score -= 20.0;
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else {
        // off-harmonic residual: penalize by distance to nearest multiple of 10
        let d = phase.min(10 - phase) as f64;
        score += d * 1.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr {
            let npr = pr - next_item_size;
            if npr % 10 == 0 || npr == 0 {
                score -= 25.0;
            }
            // penalize if next item would leave tiny dead space again
            if npr > 0 && npr < 10 {
                score += (10 - npr) as f64 * 2.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer filling fuller bins: reward closeness of item to residual
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Stream progression: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    // Penalize bins far above/below mean residual (keep residuals homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let bad_fit = (bin_capacity - item_size) as f64;
        score = 55.0 + bad_fit * 0.5 - crowding * 2.0 + progress * 20.0;
        // discourage opening new bins when a decent fit exists
        if fitting_bins_count > 0 && post_residual as f64 <= mean_residual {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are pure waste.
    if post_residual < 10 {
        score += 1000.0; // unusable gap => catastrophic penalty
    } else {
        // Non-linear penalty growing as residual shrinks toward unusability
        score += (10.0 - post_residual as f64).powi(2) * 2.0;
    }

    // Reward tight fits: fraction of residual consumed
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportionally to number of open bins
        score += open_bins_count as f64 * 8.0;
        // but if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // avoid new bin if mean residual is high (waste exists elsewhere)
        score += mean_residual * 0.5;
    } else {
        // using an existing bin slightly relieves pressure
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        // dead space for the next item: mild penalty scaled by gap
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Early stream: keep bins flexible (penalize leaving tiny residuals early)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item leaves a small dead space
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 30.0 - (after_next as f64).min(30.0);
        // bonus if next-next residual is tiny (tight chain)
        if after_next <= 5 {
            score -= 15.0;
        }
    }

    // Penalize if next item cannot fit in the residual (dead space ahead)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Early stream: slightly prefer filling existing bins densely
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed
    if bin_residual == bin_capacity {
        score += 35.0;
        // allow new bin early when few bins exist
        if open_bins_count <= 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to ever be useful (below min item size).
    if post_residual < item_size.min(10).max(1) {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use the leftover: penalize proportional waste.
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Global state coupling: prefer filling bins when mean residual is high
    // (consolidation) and open bin count is large.
    score -= 0.05 * mean_residual;
    score += 1.5 * open_bins_count as f64;

    // Time horizon: early in the stream, be more willing to open new bins
    // (new-bin candidate is attractive); late in stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
        score += 8.0 * progress;
    }

    // Prefer bins with residual close to item size (best-fit flavor with slack).
    let slack = (bin_residual as f64 - item_size as f64);
    score += 0.1 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear tightness reward: strongly favor small post_residual via cubic coupling.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness * tightness;

    // Smooth stream-progress coupling: later in the stream, tolerate less slack.
    let progress_coupling = 10.0 * (1.0 - progress) * (post / cap) * (post / cap);
    score += progress_coupling;

    // Penalize dead space relative to mean residual of open bins (quadratic interaction).
    let dead = (post - mean_residual).max(0.0);
    score += 0.35 * dead * dead / cap;

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = post - next_item_size as f64;
        score -= 8.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it slightly less attractive unless residuals are all bad.
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly reward tight fits (small post_residual).
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 3.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: does the next item still fit after this placement?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Bonus proportional to how snugly the next item would nest.
        let nest = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - nest / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item would NOT fit: this placement risks dead space.
        score += 25.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Harmonic class logic: classify post_residual into capacity-fraction buckets.
    // Residuals below the smallest item size (or small fractions of C) are dead space.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter {
        // Very small residual: mostly unusable -> penalize proportionally to waste.
        score += (quarter - post_residual) as f64 * 1.5;
    } else if post_residual >= quarter && post_residual < half {
        // Mid-range residual: useful, mild reward.
        score -= 10.0;
        // Modulo-class bonus: residuals that are common item-size multiples
        // (10, 20, 30...) are more likely reusable.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
    } else if post_residual == half {
        score -= 15.0; // exactly half-full bin is a nice harmonic state
    } else {
        // Large residual: bin still roomy; slight penalty to prefer tighter bins.
        score += (post_residual - half) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin.
        score += 90.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 60.0 * fitting_bins_count as f64;
        }
        // If the only fitting "bin" is the new bin, we must open it.
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // Early in the stream, opening bins is cheaper (build a diverse pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // If next item is large and current open bins' mean residual can't host it,
        // opening a fresh bin now is strategically good.
        if next_item_size as f64 > mean_residual {
            score -= 55.0;
        }
    } else {
        // Existing bin: slight preference when its residual is close to mean
        // (keeps bin pool balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
        // Prefer bins among many candidates that leave the smallest waste.
        if fitting_bins_count > 2 {
            score -= 5.0;
        }
    }

    // Small late-stream tightening: near the end, avoid opening bins aggressively.
    if total_items > 0 && step_index + 2 >= total_items && bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0; // tiny sliver: worst outcome
    } else if post_residual < min_useful {
        // perfect fit (post_residual == 0)
        score -= 40.0;
    }

    // Non-linear penalty on wasted fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Reward using bins that would otherwise leave a hard-to-fill residual
    // similar to the current item (good chaining with lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // gap can host the next item: attractive
        } else if post_residual > 0 {
            score += 8.0;  // gap smaller than next item: dead space risk
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it mildly unattractive by default,
    // but attractive when open bins are very full on average.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = bin_capacity as f64 - 15.0 - 10.0 * pressure;
        if next_item_size > 0 && next_item_size >= min_useful && next_item_size <= bin_capacity {
            score += 5.0; // a fresh bin always fits the next item
        }
    }

    // Mild pressure from number of open bins: prefer consolidating
    // into existing bins as the fleet grows.
    score += 0.5 * open_bins_count as f64 * waste_frac;

    // Late-stream tightening: as the stream progresses, dead space matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of next item into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        // Perfect chain (post_residual == next_item_size) is gold
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space creation
        score += 25.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize small unusable post-residuals (dead space)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Prefer tight fits relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or item is huge
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 20.0 * progress;
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    // Slight preference for filling fuller bins as stream progresses
    score -= 10.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64)) * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual aggressively.
    score *= 1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Penalize small unusable dead space (post_residual < typical small item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.6 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 5.0; // dead space that blocks next item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: make empty bins mildly attractive only when current bins
    // would leave large waste or no bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        // Prefer new bin when item is large (little waste left) and many bins open.
        score = waste + 10.0 - 0.5 * item_size as f64 - 0.3 * open_bins_count as f64
            + 5.0 * progress;
        // Discourage hoarding new bins when existing residuals are large.
        if mean_residual > 40.0 {
            score += 20.0;
        }
        // Encourage new bin for huge items that would leave tiny dead space.
        if item_size >= 80 {
            score -= 30.0;
        }
    }

    // Mild global balance: prefer bins below mean residual (fill emptier bins less).
    if bin_residual != bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual with smooth polynomial coupling to stream progress.
    let x = pr / cap; // 0..1
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base: post-residual, damped/amplified by progress polynomial.
    let mut score = pr * (1.0 + 0.6 * p2 - 0.3 * p3);

    // Non-linear penalty for dead space: quadratic in residual, growing with progress.
    score += 40.0 * x * x * (0.5 + 0.5 * progress);

    // Reward tight fits (small post-residual) via smooth interaction.
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - x);
    }

    // Lookahead coupling: if next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits_next = if next_item_size <= post_residual { 1.0 } else { 0.0 };
        score += (1.0 - fits_next) * 15.0 * nx * (0.5 + progress);
        score -= fits_next * 12.0 * nx;
    }

    // Mean residual coupling: penalize bins deviating from mean (keep residuals balanced).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: mild penalty early, reduced late (prefer consolidation early).
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but post_residual that is
    // too small (< smallest item size 1..=10) becomes dead space. Harmonic
    // classes: classify post_residual by integer division into capacity bands.
    if post_residual > 0 {
        let band = post_residual / 10; // 0..10 harmonic classes of dead space
        score += band as f64 * 6.0;
        // Perfect fill is heavily rewarded.
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual < 10 {
            score -= 25.0; // near-perfect fill, still very desirable
        }
    } else {
        score -= 60.0;
    }

    // Penalize bins whose residual is in awkward classes (e.g. residual mod 10
    // leaves remainder that no typical item can consume).
    let awkward = post_residual % 10;
    if awkward > 0 && awkward < 5 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item can fit into the post_residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward if next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the known next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer opening a new bin only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // If existing bins are crowded (low mean residual), opening new is fine.
        if mean_residual < 20.0 {
            score -= 20.0;
        }
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild preference for fuller bins overall (relative fill fraction).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Spread load when too many bins are open with large residuals.
    if open_bins_count > 8 && mean_residual > 50.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Large residual waste relative to capacity: penalize proportionally.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Open bins pressure: discourage spreading when many bins are already open.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: if this bin is far below mean residual, it is a good filler.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Stream progression: later in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), penalize dead space nonlinearly.
    let pr = post_residual as f64;
    score += 0.05 * pr * pr / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // Slack left after hypothetically placing next item too.
            let slack = pr - nx;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            score -= 4.0 * nx / bin_capacity as f64;
        } else {
            // Next item won't fit here: penalize leaving residual just below next size.
            let gap = nx - pr;
            if gap <= 20.0 {
                score += 6.0 * (1.0 - gap / 20.0);
            }
        }
    } else {
        // Last item: any placement fine, prefer exact fit.
        score -= 10.0;
    }

    // Compare post_residual against mean residual: avoid creating outliers of waste.
    score += 0.3 * (pr - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - pr).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists; penalize moderately
    // so it wins only when open bins would waste heavily.
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 5.0; // two identical items pair nicely in a fresh bin
        }
    }

    // Late in the stream, prefer closing bins tightly (avoid stranding small residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: penalize large post-residual quadratically.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 60.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Dead-space penalty: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate: only attractive when existing bins fit badly
    // (post_residual small relative to mean residual) or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins by default; scale with number of open bins.
        score += 150.0 + 8.0 * open_bins_count as f64;
        // Early stream: keep fewer bins, penalize more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 100.0 * (1.0 - progress);
        // But if the item leaves a big hole in any existing bin vs a fresh bin,
        // a new bin becomes relatively better: subtract when item is large.
        score -= 0.8 * item_size as f64;
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 0 {
            score -= 0.6 * next_item_size as f64;
            // If next item could combine with this one's leftover, discourage new bin.
            if next_item_size <= post_residual {
                score += 40.0;
            }
        }
    } else {
        // Lookahead synergy: reward bins whose leftover can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0 + 0.4 * next_item_size as f64;
        }
        // Penalize bins that deviate strongly from mean residual (keep balance),
        // except very tight bins which are good targets.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Prefer bins that fit exactly-ish relative to item size.
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear reward
    let mut score = pr;
    score -= 0.35 * cap * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, moderate residuals are fine; late, waste is heavily penalized
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.4 * p2 + 0.6 * p3);

    // Penalize dead space that cannot fit a typical future item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr > 0.0 && pr < ni {
            score += (ni - pr) * (1.5 + 2.0 * progress);
        }
        // Reward leaving space for the next item
        if pr >= ni {
            score -= 2.0 + 3.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 10.0 * progress;
    }

    // Mild penalty relative to mean residual to balance bins
    score += 0.15 * (mean_residual - pr).abs();

    // New-bin candidate: give it a smooth competitive baseline
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * p2) - 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Perfect-fit harmonic classes: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are highly reusable -> reward them.
    for m in [10i64, 20, 25, 50] {
        if post % m == 0 && post > 0 {
            score -= 6.0 + (m as f64) * 0.08;
        }
    }

    // Dead-space penalty: post_residual in awkward ranges (1..10) is nearly unusable
    // given item sizes >= 1 but typically larger; penalize strongly.
    if post > 0 && post < 10 {
        score += 18.0;
    }

    // Fraction-of-capacity harmonic bands: residual in [0.5C, 0.75C) vs [0.75C, C)
    // — larger residuals are more flexible; reward proportionally with a step function.
    let half = cap / 2;
    let three_quarters = (3 * cap) / 4;
    if post >= three_quarters {
        score -= 8.0;
    } else if post >= half {
        score -= 3.0;
    }

    // Integer-division threshold coupling with next item: if the next item fits
    // exactly into post_residual, big reward (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size as i64 == post {
            score -= 25.0;
        } else if next_item_size as i64 <= post {
            // next item fits: reward based on how "tight" the fit is
            let tightness = (next_item_size as f64) / (post as f64);
            score -= 10.0 * tightness;
        } else {
            // next item won't fit here: mild penalty scaled by how badly it misses
            score += 4.0;
        }
        // Harmonic class of next_item_size: large next items (>= half capacity)
        // favor keeping big residuals free.
        if next_item_size >= 50 && post < next_item_size as i64 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    // It should only win when existing bins are badly fragmented. Penalize the
    // fresh bin mildly when any open bins fit, unless the current bin's post-fit
    // residual is dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * (open_bins_count as f64);
        // If stream is early, opening bins is cheap; reduce penalty.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: when mean residual across open bins is large,
    // we have slack everywhere -> mildly penalize consuming a good bin.
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Small item into large residual: waste of flexibility, penalize when
    // item_size is a small harmonic class (< 20) and residual is large.
    if item_size < 20 && post > (cap * 7) / 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small leftover gaps are unusable for typical items.
        let dead = (post_residual as f64).min(15.0);
        score += dead * dead * 2.0;

        // Reward residual that can still fit a plausible future item.
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64);
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
        // Next item won't fit here; penalize leaving a gap smaller than next item.
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins early; relax late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - progress) * 2.0;
    score += pressure;

    // Mean-residual coupling: if this bin's residual is far below average, it's a tight bin — prefer using it.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.5;

    // New-bin candidate handling: opening a fresh bin is only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins are open (spread load).
        score = 60.0 + open_bins_count as f64 * 0.5;
        if item_size > 70 {
            // Very large items: fresh bin is reasonable.
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: next item fits with small leftover after it
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 200.0 - after_next as f64 * 4.0;
        if after_next == 0 {
            score -= 300.0; // chain of two perfect fits
        }
    }

    // Penalize dead space: post_residual too small for the smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Penalize leaving very large residuals relative to mean residual (wasteful spread)
    if post_residual as f64 > mean_residual + 30.0 {
        score += (post_residual as f64 - mean_residual - 30.0) * 2.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Tight fits are good: reward small post_residual relative to item size
    if post_residual <= item_size / 4 {
        score -= 50.0;
    }

    // Late in the stream, consolidate rather than open new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 30.0;
    } else {
        // New-bin candidate: penalize unless open bins are badly fragmented
        score += 40.0 - 40.0 * progress;
        if mean_residual < item_size as f64 * 1.5 {
            score -= 60.0; // open bins too full, new bin reasonable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post_residual becomes dead space.
    let tightness = if post_residual == 0 {
        -500.0
    } else {
        -(item_size as f64 / bin_residual.max(1) as f64) * 80.0
    };
    score += tightness;

    // Penalize small unusable post_residuals that no typical item can use,
    // unless it's a perfect fit (already handled above).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // reward; if this placement would strand the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if bin_residual >= item_size + next_item_size {
            score -= 10.0;
        } else {
            score += 15.0;
        }
    }

    // Global state: when many open bins exist with large mean residual,
    // prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = (open_bins_count as f64).ln() * 4.0;
    score += open_pressure * (mean_residual / bin_capacity as f64);

    // Time horizon: early in the stream, be conservative (favor new bins for
    // large items to keep flexibility); later, pack aggressively.
    let early = (1.0 - progress).powi(2);
    if item_size > 50 && early > 0.5 && bin_residual == bin_capacity {
        score -= 20.0 * early;
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // New-bin candidate: give it a moderate default so it only wins when
    // existing fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize wasted space, with non-linear (quadratic) penalty on large residuals
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth coupling: penalty on residual shrinks as stream progresses
    // (later in the stream, tight fits matter relatively more)
    let progress_damp = 1.0 / (1.0 + 1.5 * progress);
    score *= progress_damp;

    // Reward tight fits: non-linear bonus when post_residual is small
    let tightness = (1.0 - norm_pr).powi(6);
    score -= 12.0 * tightness;

    // Perfect-fit bonus (post_residual near zero)
    if pr < 1.0 {
        score -= 25.0;
    }

    // Lookahead coupling: penalize leaving residual just below next item size
    // (dead space that next item cannot use), smooth ramp
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 && gap < 40.0 {
            score += 8.0 * (1.0 - gap / 40.0) * (1.0 - gap / 40.0);
        }
        // Reward residual that exactly accommodates next item
        if (gap.abs() as u32) < 1 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for spreading across many open bins vs. consolidating
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: make empty bins moderately attractive
    // only when existing residuals are poor fits
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        score = 45.0 + 0.3 * mean_fit_gap - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: capacity divided into 5 bands.
    // Residuals in the smallest band are "dead space" -> penalize.
    let band = (bin_capacity as f64 / 5.0) as u32;
    match post_residual {
        0 => {
            // Perfect fit: strongly reward.
            score -= 40.0;
        }
        r if r < band => {
            // Dead space: penalize quadratically within the band.
            score += (band - r) as f64 * 0.6;
        }
        r if r < 2 * band => {
            // Mid-low residual: mild reward, can absorb a small item.
            score -= 3.0;
        }
        r if r < 3 * band => {
            // Comfortable residual: neutral.
        }
        _ => {
            // Large residual: slightly discourage (waste of a well-packed bin).
            score += 4.0;
        }
    }

    // Modulo-class coupling: if next item's size class divides the post
    // residual nicely (post_residual % next_item_size is small), reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let m = post_residual % next_item_size;
        score -= (band - m.min(band)) as f64 * 0.25;
        // Exact nesting of the lookahead item is very desirable.
        if m == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this residual anyway; slight penalty for
        // leaving a residual that no small class can exploit.
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize unless residuals elsewhere
    // are genuinely poor. Encourage opening fresh bins early in the stream
    // or when mean residual is tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 25.0 + 20.0 * progress;
        if mean_residual < (band as f64) {
            // All open bins nearly full -> new bin is fine.
            new_bin_score -= 20.0;
        }
        if item_size > 3 * band {
            // Large item into a fresh bin keeps big-item/small-item harmony.
            new_bin_score -= 8.0;
        }
        score = score.min(new_bin_score) + new_bin_score * 0.0;
        score = new_bin_score + (post_residual as f64) * 0.01;
    }

    // Tie-break with open bin count: spreading load slightly preferred
    // when many bins are open (keeps residual diversity).
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate penalty for small-to-medium dead space that few items can use.
    if post_residual >= 10 && post_residual < 25 {
        score += 20.0;
    }
    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space usability: if the lookahead item fits the post residual,
    // the remaining gap is valuable, so reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If lookahead item cannot fit into post_residual, gap may become dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins when not needed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Penalize opening a new bin when a reasonable fit exists elsewhere.
    if bin_residual == bin_capacity && open_bins_count > 0 && post_residual > 20 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by base term.

    // Aggressive 2-step lookahead: strongly reward when the next item
    // exactly fills the post_residual (perfect chain fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        // Perfect lookahead fit bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Next item fits snugly into post_residual
        if next_item_size <= post_residual && (post_residual - next_item_size) <= 10 {
            score -= 5.0;
        }
        // Next item cannot use this residual: penalize large wasted space
        if next_item_size > post_residual && post_residual > 0 {
            let waste = post_residual as f64;
            score += 0.3 * waste;
        }
    } else {
        // Last item: prefer minimal residual overall
        score += 0.1 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        // New-bin candidate: only attractive if post_residual would be tiny
        score += 25.0 - 0.2 * post_residual as f64;
    }

    // Discourage leaving small unusable dead space (<= 10) unless it's a perfect fit
    if post_residual > 0 && post_residual <= 10 {
        score += 6.0;
    }

    // Slight preference to fill earlier bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no plausible item (min size 1..=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward residue.
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer new bins for big items);
    // late in the stream, pack greedily into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += 18.0 - 14.0 * large_item - desperation;
        // Late in the stream, opening new bins is fine since remaining items are few.
        score -= progress * 8.0;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), smoothed non-linearly
    let mut score = 2.0 * norm_pr + 3.0 * norm_pr * norm_pr;

    // Non-linear coupling: post_residual value interacts with stream progress.
    // Late in the stream, waste is more costly (fewer chances to reuse it).
    let coupling = 4.0 * norm_pr * norm_pr * (progress * progress) + 2.0 * norm_pr * progress;
    score += coupling;

    // Dead-space penalty: residuals too small to ever fit typical items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            // This residual can't fit the next item; penalize more as stream advances
            score += 1.5 + 2.0 * progress;
        } else {
            // Reward residuals that can host the lookahead item
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 1.2 * fit_quality * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else if fitting_bins_count > 1 {
        // Among many options, mildly prefer tighter bins (already in norm_pr term)
        score += 0.2 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate (empty bin): discourage unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = if open_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            0.0
        };
        // Opening a bin is attractive when mean residual is small (bins full)
        score = 1.0 - 2.5 * crowd + 1.5 * progress * (1.0 - crowd);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is unbeatable.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the post residual (capacity divided into 10-unit bands).
    let class = post_residual / 10;
    let within = (post_residual % 10) as f64;

    // Reward residuals that form useful harmonic classes: large bands are reusable.
    // Penalize awkward "dead zone" residuals (small but nonzero leftovers).
    if post_residual < 10 {
        // Dead space: nearly unusable given min item size, but keep exact small fits viable.
        score += 60.0 - 3.0 * post_residual as f64;
    } else {
        // Prefer residuals that match common item sizes (multiples of 10) exactly.
        if within == 0.0 {
            score -= 8.0 + class as f64;
        } else {
            score += within * 0.5;
        }
    }

    // Lookahead: if next item fits the post residual, strongly reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.4;
        // Bonus if next item then leaves another clean class.
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover; slight penalty for wasting potential.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If existing bins are nearly full on average, new bin is less wasteful.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate aggressively, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 15.0;
    }

    // Mild pressure toward fuller bins when many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 15.0 * (1.0 - fit_ratio.min(1.0));

    // Last chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> discourage spreading; few -> encourage filling.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 2.0;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits, mild penalty for blocking it.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 6.0;
    }

    // New bin candidate: neutral baseline with slight early-stream openness.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // matches the next item size (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            score -= 500.0;
        } else if diff <= 5.0 {
            score -= 150.0;
        } else if diff <= 10.0 {
            score -= 60.0;
        } else {
            // Penalize residuals that are too small to ever be useful again.
            if pr < nxt && pr < 10.0 {
                score += 40.0;
            }
        }
        // If next item cannot fit in the post-residual, mild penalty unless
        // residual is large enough to be generally reusable.
        if pr < nxt && pr >= 10.0 {
            score -= 10.0; // still usable space for future items
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    // (best-fit style), penalize outliers with excessive space.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make opening a new bin attractive only when no open bin
    // fits well. Penalize new bins when a good existing fit exists.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Early in the stream, opening bins is cheaper; late in the stream,
        // consolidate into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 100.0;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 80.0;
        }
        // If the current item leaves a bad residual in any open bin anyway,
        // a fresh bin may be better (handled by base post_residual comparison).
    }

    // Slight preference for keeping the number of open bins in check.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item;
    // penalize bins that leave a residual that fits nothing.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 22.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0 * tightness;
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // item is large (poor fit elsewhere) or many bins are open with fat residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2);
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let fat_mean = (mean_residual / bin_capacity as f64 - 0.5).max(0.0);
        score += 12.0 * large_item_bonus * (1.0 - crowding)
            + 10.0 * fat_mean
            + 6.0 * (1.0 - progress)
            - 14.0 * crowding;
        // Never open a new bin for a tiny item when alternatives exist.
        if item_size <= 30 && fitting_bins_count > 1 {
            score += 40.0;
        }
    } else {
        // Mild penalty for using very empty existing bins (save them for big items).
        let emptiness = bin_residual as f64 / bin_capacity as f64;
        if emptiness > 0.85 && item_size < 50 {
            score += 5.0;
        }
        // Slight preference for bins below the mean residual (balance load).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, prioritize filling aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, small residuals are acceptable; later, waste is penalized more.
    let pr_norm = pr / cap;
    let phase = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += phase * pr_norm * pr_norm * 40.0;

    // Reward tight fits: coupling between item size and residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * tightness * 12.0;

    // Lookahead: penalize residual that barely fails to fit the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= (gap / cap) * 8.0;
        } else {
            score += (-gap / cap) * 6.0 * (1.0 - phase);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - phase * 0.5);
    }

    // Mild dispersion penalty relative to mean residual
    score += (pr - mean_residual).abs() * 0.15;

    // Prefer reusing bins over opening new ones, slightly stronger early
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - phase);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: penalize dead space in awkward classes
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    // Modulo classes on post_residual (harmonic granularity 10)
    let class = post_residual % 10;
    score += match class {
        0 => -8.0,   // perfect class: residual divisible by 10, very reusable
        1 | 2 => 6.0, // tiny slivers: nearly dead space
        3 | 4 => 3.0,
        5 => -4.0,   // half-class residual, highly reusable
        6 | 7 => 1.5,
        _ => 4.0,
    };

    // Reward tight fits via integer-division thresholds
    if post_residual <= 5 { score -= 12.0; }
    else if post_residual <= 10 { score -= 6.0; }
    else if post_residual > 30 { score += (post_residual as f64 - 30.0) * 0.15; }

    // Fractional residual penalties (non-linear coupling)
    score += frac * frac * 10.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item won't fit here; slight penalty if this bin becomes near-dead
            if post_residual < next_item_size.min(40) { score += 3.0; }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer only when residual would be very small (good fit)
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost + reward proportional to item packing density
        score = 55.0 - (item_size as f64) * 0.5;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // room for lookahead pairing in fresh bin
        }
        if open_bins_count == 0 { score -= 40.0; }
    }

    // Stream progression: later in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += progress * 10.0;
    }

    // Mean residual coupling: prefer bins close to mean residual (balance)
    score -= 2.0 / (1.0 + (post_residual as f64 - mean_residual).abs() * 0.05);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste. Penalize nonlinearly.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual < 20 {
        // Small gap zone: mildly penalize, but keep ordering by residual.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Perfect fit reward: leaving exactly zero or a large reusable residual
    // is good; zero residual is best (bin closes cleanly).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.4;

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit in post residual but fits in current residual,
    // penalize wasting this bin on the current item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 4.0;
        }
    }

    // New-bin candidate: neutral-ish baseline; only attractive when no open
    // bin offers a decent fit (post_residual small on open bins is penalized
    // above, so a fresh bin's full residual stays competitive).
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize wasted space relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post-residual against mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.3 * (mean_residual - pr);
    } else {
        score += 0.2 * (pr - mean_residual);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would
    // leave an awkward residual that likely becomes dead space.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If the item is large relative to capacity, a fresh bin is less bad.
        score -= 0.3 * item_size as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    // Late in the stream, tighten packing: discourage leaving residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.4 * pr;

    // Small penalty scaled by how crowded the bin set already is.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed: time-varying aggressiveness.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Reward tight fits: heavily discount small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize post_residual that is too small to ever be useful
    // (dead space below the minimum item size ~ wasted capacity).
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this placement strongly (pairing bonus).
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 15.0;
        } else if (next_item_size as f64) <= bin_residual as f64 {
            // next item would have fit here only if we place better
            score += 5.0;
        }
        // If next item exactly consumes post_residual, extra reward.
        if next_item_size as f64 == post_residual as f64 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among multiple fitting bins, prefer fuller ones (larger item_size
        // relative to residual = better fill ratio).
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fill;
    }

    // Global state: penalize contributing to bin sprawl when many bins open.
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: if open bins are generally full (low mean
    // residual), opening a new bin is more acceptable; if they are empty,
    // prefer reusing them.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus sprawl penalty.
        score += 30.0 + (open_bins_count as f64) * 1.5;
        // Early in the stream, opening bins is cheaper (exploration);
        // late in the stream, prefer consolidation.
        score -= 20.0 * (1.0 - progress);
        // If mean residual across open bins is small, new bin is justified.
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
        // If next item is large and no bin could hold both, new bin helps.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 6.0;
        }
    } else {
        // Existing bin: slight bonus to reuse, scaled by emptiness of fleet.
        score -= mean_residual * 0.1;
    }

    // Late-stream consolidation pressure: as progress -> 1, penalize
    // leaving large residuals behind (favor closing bins out tightly).
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) coupling.
    let mut score = post + 40.0 * post_norm * post_norm;

    // Smooth interaction of post_residual with stream progress:
    // late in the stream, tight fits matter more (dead space is costly).
    score += 25.0 * post_norm * (1.0 - post_norm) * (0.5 + progress);

    // Penalize opening/using bins when many bins are already open (fragmentation).
    score += 2.0 * open_bins_count as f64 * post_norm;

    // Reward filling bins close to mean residual alignment (smooth coupling).
    let mean_norm = mean_residual / cap;
    score -= 10.0 * (post_norm - mean_norm) * (post_norm - mean_norm).abs();

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let tight = 1.0 - (post - nxt) / cap;
            score -= 30.0 * tight * (1.0 + progress);
        } else {
            score += 5.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post_norm);
    }

    // Slight preference toward existing bins vs. new empty bin (new bin has post == cap).
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Reward near-perfect fits strongly (dead-space minimization, superlinear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Modulo arithmetic on post_residual: leftovers divisible into common item
    // sizes (10/20/25/50) are "harmonic" and reusable.
    let pr_u = post_residual;
    if pr_u % 10 == 0 && pr_u > 0 {
        score -= 25.0;
    }
    if pr_u % 25 == 0 && pr_u > 0 {
        score -= 15.0;
    }
    if pr_u % 50 == 0 && pr_u > 0 {
        score -= 20.0;
    }
    // Awkward primes / odd non-harmonic leftovers are penalized.
    if pr_u % 10 != 0 && pr_u < 20 && pr_u > 0 {
        score += 30.0;
    }

    // Lookahead coupling: can the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic check: next item leaves another usable class.
            let next_left = post_residual - next_item_size;
            if next_left % 10 == 0 {
                score -= 60.0;
            } else {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: leftover likely dead space.
            score += 15.0 + 0.5 * (next_item_size as f64 - pr);
        }
    }

    // Integer-division thresholds on residual fraction.
    let tier = (frac * 4.0).floor() as u32; // 0..=3 quartiles of capacity
    score += match tier {
        0 => -10.0,          // <25% left: tight, good use
        1 => 5.0,            // 25-50%: mediocre
        2 => 12.0,           // 50-75%: wasteful for a small item
        _ => 20.0,           // >75%: nearly empty bin used for a small item
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    // or the stream is early (amortization) and open bins are crowded.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 400.0 } else { 0.0 };
        let crowding = (open_bins_count as f64) * 8.0;
        // New bins are cheap early, expensive late in the stream.
        score = 500.0 + crowding - 200.0 * (1.0 - progress) + scarcity;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0; // big item now, room for next one too
        }
    }

    // Mild preference for bins below mean residual (balance preservation).
    score += 0.3 * (mean_residual - pr).abs().signum() * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste — penalize heavily.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit bonus: filling the bin exactly is ideal.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 15 {
        // Tiny leftover that could still serve small items: mild bonus.
        score -= 8.0;
    }

    // Dead-space pressure scales with stream progression (late stream:
    // prefer tightening existing bins over opening new ones).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.6;

    // Open-bins pressure: when many bins are open, favor placements that
    // close bins out (small post_residual); discourage leaving large gaps.
    let bin_pressure = open_bins_count as f64;
    score += bin_pressure * 0.35 * (post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // unattractive unless no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins already open
        // or when the current item would leave a big gap in an open bin.
        score = 40.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else if post_residual_open_worst(item_size) > 35 {
            // existing fits are poor (would waste > 35); opening is fine
            score -= 10.0;
        }
    }

    // Lookahead coupling: if next item fits in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item barely misses, mild penalty for stranding space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Mean residual coupling: bins far below mean residual are "fresher";
    // prefer packing into bins already below mean (older, emptier slots).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

// helper: worst-case waste if item were placed in any fitting open bin
// (approximated via post_residual passed in; we use a conservative proxy)
fn post_residual_open_worst(item_size: u32) -> u32 {
    // Proxy: assume typical open-bin residual ~ item_size + 30 wasted if
    // poorly fit; grounded heuristic scale, no external state.
    35
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can also fit here: strong reward for tight match
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit after placement: penalize dead space
            score += 0.5 * diff;
        }
        // exact match jackpot
        if post_residual == next_item_size {
            score -= 250.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    let res = post_residual as f64;
    score += 0.3 * (res - mean_residual);

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize new-bin opening unless current bin fit is terrible
    if bin_residual == bin_capacity {
        // new bin: baseline score = full residual; add penalty so it's only
        // chosen when no open bin offers a good fit
        score += 40.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening a fresh bin is attractive if next item is large
            score -= 0.4 * next_item_size as f64;
        }
    }

    // Late-stream consolidation: tighten packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * res;

    // Penalize large wasted fraction of the bin
    score += 0.1 * res * res / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit bonus: strongly reward near-perfect fills
    let tight = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 25.0;
    } else if tight < 0.10 {
        score -= 12.0 * (1.0 - tight / 0.10);
    } else if tight < 0.20 {
        score -= 4.0 * (1.0 - tight / 0.20);
    }

    // Penalize creating dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    }

    // Lookahead: if the next item fits the post-residual, reward leaving that gap;
    // if next item is large and post-residual too small, penalize wasting space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 3.0 + 0.05 * next_item_size as f64;
        } else {
            score += 0.02 * (next_item_size - post_residual) as f64 * (0.5 + progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 0.10 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has a large baseline cost so it is
    // only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0
            + 10.0 * (1.0 - progress)
            + 0.5 * (open_bins_count as f64).sqrt();
        // If mean residual across open bins is large, open bins are wasteful; new bin less bad
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
    }

    // Mild pressure to consolidate into fuller bins as the stream progresses
    score += 0.02 * (bin_residual as f64 - mean_residual) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: minimize wasted space, non-linearly scaled
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (penalize large post_residual)
    let coupling = 1.0 + 1.5 * progress * progress + 0.5 * progress * (1.0 - progress);
    score *= coupling;

    // Reward near-perfect fits smoothly (small post_residual gets extra discount)
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * tightness * progress;

    // Penalize dead space that next item likely can't use (smooth interaction)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap > 0.0 {
            score += 0.35 * gap * (gap / cap);
        } else {
            score -= 2.0 * (-gap / cap);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: mild penalty so we prefer reusing open bins,
    // but relax late in the stream / when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score += 8.0 - 6.0 * progress - 4.0 * crowding;
    }

    // Slight preference for bins tighter than the mean residual (smooth)
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residual divisible by small integers is more "usable"
    for &m in &[5u32, 10, 20, 25] {
        if post_residual % m == 0 {
            score -= 8.0 + (m as f64);
        }
    }

    // Integer-division thresholds on post_residual: dead-space bands
    let pr = post_residual;
    if pr < 10 {
        score += 30.0; // unusable sliver (items >= 10... but sizes 1..100 possible)
    } else if pr < 20 {
        score += 15.0;
    } else if pr < 35 {
        score += 5.0;
    }

    // Next item lookahead: harmonic match between post_residual and next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward, more so when fit is tight
            let slack = pr - next_item_size;
            score -= 25.0 - (slack as f64).min(20.0);
            if slack == 0 {
                score -= 60.0; // chained perfect fit
            }
        } else {
            // next item won't fit in residual: penalize small leftovers
            score += 10.0;
        }
        // modulo coupling: next_item_size and post_residual share a common divisor class
        let g = gcd(post_residual.max(1), next_item_size);
        if g >= 5 {
            score -= 6.0;
        }
    } else {
        // last item: prefer filling bins fully
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default,
    // but becomes attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        score = 60.0
            + (open_bins_count as f64) * 3.0
            - mean_residual * 0.4;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64) * 0.5;

    // Penalize creating residual far below mean (fragmentation)
    if (post_residual as f64) < mean_residual * 0.4 && post_residual > 0 {
        score += 12.0;
    }

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (>=1) are fine,
    // but residuals in a "trap zone" (small but nonzero, unusable by likely next items)
    // are heavily penalized.
    let min_item = 1.0f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if post_residual > 0 && (post_residual as f64) < min_item + 9.0 {
        // tiny sliver: unusable dead space
        score += 25.0 + 15.0 * progress;
    }

    // Penalize gaps that cannot fit the lookahead item (likely dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits (post_residual close to zero).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity, so add a penalty there).
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * open_bins_count as f64;
    } else {
        // Reward using existing bins more when bin count is high.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mild preference for bins with residuals below average (tighter bins first).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good, but exact / tiny fits
    // deserve a superlinear bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        score -= 200.0 * (1.0 - pr / bin_capacity as f64).powi(8);
        if pr < 10.0 {
            score -= 300.0 * (10.0 - pr) as f64;
        }
    }

    // 2-step lookahead: if the NEXT item fits exactly into the post-residual,
    // this placement chains perfectly — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64).powi(6);
        } else {
            // next item cannot use this bin's leftover: dead-space penalty
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual to the mean residual across open bins:
    // leaving more slack than average is wasteful; tighter-than-average is good.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate handling: only open a fresh bin when the item fits very
    // poorly everywhere else (large item relative to residuals) or few bins fit.
    if bin_residual == bin_capacity {
        let base = 250.0
            + 3.0 * open_bins_count as f64
            + 2.0 * fitting_bins_count as f64;
        // If the item is large relative to capacity, opening a new bin is fine.
        let large_item_bonus = if item_size as f64 > 0.6 * bin_capacity as f64 {
            -120.0
        } else {
            0.0
        };
        score += base + large_item_bonus;
    }

    // Mild stream-progression bias: late in the stream, consolidate harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively.
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64).powf(2.0);

    // Penalize bins that become nearly full but leave a "dead" sliver
    // (post_residual in 1..=8 is often unusable for future items).
    if post_residual > 0 && post_residual <= 8 {
        score += 25.0 * (1.0 - post_residual as f64 / 8.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this bin's remainder: slight penalty for
            // fragmenting when post_residual is small relative to typical items.
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins with larger residuals when the global mean residual
    // is high (reduce spread), prefer tight bins when mean is low.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Late in the stream, consolidate: favor bins with less residual overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 - item_size as f64).abs()
        };
        // Base cost of opening a new bin, reduced late when open bins are many.
        score += 60.0 - 20.0 * progress;
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size > post_residual && next_item_size > 0 {
            score -= 15.0;
        }
        let _ = desperation;
    }

    // Mild preference for fewer open bins early on (avoid bin explosion).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nr = next_item_size as f64;

    // Base: prefer minimal post residual
    let mut score = pr;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - pr / cap; // in (0,1], 1 = perfect fit
    let tight_bonus = (tightness * tightness * tightness) * (20.0 + 60.0 * progress);
    score -= tight_bonus;

    // Penalize post residual scaled by how much of the bin it wastes, nonlinearly.
    let waste_frac = pr / cap;
    score += 15.0 * waste_frac * waste_frac * (1.0 + progress);

    // Lookahead coupling: if the next item fits into post_residual, reward leaving that space.
    if nr > 0.0 && nr <= pr {
        let gap = (pr - nr) / cap;
        score -= 12.0 * (1.0 - gap * gap) * (0.5 + progress);
    } else if nr > 0.0 {
        // Next item won't fit here; mildly penalize leaving large dead space.
        score += 6.0 * waste_frac * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Prefer bins with residual below mean residual (consolidating small leftovers).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (1.0 - progress);

    // Mild penalty for spreading across many bins early on.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it decomposes modulo small integers.
    let r = post_residual;
    let cap = bin_capacity as f64;
    let fill_frac = 1.0 - (r as f64) / cap;

    // Reward near-perfect fills (dead space < 5) strongly.
    if r == 0 {
        score -= 1000.0;
    } else if r <= 5 {
        score -= 200.0;
    } else if r <= 12 {
        score -= 40.0;
    }

    // Harmonic residue classes: residuals divisible by small ints are more reusable
    // by common item sizes (many sizes are multiples of 10, 20, 25, 50).
    if r % 10 == 0 { score -= 15.0; }
    if r % 20 == 0 { score -= 10.0; }
    if r % 25 == 0 { score -= 8.0; }
    if r % 50 == 0 { score -= 6.0; }

    // Penalize awkward residuals in "dead zones" (1..10 and 51..59 style gaps).
    if r > 0 && r < 10 { score += 25.0; }
    if r >= 41 && r <= 49 { score += 8.0; }

    // Lookahead coupling: does this bin's post residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 12.0 + (next_item_size as f64) * 0.15;
        } else {
            // next item won't fit here; penalize proportionally to the shortfall.
            score += ((next_item_size - r) as f64) * 0.10;
        }
        // Harmonic class match: next item and residual share a divisor of 10.
        if next_item_size % 10 == 0 && r % 10 == 0 && next_item_size <= r {
            score -= 10.0;
        }
    } else {
        // Last item: any placement is fine, prefer tightest fill.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early or when all fits are poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 - 30.0 * (1.0 - progress); // cheap to open early, costly later
        if mean_residual < item_size as f64 { score -= 25.0; }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05 * (1.0 - fill_frac);

    // Slight preference for bins below the mean residual (fill emptier-ish bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // Minimum plausible item size is 1; treat gaps below a soft threshold as dead space.
        let dead_threshold = 10.0f64.min(bin_residual as f64);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
        // Perfect fit reward.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Prefer tight fits generally: residual proximity to item size.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        // Post residual cannot host next item -> extra dead-space penalty.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Mean residual coupling: placing into a bin below mean residual concentrates space.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only open a new bin when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        let would_be_dead = post_residual > 0 && (post_residual as f64) < 10.0;
        if would_be_dead {
            score -= 30.0; // opening fresh bin beats creating dead space
        } else {
            score += 20.0; // keep using open bins when fit is reasonable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Aggressive 2-step lookahead: exact match of post_residual to next item is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Exact chain fit gets a strong bonus.
        if diff < 0.5 {
            score -= 40.0;
        } else {
            // Penalize mismatched dead space scaled by how far next item misses.
            score += 0.35 * diff;
        }
        // If next item cannot fit here but could fit a fresh bin, mild penalty.
        if nxt > post {
            score += 6.0;
        }
        // Bonus if post_residual becomes unusable (< smallest plausible item) only when small.
        if post_residual < 10 && post_residual > 0 {
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fit, no lookahead concerns.
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins that are already more filled than average.
    score -= 0.25 * (mean_residual - post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // (large items are hard to place later, a fresh bin is fine).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 20.0 - 18.0 * fill_ratio;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // If many open bins already, discourage more.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer minimizing wasted space overall with a mild quadratic dead-space term.
    if post > 0.0 {
        score += 0.02 * post * post / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins where the next item fits exactly after this one.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; slight penalty for stranding space.
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    score -= (open_bins_count as f64).ln() * tight * 5.0;

    // Global state: if mean residual is high, prefer consolidating into full bins.
    let fill_ratio = 1.0 - (bin_residual as f64) / cap;
    score -= (mean_residual / cap) * fill_ratio * 10.0;

    // Time horizon: early in the stream, be conservative (favor new bins for large items);
    // late in the stream, pack aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = (1.0 - progress) * 8.0;
    if bin_residual == bin_capacity {
        score += new_bin_bias - 2.0;
        // A new bin is attractive if the item is large and next item is also large.
        if item_size as f64 / cap > 0.6 && next_item_size as f64 / cap > 0.6 {
            score -= 12.0;
        }
    }

    // Mild penalty for opening new bins when plenty of fitting bins exist.
    if bin_residual == bin_capacity && fitting_bins_count > 2 {
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post residual, with a super-linear (quartic) penalty
    // so small residuals are heavily favored.
    let mut score = pr + (pr / cap).powi(4) * 30.0;

    // Perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly reward using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 30.0 * progress;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // penalize bins that leave residual just below the next item size (dead space).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (pr - ni) / cap;
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // New-bin candidate handling: opening a new bin is penalized early (waste of
    // capacity) but becomes progressively acceptable late in the stream, or when
    // the current bin would leave a very small, likely unusable residual.
    if bin_residual == bin_capacity {
        let tight_fit = (pr / cap).powi(3) * 40.0;
        let stream_cost = 25.0 * (1.0 - progress);
        let crowd_cost = (open_bins_count as f64).ln() * 2.0;
        score += stream_cost + crowd_cost - tight_fit - 15.0 * progress;
    }

    // Mild coupling with mean residual: bins far from the mean residual that end
    // up tight are slightly preferred (balancing effect).
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by 10 -> "clean" harmonic slot (10/20/.../100).
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post_residual divisible by 25 -> quarter/half capacity slots.
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    // Dead zone: tiny unusable remainders (1..=9) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }
    // Semi-dead zone: 10..=19 hard to pair with items >= 10 unless exact.
    if post_residual >= 10 && post_residual < 20 {
        score += 5.0;
    }

    // Integer-division threshold coupling: post_residual bucket by quarter capacity.
    let quarter = (post / (cap / 4.0)).floor();
    score += quarter * 1.5;

    // Lookahead harmonic matching: can next item exactly fill the post_residual class?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect closure
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 8.0;
            }
            if gap < 10 {
                score += 6.0; // leaves a dead sliver
            }
        } else {
            // next item won't fit here; slight bonus for keeping this bin for it? no: penalize tight bins
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive if current bins are fragmented.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        // open a fresh bin when open bins are already low-residual or crowded
        if mean_frac < 0.25 || open_bins_count == 0 {
            score -= 5.0;
        } else {
            score += mean_frac * 10.0 + open_bins_count as f64;
        }
    }

    // Stream progression: later in stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / cap) * 4.0;

    // Large item: prefer bins with small residual waste naturally handled above;
    // extra penalty for splitting a bin that could hold next big item.
    if item_size >= 50 && post_residual > 0 && post_residual < 20 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residuals that are too small
    // to be usable by future items (items >= 1, but realistically small gaps
    // below the typical minimum item size become dead space).
    let min_item = 1.0f64;
    let usable_threshold = 30.0f64; // gaps below this are rarely reusable
    if (post_residual as f64) < usable_threshold {
        // quadratic dead-space penalty, strongest near zero
        let gap = usable_threshold - post_residual as f64;
        score += 2.0 * gap * gap / usable_threshold;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (post_residual small relative to bin capacity)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * fit_ratio * fit_ratio;

    // Lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 45.0; // chain of perfect fits
        } else if slack < usable_threshold {
            score += 1.5 * (usable_threshold - slack); // next item leaves dead space
        } else {
            score -= 8.0; // next item still leaves usable space
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (post_residual leaves a large dead gap).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if (post_residual as f64) < usable_threshold {
            score += 20.0; // but not if it creates dead space
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
    score -= pressure * (1.0 - fit_ratio);

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if all existing fits are bad.
        // Base cost of a new bin grows with open bins count and mean residual.
        score += 35.0 + 0.5 * open_bins_count as f64;
        if mean_residual > 40.0 {
            score += 15.0; // plenty of slack elsewhere; discourage new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // roomy bin useful for upcoming larger items
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (fill the fullest bins first to close them out).
        let dev = mean_residual - bin_residual as f64;
        score -= 0.3 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            // penalize residual dead space left after the lookahead item
            score += 0.35 * leftover_after_next as f64;
            score -= 8.0; // mild reward for any lookahead fit
        } else {
            // next item cannot use this bin's remainder: penalize dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins with residual near/below mean
    // (avoid leaving many half-empty bins around).
    score += 0.25 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score -= 15.0; // large item: opening a fresh bin is reasonable
        }
    }

    // Early in stream: slightly discourage hoarding many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residuals (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward if next item fits exactly-ish in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 22.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overflow.
            score += 6.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0 + 0.05 * (post_residual as f64);
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Relative-to-mean residual adjustment: prefer bins that are already
    // more filled than average (small residual relative to mean).
    if mean_residual > 0.0 {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when it beats poor fits.
    if bin_residual == bin_capacity {
        // Baseline penalty so new bins are chosen only when open bins score badly.
        score += 30.0 + 0.35 * item_size as f64;
        // Late in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
        // If no open bin fits, this penalty is irrelevant (new bin is forced),
        // but keep it so genuinely good fits elsewhere still win.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits, but with non-linear decay on post_residual.
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, residual waste matters more (less room to fill it).
    score += 18.0 * pr_norm * pr_norm * (0.5 + progress);

    // Penalize bins that cannot also fit the lookahead item smoothly.
    let fits_next = if next_item_size > 0 && next_item_size <= pr { 1.0 } else { 0.0 };
    score -= 6.0 * fits_next * (1.0 - progress);

    // Dead-space avoidance: very small post_residual is great, reward smoothly.
    score -= 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bin bonus (smooth in fitting_bins_count).
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - pr_norm);
    }

    // Mild dispersion penalty: avoid deviating too far from mean residual.
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize lightly early, more late (prefer existing bins as stream progresses).
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // --- Dead-space penalty: residuals in (0,10) are nearly unusable ---
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Harmonic class: multiples of 10 are "clean" residual states
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else {
        // fractional-capacity classes: penalize awkward odd remainders
        score += (post_residual % 10) as f64 * 0.4;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // this bin can also host the next item: reward
            score -= 6.0;
            // extra reward if next item fills it exactly (harmonic pairing)
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else if post_residual > 0 {
            // dead space for the lookahead item
            score += 8.0;
        }
    }

    // --- Last-chance bonus: only bin that fits, avoid opening a new bin wastefully ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // --- Mild bias toward reusing existing bins ---
    if is_new_bin {
        score += 3.0;
        // opening a bin late in the stream is fine; early on prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 4.0;
    }

    // --- Contextual: if mean residual across bins is high, tighten packing ---
    if !is_new_bin && mean_residual > 40.0 {
        score -= 2.0;
    }

    // Perfect fit is always best
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot hold the next item (or any plausible item).
    let usable_threshold = if next_item_size > 0 { next_item_size.max(10) } else { 10 };
    if post_residual > 0 && post_residual < usable_threshold {
        score += 60.0 + (usable_threshold - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward placements that leave room for the lookahead item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: penalize proliferating bins mildly, scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is close to the mean residual (balance-aware).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when the current item is large
        // and open bins would be left with tiny dead gaps anyway.
        let mut new_bin_cost = 45.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Room for a full pair in a fresh bin is valuable.
            new_bin_cost -= 20.0;
        }
        if post_residual == 0 {
            new_bin_cost -= 40.0; // fresh bin with future space is fine
        }
        score = score.max(new_bin_cost) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a perfect two-item fill.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Penalize leftover space that next item cannot use at all.
        if (post_residual as i64) < (next_item_size as i64) {
            score += 0.8 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score -= 40.0;
    }

    // Reward bins whose residual is already below average (consolidating waste).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin mildly, unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * open_bins_count as f64;
    }

    // Late in the stream, tighten up: prefer minimal post_residual more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 12.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Penalize dead space that cannot accommodate the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }
    // Reward residual that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 1.5;
    }

    if is_new_bin {
        // Opening a new bin is generally discouraged when alternatives exist.
        score += 6.0 + progress * 6.0;
        // But if this item fits in no open bin besides (possibly) itself, allow it.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // Late in the stream, consolidating matters more than opening bins.
        if progress > 0.8 {
            score += 4.0;
        }
    } else {
        // Last-chance bin: strongly prefer using it.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // Reward tight relative fit.
        score -= (item_size as f64 / bin_capacity as f64) * 4.0;
        // Prefer bins whose residual is close to the item size (minimal slack).
        score += (bin_residual as f64 - item_size as f64).abs() * 0.04;
        // Slight preference for bins with residuals below the mean (tighter bins first).
        score += (bin_residual as f64 - mean_residual) * 0.02;
        // With many open bins, favor consolidation into already-open bins.
        if open_bins_count > 4 {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr;

    // Smooth polynomial coupling: post_residual interacts with stream progress.
    // Early in the stream, larger residuals are more acceptable (future items can fill them);
    // late in the stream, dead space is penalized more heavily.
    let progress_coupling = norm_pr * norm_pr * (0.5 + progress) * cap;
    score += progress_coupling;

    // Cubic term: strongly punish mid-range wasted space that is neither reusable nor tight
    let cubic = norm_pr.powi(3) * cap * (1.0 - progress);
    score -= cubic * 0.35;

    // Reward bins whose residual closely matches the next item (lookahead chaining)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let match_bonus = -cap * 0.5 * (1.0 - gap / cap).powi(4) * (1.0 - progress * 0.5);
        score += match_bonus;
    } else {
        // Last item: strongly prefer filling existing bins completely
        score -= cap * (1.0 - norm_pr).powi(2) * 0.6;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= cap * 0.45 * (1.0 - progress);
    } else if fitting_bins_count > 1 {
        // With many options, tighten competition: favor smallest post-residual more
        score += norm_pr * cap * 0.15 * (fitting_bins_count as f64).ln().max(1.0);
    }

    // Mean-residual coupling: if this bin is far from the fleet mean, smooth it out
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * cap * 0.1 * progress;

    // New-bin candidate handling: empty bin gets a moderate penalty so it only wins
    // when open bins are genuinely poor fits
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.3 * progress) + pr;
        if fitting_bins_count <= 1 {
            score -= cap * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "friendly"
    // for future small items (multiples of small divisors waste less space).
    let pr = post_residual;
    let mut harmony = 0.0;
    if pr % 10 == 0 { harmony += 6.0; }
    if pr % 5 == 0 { harmony += 2.0; }
    if pr % 25 == 0 { harmony += 3.0; }
    if pr % 50 == 0 { harmony += 4.0; }
    // Small residuals (<10) are dead space unless perfectly zero.
    if pr > 0 && pr < 10 { harmony -= 8.0; }
    score -= harmony;

    // Perfect fit: huge reward.
    if pr == 0 { score -= 40.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 15.0; }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr { score -= 30.0; }
        else if next_item_size <= pr { score -= 5.0; }
        else {
            // Next item won't fit here: penalize leaving a large awkward gap.
            if pr >= next_item_size * 2 / 3 { score += 4.0; }
        }
    }

    // New-bin candidate handling: make the empty bin attractive only when
    // no good fit exists among open bins (poor fit = large post residual
    // relative to capacity) or when many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.45 * bin_capacity as f64;
        if poor_fit || fitting_bins_count == 0 {
            score -= 20.0; // prefer fresh bin over stuffing
        } else {
            score += 25.0; // discourage opening bins when a decent fit exists
        }
    }

    // Late in the stream, tighten packing: penalize wasted space more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += score * 0.15 * progress;

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    // Align with mean residual: prefer bins whose post residual is near mean
    // (keeps future flexibility uniform).
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that can host the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead cannot use this gap: penalize proportionally.
        score += 10.0 * (next_item_size as f64 - post_residual as f64) / next_item_size as f64;
    }

    // Open-bin pressure: when many bins are open, discourage fragmenting space further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.4 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins that are either tight or near-mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative, allow new bin
        } else if post_residual < 10 {
            score += 100.0; // would create immediate dead space vs a fit elsewhere
        } else {
            score += 12.0 + 0.5 * open_bins_count as f64; // mild bias toward reuse
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 40.0 + (post_residual as f64 - next_item_size as f64) * 0.5;
        } else {
            // Dead space that cannot host the next item: penalize.
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        }
    }

    // Relative to mean residual: prefer bins tighter (more filled) than average.
    score += (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists;
    // an empty bin has residual == capacity, so its raw score is high already.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly, more when many bins are open.
        score += 50.0 + (open_bins_count as f64) * 2.0;
        // But if the next item is large and current fits are poor, allow it.
        if next_item_size > 60 && post_residual > 0 {
            score -= 30.0;
        }
    }

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Penalize dead space: post_residual that is too small to ever be useful
    // (smaller than the minimum conceivable item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits into this bin's post_residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 10.0;
        }
        // Chain fit: next item fills post_residual exactly.
        if next_item_size == post_residual {
            score -= 35.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the
    // stream and when good fitting alternatives exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 55.0;
        // Later in the stream, opening new bins is less costly (fewer future items to serve).
        new_bin_penalty *= 1.0 - 0.5 * progress;
        // If many bins can fit, definitely prefer an existing one.
        if fitting_bins_count > 1 {
            new_bin_penalty += 30.0;
        }
        // If the item is huge relative to capacity, a fresh bin is actually attractive.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            new_bin_penalty -= 40.0;
        }
        // If open bins have large mean residual, they should be used instead.
        score += new_bin_penalty - 0.1 * mean_residual.min(100.0);
        // Cap: a new bin's raw score should at least equal post_residual (=capacity).
        score = score.max(bin_capacity as f64);
    }

    // Mild pressure to prefer filling bins with lower residual among equals
    // (waste-minimization across the fleet).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Slight preference for bins that keep residuals "round" (multiples of 10),
    // easing future packing in unknown distributions.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly * cap * 0.01;

    // Reward tight fits, more strongly late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (pr < next_item_size as f64) {
        score += (next_item_size as f64 - pr) * (0.6 + 0.8 * progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (norm_pr + 0.1);

    // Deviation from mean residual: prefer bins near the mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the smallest item (1)
    // are pure waste; residuals below common item sizes (<= 10) are near-dead.
    if post_residual < 10 {
        score += 12.0 + (10 - post_residual) as f64 * 0.8;
    }

    // Harmonic classes: post_residual divisible by common size classes is reusable
    let classes: [u32; 6] = [5, 10, 20, 25, 50, 100];
    let mut harmonic_bonus = 0.0;
    for (k, &c) in classes.iter().enumerate() {
        if post_residual % c == 0 && post_residual > 0 {
            harmonic_bonus += 3.0 + k as f64 * 1.5;
        }
    }
    score -= harmonic_bonus;

    // Perfect fit: exact fill rewards strongly
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        // reward leaving room for the next item; stronger when it fits snugly
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + 6.0 * (1.0 - slack / cap);
        // harmonic match: next item exactly divides remaining space
        if slack == 0.0 {
            score -= 15.0;
        } else if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize creating a bin that strands the lookahead
        score += 4.0 + next_item_size as f64 * 0.05;
    }

    // Integer-division thresholds on post_residual
    let quarter = (bin_capacity / 4) as f64;
    let half = (bin_capacity / 2) as f64;
    if pr > half {
        score -= 3.0; // roomy residual is flexible
    } else if pr > quarter {
        score += 1.0; // mid-range: mildly attractive
    } else if pr > 0.0 {
        score += 2.5; // cramped residual
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or this is a
    // large item early in the stream where spreading load helps.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual / cap < 0.15 && open_bins_count > 0;
        if item_size > 50 && progress < 0.5 {
            score -= 6.0;
        } else if crowded {
            score -= 2.0;
        } else {
            score += 10.0 + open_bins_count as f64 * 0.3;
        }
        // never open a new bin when a perfect fit exists elsewhere
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for fuller bins overall (reduce fragmentation)
    score -= (1.0 - pr / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (min size 1..=10) can use it well.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0 + (25 - post_residual) as f64 * 0.6;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0;

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for next item: mild dead-space penalty.
        score += 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let base = 55.0 + pressure * 6.0;
        // Allow opening when the item is large and few bins fit it.
        let relief = if item_size > bin_capacity / 2 { 25.0 } else { 0.0 };
        score += base - relief;
    }

    // Early stream: be slightly more willing to keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    // Mild alignment with mean residual: avoid bins far from the norm.
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Perfect-fit reward: post_residual near zero.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward when next item matches post_residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - next_fit / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize wasted space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    }

    // Relative to mean residual: bins tighter than average are worth filling.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize leaving dead space that nothing (>=10) could use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: open a new bin only when it's early or existing bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Late in stream: consolidate into existing bins.
    if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
        score += 0.15 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post_residual is small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness * tightness);

    // Lookahead: reward bins that can also host the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Penalize leaving a residual too small for the next item (dead space).
            score += 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(3));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when open bins
    // are quite full or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = fullness + 0.5 * (item_size as f64 / bin_capacity as f64);
        score += 25.0 - 30.0 * pressure - 5.0 * progress;
        // Penalize hoarding many open bins.
        score += 0.4 * open_bins_count as f64;
    } else {
        // Mildly prefer using existing bins when mean residual is high (fragmentation risk).
        if mean_residual > 0.0 {
            score += 2.0 * (1.0 - (bin_residual as f64 / mean_residual).min(2.0) / 2.0);
        }
    }

    // Prefer bins whose residual is close to the item size (exact-fill preference).
    let diff = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual, with non-linear squaring for tightness.
    let mut score = post + 0.35 * (post * post) / cap;

    // Smooth progress coupling: late in the stream, tighten more aggressively.
    let tightness = 1.0 + 1.2 * progress * progress;
    score *= tightness;

    // Reward filling a bin nearly exactly (post_residual near 0) with a smooth dip.
    let fill_ratio = 1.0 - post / cap;
    score -= 8.0 * fill_ratio * fill_ratio * fill_ratio;

    // Last-chance bin: strong smooth bonus to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    } else {
        // Mild penalty when many bins fit (this one is not special).
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Penalize bins whose residual deviates far below the mean residual
    // (i.e., wastefully empty bins) via smooth quadratic coupling.
    let dev = mean_residual - post;
    score += 0.05 * dev * dev / cap;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0);
        let slack = (post - nxt).abs();
        score += 0.4 * fits_next / cap;
        score -= 3.0 * (-slack / (0.15 * cap)).exp(); // smooth reward when next item fits snugly
    }

    // New-bin candidate: penalize smoothly, but relax when existing residuals are tight
    // relative to the item (nothing fits well) or late in the stream.
    if bin_residual == bin_capacity {
        let avg_fit_gap = (mean_residual - item).max(0.0) / cap;
        let escape = (-6.0 * avg_fit_gap).exp(); // ~1 when open bins fit poorly
        score += 10.0 - 8.0 * escape - 2.0 * progress;
        // Slightly discourage hoarding new bins when many are already open.
        score += 0.3 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as fraction of capacity

    // Penalize residuals in "awkward" classes: small but nonzero slivers.
    if post_residual > 0 {
        let class = post_residual % 25; // quarter-capacity harmonic classes
        score += match class {
            0 => -6.0,                    // perfectly aligned residual: reward
            1..=4 => 8.0,                 // tiny sliver: dead space, strong penalty
            5..=9 => 3.0,                 // small awkward zone
            10..=15 => -1.0,              // mid zone, mildly fine
            _ => 0.5,
        };
    } else {
        score -= 12.0; // perfect fill: big reward
    }

    // Integer-division thresholds: residual usable by next item?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here too — reward chained placement, scaled by tightness.
        let tight = 1.0 - (post_residual as f64 / (item_size + next_item_size) as f64);
        score -= 5.0 + 4.0 * tight;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0; // residual too small for lookahead: penalty
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - frac * cap).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Open a new bin when mean residual is small (existing bins nearly full)
        // and many bins are open; otherwise prefer existing bins.
        score = 40.0 + mean_residual * 0.4 + open_bins_count as f64 * 1.5
                - fragmentation * 0.2 - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits anywhere: must open
        }
    }

    // Slight preference for tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host the
    // smallest plausible future item are pure waste -> heavy penalty.
    let min_useful = 12u32;
    if post_residual < min_useful {
        // Perfect fit zone: tiny leftovers are fine (bin is essentially full).
        score -= 40.0;
    } else if post_residual <= 20 {
        // Small dead-space band: unusable for most items, penalize hard.
        score += (25.0 - post_residual as f64) * 3.0;
    } else {
        // Usable residual: mild reward proportional to how much was consumed.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    }

    // Reward near-exact fits (post_residual close to zero or to a
    // plausible next-item size).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0; // perfect chain: next item fills this bin exactly
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Bin can still host the lookahead item: keep it attractive.
        score -= (post_residual - next_item_size) as f64 * 0.2;
    } else if next_item_size > 0 {
        // Lookahead cannot fit here: penalize if we'd strand the bin.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 10.0 + 6.0 * open_bins_count as f64;
        // Exception: if the item is large and current residuals are tight,
        // a fresh bin may be preferable.
        if item_size as f64 > 0.6 * bin_capacity as f64
            && mean_residual < item_size as f64 * 1.2
        {
            score -= 25.0;
        }
    } else {
        // Slight preference for tighter existing bins (best-fit flavor).
        score += (bin_residual as f64 - post_residual as f64) * 0.05;
        // Prefer bins below mean residual (fill emptier-relative bins less).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    // Late in the stream, consolidate: penalize spreading across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core 2-step lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chaining: bin becomes exactly full after next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: leftover slack stays useful.
            score -= 15.0 + (post_residual as f64 - next_item_size as f64).min(20.0);
        } else {
            // Dead space: next item cannot use what's left.
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: only absolute tightness matters.
        score -= 20.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: it is recognizable by bin_residual == bin_capacity.
    // Penalize opening a new bin when open bins exist; allow it only when
    // many bins are open and item is large (poor fits everywhere).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let base_penalty = 35.0;
            let large_item_bonus = if item_size > 50 { 10.0 } else { 0.0 };
            let crowding = (open_bins_count as f64).min(10.0) * 0.5;
            score += base_penalty + large_item_bonus + crowding;
        } else {
            // First bin ever: must be opened.
            score -= 100.0;
        }
    }

    // Slight late-stream tightening: as stream progresses, waste matters more.
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item can fit in the post residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
            // Extra reward for chaining tight fits.
            let chain = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 8.0 * chain;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mildly prefer tighter ones (already via fit_ratio).
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins below mean residual (more room left than average is wasteful to consume
    // unless needed); consuming a below-average-residual bin preserves flexibility.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Time horizon: early in stream, be pickier about waste; late in stream, just fill bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 30.0 + 5.0 * openness.sqrt();
        // But if the item is large relative to capacity, new bin is fine.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If no open bin fits well (high mean residual mismatch), allow new bin.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear decay
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth non-linear coupling with stream progress: tighten packing as stream advances
    score += 8.0 * norm_pr * progress * (1.0 - progress + 0.25);

    // Lookahead: reward residuals that can still host the next item, penalize near-miss dead space
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap) * (1.0 - progress * 0.5);
        } else {
            score += 2.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Mild penalty when bin is far below the mean residual (fragmentation avoidance)
    score += 0.5 * (mean_residual - pr as f64).abs() / cap;

    // New-bin candidate: neutral-ish baseline so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_u = post_residual;
    let class = if post_u == 0 { 0u32 }
        else if post_u <= eighth { 1 }
        else if post_u <= quarter { 2 }
        else if post_u <= quarter * 2 { 3 }
        else if post_u <= quarter * 3 { 4 }
        else { 5 };

    // Reward near-perfect fits heavily.
    match class {
        0 => { score -= 60.0; }
        1 => { score -= 25.0; }
        2 => { score -= 10.0; }
        3 => { score += 5.0; }
        4 => { score += 12.0; }
        _ => {}
    }

    // Modulo arithmetic: leftover divisible by common item sizes is reusable.
    if post_u > 0 {
        let reusable = (post_u % 10 == 0) || (post_u % 20 == 0) || (post_u % 25 == 0) || (post_u % 50 == 0);
        if reusable { score -= 8.0; }
        // Penalize dead space that no plausible item (1..=80) can pair with usefully.
        if post_u > 80 { score += 6.0; }
        if post_u < 10 { score += 3.0; } // tiny sliver is nearly dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_u {
            score -= 45.0;
        } else if next_item_size <= post_u {
            let slack = (post_u - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual: mildly penalize small leftovers.
            score += 2.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.9;
        // If current item is large or fits nothing else, opening is more attractive.
        if fitting_bins_count == 0 { score -= 40.0; }
        if item_size >= bin_capacity / 2 { score -= 15.0; }
        // Late in stream, prefer consolidating.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If mean residual across open bins is large, avoid new bins.
        score += mean_residual * 0.15;
    } else {
        // Slight preference to keep many open bins from proliferating.
        score += open_bins_count as f64 * 0.05;
    }

    // Prefer tighter bins generally (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 20 {
        // Small unusable gaps are heavily penalized, worse the smaller they are.
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual == 0 {
        score -= 40.0; // perfect fit is golden
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // Coupling with mean residual: if this bin's residual is far below mean, it's a good filler.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - bin_res_f) * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap: the gap is truly dead space.
        score += 10.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate handling: fresh bin is attractive when current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by how bad existing fits are.
        score = 45.0 + post_residual as f64;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if item_size > 60 {
            score -= 10.0; // large items start fresh bins comfortably
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable dead space (non-linear: tiny residuals are very bad).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 40.0 * (10.0 - pr);
        }
    }

    // 2-step lookahead: reward if next item exactly fills the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (nxt - pr).abs() < 0.5 {
            score -= 500.0; // chain completion: this bin will be perfectly closed next step
        } else if nxt <= pr {
            // next item fits: reward proportional to how well it fills the remainder
            let fill = nxt / pr;
            score -= 120.0 * fill * fill;
        } else {
            // next item cannot fit into remainder: penalize leaving a gap the lookahead can't use
            let gap = pr - nxt;
            score += 8.0 * gap.min(50.0);
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    // (consolidate waste into few bins), but avoid extreme tightness when
    // many alternatives exist.
    let dev = mean_residual - bin_residual as f64;
    score -= 6.0 * dev;

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: make empty bins attractive only when no open bin
    // offers a good fit. Default new-bin score is post_residual (= capacity), so
    // nudge it up slightly; big exact/lookahead bonuses in existing bins will win.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Mild preference for fewer open bins (bin consolidation).
    score -= 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus proportional to fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Penalize small dead space that is hard to reuse (post_residual in awkward range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot fit here; slight penalty for wasting this residual.
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 10.0 * fill;

    // Global state: if many bins are open with high mean residual, discourage opening/keeping slack.
    if open_bins_count > 1 {
        score += 0.5 * (open_bins_count as f64).ln() * (post_residual as f64 - mean_residual).abs();
    }

    // New-bin candidate: make it unattractive unless it would give a much better residual profile.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
        // But if no existing bin fits well (item nearly fills a fresh bin anyway), neutralize.
        if item_size >= 80 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - (pr / cap);

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let prog_coupling = pr * (0.35 * progress * progress + 0.15 * progress + 0.05);
    score += prog_coupling;

    // Reward tight fits via cubic tightness term
    score -= 18.0 * tightness * tightness * tightness * fit_ratio;

    // Penalize large dead space quadratically, modulated by progress
    let dead = pr / cap;
    score += 30.0 * dead * dead * (1.0 - 0.5 * progress);

    // Last-chance bin bonus (smooth, not piecewise)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 - dead);

    // Lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_err = (pr - nxt) / cap;
        score -= 12.0 * (-4.0 * match_err * match_err).exp();
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin mildly, more early in stream
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items 10..80 historically create residues;
    // residues divisible by 10 are "harmonic" (easy to fill later), odd/small ones are dead space.
    let harmonic = (post_residual % 10 == 0) as f64;
    score -= harmonic * 12.0;

    // Penalize tiny non-harmonic dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainable: strongly favor
            let chain_waste = post_residual - next_item_size;
            score -= 20.0;
            score -= harmonic_class_bonus(chain_waste);
        } else {
            // next item won't chain here; penalize proportional to how badly it misses
            let miss = next_item_size - post_residual;
            score += miss as f64 * 0.8;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bin residuals are large/fragmented and item is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_frag = mean_residual / (bin_capacity as f64);
        // penalize new bin normally; discount when fragmentation is high
        let new_bin_penalty = 30.0 * (1.0 - avg_frag) + 20.0 * progress;
        score += new_bin_penalty;
        // small items into fresh bins are wasteful unless nothing fits well
        if item_size <= bin_capacity / 4 {
            score += 10.0;
        }
        // if many bins fit the item, definitely avoid new bin
        score += fitting_bins_count as f64 * 5.0;
    }

    // Prefer tighter bins (best-fit flavor) with nonlinear scaling
    score += (bin_residual as f64) * 0.05;

    // Mild bonus for matching item size to residual via integer division thresholds
    let ratio_class = (item_size * 4) / bin_capacity; // 0..3 coarse class
    let res_class = (bin_residual * 4) / bin_capacity;
    if ratio_class == res_class {
        score -= 6.0;
    }

    // Open bins pressure: many open bins -> consolidate
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

#[inline]
fn harmonic_class_bonus(chain_waste: u32) -> f64 {
    // waste that is itself harmonic (multiple of 10 or zero) is fine
    if chain_waste == 0 {
        8.0
    } else if chain_waste % 10 == 0 {
        4.0
    } else {
        -(chain_waste as f64) * 0.3
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Penalize "nearly dead" gaps: small residuals that most future items cannot use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 150.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 60.0 * fill_ratio * fill_ratio;
    }

    // If this bin is the only one that can fit the item, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 20.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading into fresh space;
    // favor closing bins. With few open bins, allow opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and mean residual waste.
        score += 40.0 + bin_pressure * 6.0 + mean_residual * 0.4;
        // Opening a new bin is fine early or when existing bins are badly fragmented.
        if open_bins_count == 0 {
            score -= 300.0;
        } else if mean_residual < 15.0 {
            score -= 60.0;
        }
    } else {
        // Existing bin: slight reward for keeping bin count low.
        score -= bin_pressure.min(30.0) as f64 * 0.5;
        // Reward using bins whose residual is above mean (consolidate slack).
        if (bin_residual as f64) > mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: strongly favor bins whose residual is exactly consumed.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // reward heavily; if it fits at all, reward moderately; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Reward closeness of next item to post_residual (chain packing).
            let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 200.0 * (1.0 - gap);
        } else {
            // Next item won't fit here: penalize leaving large awkward gaps.
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    // Leaving less than the mean residual is good (tight packing); more is bad.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize new-bin opening unless existing bins would leave large waste.
    if bin_residual == bin_capacity {
        // New bin baseline: its post_residual is large; add a fixed opening cost
        // so we only open when no open bin gives a tight fit.
        score += 60.0;
        // But if next item is large and current bins are tight, opening is fine:
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 80.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Prefer placing larger items first into tighter bins (waste shaping).
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * (fit_ratio - 0.85);
    }

    // Penalize large dead space quadratically, but less when the bin is nearly full.
    score += 0.05 * (post_residual as f64).powi(2) / 100.0;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving post_residual that can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // Dead space unusable by the next item: mild penalty scaled by stream progress.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 6.0 * (0.3 + 0.7 * progress);
        }
    }

    // Global state: when many bins are open, prefer consolidating into existing ones;
    // when few bins are open, new-bin candidate is more acceptable.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty growing with open bins and mean residual.
        score += 15.0 + 2.0 * open_pressure;
        // But if the item is large relative to mean residual, opening fresh is fine.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward increases with open bins count (consolidation pressure).
        score -= 1.5 * (open_bins_count.min(20) as f64);
    }

    // Time horizon: late in the stream, avoid leaving tiny unusable fragments.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = if bin_residual >= item_size { item_size as f64 / bin_residual.max(1) as f64 } else { 1.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild quadratic penalty on residual (encourage tight fills later matters more).
    let prog2 = progress * progress;
    let coupling = (pr * pr) / (cap * cap) * (0.5 + 2.5 * prog2);
    score += coupling;

    // Reward high fill ratio, weighted increasingly with progress.
    score -= fit_norm * fit_norm * (1.0 + 3.0 * prog2) * 2.0;

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * prog2;
    }

    // Penalize when this bin's residual is far below the mean (wasteful relative use),
    // smoothly scaled.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += dev * dev * 1.5;

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 + 3.0 * fit_norm;
    }

    // Mild penalty on proliferation of open bins, smoothed by progress.
    score += (open_bins_count as f64).ln().max(0.0) * (0.3 + 0.7 * prog2);

    // New-bin candidate: prefer it only when residuals are large and stream is early.
    if bin_residual == bin_capacity {
        score += 1.0 - 2.0 * prog2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals divisible by small
    // moduli are more likely reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }
        if pr % 7 == 0 {
            score -= 4.0;
        }
        if pr % 3 == 0 {
            score -= 2.0;
        }
    }

    // Integer-division class: post_residual in a "usable band" (>= next item)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 && post_residual >= next_item_size {
        // This bin can also host the lookahead item -> strong reward.
        score -= 8.0 + 4.0 * (1.0 - progress);
        // Extra harmonic bonus when post_residual is an exact multiple class of next item
        if post_residual % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead: penalize small unusable leftovers.
        let gap = next_item_size - post_residual;
        if gap <= 9 {
            score += 5.0 + gap as f64;
        }
    }

    // Tight fit reward (harmonic fraction of capacity consumed)
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_fraction * fill_fraction;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins are very full
    // (mean residual small) or many bins already open.
    if bin_residual == bin_capacity {
        score += 6.0;
        if mean_residual < 12.0 {
            score -= 10.0;
        }
        if open_bins_count > 8 {
            score -= 3.0;
        }
    }

    // Prefer denser bins (below-average residual) when multiple fit.
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100,
    // practically anything < next_item_size or < ~10) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver: heavy penalty
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap cannot host the lookahead item: likely dead space.
        score += 0.35 * (post_residual as f64).max(1.0);
    }

    // Reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 18.0 * tightness * tightness;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading further
    // unless the fit is excellent; with few bins, encourage consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.5);
    score += pressure * (2.0 + 3.0 * progress);

    // Prefer bins whose residual is close to the mean (keeps bin states uniform,
    // avoids one bin hoarding all slack while others die).
    score += 0.25 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            // competing open bins exist: make new bin costly unless they'd waste space
            let best_waste = (bin_residual as f64 - item_size as f64).max(0.0);
            25.0 + 0.5 * best_waste
        };
        score += 20.0 + desperation;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps a large upcoming item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Reward near-matches of the next item into the leftover space
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 12.0 / (1.0 + gap as f64);
    }

    // Penalize residuals that are too small to ever be useful again
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins with below-average residual (tighter fill, saves slack)
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Mild preference for fewer open bins when many are already open
    score += 0.15 * open_bins_count as f64;

    // Progress-based pressure: late in the stream, avoid opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress;

    // Penalize the brand-new empty bin candidate moderately,
    // unless it enables a perfect lookahead pair (item + next item exactly filling a bin)
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill achieved by this placement.
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: subtract a bonus proportional to how well the item fills the bin.
    score -= 12.0 * fill * fill;

    // Penalize leaving awkward small residuals (dead space) that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;  // hard-to-fill gap
    }

    // Lookahead: if the next item fits into the post-residual, reward preserving that option.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here anyway; slight penalty if we leave a big useless gap.
            score += 0.02 * (post_residual as f64 - (next_item_size as f64 - 1.0)).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more willing to open/keep bins flexible;
    // late in the stream, prioritize closing out bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fill;

    // Global state coupling: when many bins are open with large mean residual, prefer
    // consolidating into existing bins rather than spreading out.
    if bin_residual < bin_capacity {
        score += 0.03 * (mean_residual - post_residual as f64);
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fill);
    }

    // New-bin candidate: make it slightly unattractive unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * (open_bins_count as f64).ln().max(0.0);
        // If mean residual across open bins is large, opening a new bin is more acceptable.
        score -= 0.04 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Base: waste after placement, shaped non-linearly.
    let mut score = pr.powf(1.5) / cap;

    // Reward tight fits: smooth coupling of post_residual with fill ratio.
    score -= (1.0 - pr / cap) * fit * 30.0;

    // Polynomial interaction: waste penalty grows with stream progress.
    score += 20.0 * (pr / cap).powi(2) * (1.0 + progress);

    // Dead-space avoidance: penalize residuals that no typical item can use,
    // smoothly via product of residual and progress.
    score += 10.0 * (pr / cap) * (pr / cap) * progress * progress;

    // Last-chance bonus: only one fitting bin — strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + fit);
    }

    // Lookahead: if next item fits the post-residual, reward; else penalize smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (nxt / cap) * (1.0 - gap / cap);
        } else {
            score += 4.0 * ((-gap) / cap);
        }
    }

    // Mild penalty for spreading across many bins relative to mean residual.
    score += 0.5 * open_bins_count as f64 * (pr / cap).abs().powi(2);

    // New-bin candidate: empty bin gets a moderate default score so it wins
    // only when open bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        score = 12.0 + 8.0 * progress - 6.0 * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction cell does it land in?
    let q = (post_residual * 4) / bin_capacity; // 0..3 quartile class of leftover
    match q {
        0 => score -= 8.0,             // near-perfect fill, reward strongly
        1 => score += 2.0,             // small dead space, mildly penalize
        2 => score += 0.0,             // mid leftover, neutral
        _ => score -= 3.0,             // large leftover, usable, reward
    }

    // Modulo-10 dead-space class: residuals that are multiples of 10 are
    // "harmonic" with typical item sizes and easy to refill later.
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    } else {
        score += 1.5; // awkward residue class
    }

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact / near-exact match classes
            let diff = post_residual - next_item_size;
            if diff == 0 {
                score -= 10.0;
            } else if diff <= 5 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item won't fit here; leftover becomes dead space
            score += 3.0;
        }
    } else {
        // last item: close bins as tightly as possible
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, tightness matters more
        score += (post_residual as f64) * 0.05 * (fitting_bins_count.min(10) as f64);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when item is large relative to mean residual
        // or stream is early (many items still to come, keep flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        let openness = (open_bins_count as f64).ln_1p();

        // Score for the new bin: lower when opening is attractive.
        score = 55.0
            - 30.0 * item_frac                       // big items justify fresh bins
            - 20.0 * (1.0 - progress)                // early stream: keep options open
            + 25.0 * mean_frac                       // if open bins are roomy, use them
            + 6.0 * openness.min(4.0);               // too many open bins: consolidate

        // If the item leaves a harmonic residual in a fresh bin, that's fine.
        if (bin_capacity - item_size) % 10 == 0 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0; // new bin can also host the next item
        }
    }

    // Small global tightness nudge toward bins below mean residual (fill emptier bins first
    // keeps tight bins for tight items).
    if (bin_residual as f64) > mean_residual + 1.0 {
        score += 1.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item (size 1, but practically anything below ~10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    } else if post_residual < 20 {
        score += 15.0; // risky small gap
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward exact fit for the lookahead item (chain packing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that neither the next item nor anything small can use
    if next_item_size > post_residual && post_residual > 0 && post_residual < 30 {
        score += 10.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins and avoid opening new ones.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; must beat only bad fits.
        score += 20.0 + pressure;
        // Slightly cheaper to open a new bin early in the stream.
        score -= (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
    } else {
        // Prefer bins with tighter residuals (best-fit flavor) but avoid
        // bins far below the mean residual (they're the fragmented ones).
        if (bin_residual as f64) < mean_residual {
            score += 3.0;
        } else {
            score -= 2.0;
        }
        // Reward using a bin whose residual is close to the item size.
        let tightness = (bin_residual as f64 - item_size as f64);
        score += tightness * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: residual after placement exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item almost fills the leftover.
    else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (40.0 / (1.0 + gap)).min(40.0);
        // Penalize leaving a residual that is too small for the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score -= (mean_residual - pr).max(0.0) * 0.4;
        score += (pr - mean_residual).max(0.0) * 0.2;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Avoid opening new bins early in the stream when open bins can fit.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
    }

    // Prefer fuller bins (smaller post residual) with a nonlinear boost.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Slight bonus for bins with residuals near common small item sizes.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward exact/near-exact placements.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 30.0 / (post_residual as f64).sqrt();
    }

    // Lookahead: penalize leaving a residual that is awkwardly close to the
    // next item (dead space the next item almost fits into).
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            // next item fits: small gap is great (chains well)
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item doesn't fit: penalize residuals just below next size
            let miss = -gap;
            if miss <= 20.0 {
                score += 6.0 * (1.0 - miss / 20.0);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or
    // residuals are fragmented. Penalize opening bins when mean residual
    // could still absorb items well.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 + fragmentation * 0.5 - poor_fits
            - 10.0 * (step_index as f64 / (total_items as f64).max(1.0));
    }

    // Mild preference for using emptier bins when many bins are open,
    // to consolidate load and allow fuller bins to close out.
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mildly penalize large residuals (keep bins flexible).
    // Later (progress ~ 1): reward tight fits more aggressively (dead space is costly).
    let tightness = pr / cap; // 0 = perfect fit, 1 = empty bin
    let progress_weight = 0.5 + 2.5 * progress * progress; // smooth ramp
    score += progress_weight * tightness * tightness * cap;

    // Smooth quadratic penalty on residual relative to mean residual of open bins:
    // bins with residual far above mean are penalized (avoid scattering space).
    let dev = pr - mean_residual;
    score += 0.35 * (dev / cap) * (dev / cap) * cap * (1.0 + progress);

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // with a smooth polynomial falloff as slack shrinks toward zero.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Smooth penalty proportional to how far the next item overshoots.
            let miss = (nx - pr) / cap;
            score += 3.0 * miss * miss * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // Smoothly dampen preference among many fitting bins by residual density.
        score += 0.15 * (fitting_bins_count as f64).ln() * tightness * cap;
    }

    // Mild congestion term: when many bins are open, prefer tighter placements.
    let congestion = (open_bins_count as f64).ln_1p();
    score += congestion * tightness * tightness * 2.0;

    // New-bin candidate handling: empty bin gets a smooth adaptive penalty so it
    // only wins when open bins would waste too much space.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let late = 1.0 + 2.0 * progress;
        score += 4.0 * late - 3.0 * pressure * pressure * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Harmonic class logic: classify post_residual into capacity fraction classes.
    let post_class = post_residual / (bin_capacity / 4); // 0..3 classes (0,1-24,25-49,50-74,75-99)
    let class_bonus = match post_class {
        0 => 8.0,   // near-perfect fit, dead space < 25
        1 => 3.0,
        2 => -1.0,
        _ => -4.0,  // large leftover, low priority unless bin is fresh
    };
    score += class_bonus;

    // Integer division threshold: post_residual divisible structure
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.5; // clean modular leftover may host future round items
    }
    if post_residual == 0 {
        score -= 20.0; // exact fill: always excellent
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // harmonic match: next item lands in same quarter class
        let next_class = next_item_size / (bin_capacity / 4);
        if next_class == post_class {
            score -= 2.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space risk if next item cannot use leftover
        score += 3.0 * (post_residual as f64 / 25.0);
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive late in stream or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = bin_capacity as f64 - 5.0;
        if progress > 0.7 { score -= 10.0 * progress; }
        if mean_residual < 15.0 { score -= 8.0; }
        if fragmentation < 5.0 { score -= 2.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 4.0; // big next item benefits from fresh bin
        }
        if post_residual == 0 { score -= 20.0; }
    }

    // Mild penalty for spreading across too many bins early.
    if open_bins_count as f64 > 4.0 + step_index as f64 * 0.1 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to fit even the smallest
    // plausible future item. Penalize non-zero small gaps super-linearly.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 6.0;
    }
    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post gap,
    // reward this placement; if the gap is just barely too small, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 4 {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize opening new bins implicitly via residual bias).
    let ob = open_bins_count as f64;
    score += ob * 0.35;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose post residual stays near the
    // open-bin mean (predictable packing), penalize outliers creating scraps.
    let mr = mean_residual;
    let dev = (post_residual as f64 - mr).abs();
    score += dev * 0.15;

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when existing fits are bad (large post residual or dead gap).
    if bin_residual == bin_capacity {
        // Base mild attractiveness so it competes with poor fits.
        score = (bin_capacity as f64) * 0.5;
        // Under bin pressure or with a poor alternative, prefer a fresh bin.
        if post_residual >= 0 {
            score -= ob * 0.2;
        }
        // If next item is large, a fresh bin keeps flexibility.
        if next_item_size >= 60 {
            score -= 8.0;
        }
        // Late in the stream, avoid spreading out.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 5.0;
    }

    // Slight stream-progress term: tighten packing as stream advances.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward perfect match: post-residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0 + 10.0 * (1.0 - progress);
    }

    // Reward near-perfect matches (small gap the next item could still fill).
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 20.0 * (1.0 - gap / 10.0);
        } else {
            // Penalize leftover larger than next item but too small for typical items.
            if post_residual < 20 {
                score += 15.0;
            }
        }
    }

    // Penalize dead space: post_residual smaller than next item => next item can't go here.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins whose residual is below mean (tight packing), relative to mean_residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive when the item is large relative to capacity
    // or when open bins are mostly full (mean residual low).
    if bin_residual == bin_capacity {
        let mean_bonus = if mean_residual < item_size as f64 { 20.0 } else { 0.0 };
        score = 100.0 - mean_bonus - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // big next item: fresh bin useful
        }
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild penalty for wasting a large bin on a tiny item when many bins are open.
    if item_size <= 20 && open_bins_count > 5 && bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer tight fits via non-linear post-residual penalty
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * t) + norm_pr * t * t;
    score += 40.0 * poly;

    // Reward filling a bin more completely as stream progresses
    score -= 25.0 * fit * (1.0 - t) * (1.0 + norm_pr);

    // Lookahead: penalize residual that fails to hold next item (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 18.0 * gap * gap * (1.0 - t);
        // Reward residual that exactly accommodates next item
        let match_term = 1.0 - (nxt - pr).abs() / cap;
        if match_term > 0.0 {
            score -= 12.0 * match_term * match_term;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + fit);
    }

    // Penalize leaving mean residual far from this bin's residual (imbalance)
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: keep neutral baseline, slightly penalized vs good fits
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 20.0 * (1.0 - fit) - 15.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual), scaled by capacity fraction.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * tightness * tightness;

    // Harmonic class of the post residual: residuals that are "nice" fractions
    // of capacity (0, 25, 50, 75) or multiples of common item classes are
    // more likely to be filled by future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        let class = pr % 10;
        // Dead space penalties: residuals like 1..9 are hard to fill (items >= 1
        // but small items are rare in most streams); penalize non-decade junk.
        if class != 0 {
            score += 8.0 * (10 - class) as f64;
        }
        // Modulo classes aligned with common item sizes (10, 20, 25, 50):
        if pr % 25 == 0 { score -= 12.0; }
        if pr % 50 == 0 { score -= 10.0; }
        if pr % 20 == 0 { score -= 5.0; }
        // Integer-division thresholds: large leftover chunks are reusable.
        let chunk = pr / 25; // 0..4
        score -= 6.0 * chunk as f64;
        // Very small unusable residue (< 10): heavy penalty unless zero.
        if pr < 10 {
            score += 30.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot fit here: mild penalty proportional to overshoot
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the
    // stream and when good fitting bins exist. Recognized by full residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score += 35.0 + 25.0 * progress;
        // Opening a bin makes sense if the item is huge relative to capacity.
        score -= (item_size as f64 / cap) * 30.0;
        // If many bins are open with large mean residual, prefer reusing them.
        score += 0.3 * mean_residual;
        let _ = waste;
    }

    // Prefer denser packing across fleet: bins with below-mean residual are
    // good targets (fill the emptiest-but-fitting bins first).
    score -= 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    score += 0.05 * open_bins_count as f64;

    // Small tie-break noise-free deterministic jitter via step parity.
    if step_index % 2 == 0 { score -= 0.01; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest possible
    // item (size 1..) are effectively dead space; penalize harshly, especially
    // the classic "unusable gap" band (< 10 by legacy range, but sizes go to 1).
    let dead_threshold: f64 = 6.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward residuals that can still host the lookahead item (chain-fit bonus).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Lookahead cannot fit here: penalize proportionally to how close
            // the gap is to being useful (near-miss dead space).
            score += 6.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * tightness;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins to avoid bin proliferation.
    score += 1.5 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: bins with residual below mean are "denser";
    // filling them further is good.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: a fresh bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; slightly reduced late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 15.0 * progress;
        // If the item nearly fills a fresh bin, opening is attractive.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= 60.0 / (1.0 + diff);
        // Perfect 2-step pairing: residual consumed exactly.
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // If next item cannot fit anywhere else, prefer leaving a compatible gap.
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize dead space relative to mean residual (fragmentation control).
    let frag = post_residual as f64 - mean_residual;
    if frag > 0.0 {
        score += frag * 0.35;
    } else {
        score -= 0.15 * frag.abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight preference for tight fits overall.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 4.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = if pressure > 0.0 { 5.0 } else { post_residual as f64 + 55.0 };
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 30.0;
        }
    }

    // Late-stream bias: consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize leaving dead space too small for the smallest possible item (1..100 range).
    if post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: reward if next item fits the post residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0;
            // If next item fits bin_residual but not post_residual, placing here wastes room.
            if bin_residual >= next_item_size {
                score += 3.0;
            }
        }
    } else {
        // Last item: minimize leftover count, prefer fullest bins.
        score -= 8.0 * tightness;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: with many open bins, encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * crowd * (1.0 - tightness);

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already well-used; keep filling it.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 3.0 * (mean_residual - bin_res_f) / bin_capacity as f64;
    } else {
        score += 2.0 * (bin_res_f - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate: penalize opening a fresh bin unless no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 20.0 * (1.0 - progress);
        // Soften the penalty when mean residual is low (open bins are nearly full)
        // or when few bins can fit the item.
        let soften = (mean_residual / bin_capacity as f64).min(1.0);
        score += base_penalty * (1.0 - 0.5 * soften);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Late-stream conservatism: as the stream ends, avoid opening bins that
    // will carry large unusable residual.
    if progress > 0.8 && post_residual > 30 {
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), non-linearly penalized
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late, demand tight packing
    let slack_penalty = post / cap;
    score += 25.0 * slack_penalty * slack_penalty * (0.3 + 1.7 * progress);

    // Reward bins whose residual is close to the item (good fit quality)
    let fit_quality = (bin_residual as f64 - item_size as f64) / cap;
    score -= 10.0 * (1.0 - fit_quality) * (1.0 - fit_quality);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Compare against mean residual: placing into a bin far below mean residual
    // wastes the tightest space; encourage balancing
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if nd <= post {
            let exactness = 1.0 - (post - nd) / cap;
            score -= 12.0 * exactness * exactness;
        } else {
            // next item won't fit here; slight penalty for leaving large gap
            score += 2.0 * slack_penalty;
        }
    }

    // New-bin candidate: neutral-ish baseline; make it attractive only when
    // no open bin offers a decent fit (post_residual large relative to capacity)
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) + 8.0 * slack_penalty;
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common item sizes
    // (multiples of 10 and small remainders) are more reusable.
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    // Penalize awkward residues (not multiples of 10): dead space tends to accumulate.
    score += residue_class * 0.8;

    // Reward leaving space that exactly matches a harmonic size bucket.
    if pr == 0 {
        score -= 30.0; // perfect fit is ideal
    } else if pr <= 10 {
        score -= 12.0;
    } else if pr % 20 == 0 {
        score -= 8.0;
    } else if pr % 25 == 0 {
        score -= 5.0;
    }

    // Integer-division threshold on post_residual: space that can hold the next item is valuable.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // This bin remains usable for the next item: reward.
            score -= 6.0;
            // Extra reward if next item fits leaving another harmonically clean residual.
            let next_pr = pr - next_item_size;
            if next_pr % 10 == 0 {
                score -= 4.0;
            }
            // Coupling: if next item fits with small slack, this is a great chain.
            if next_item_size >= pr * 3 / 4 {
                score -= 5.0;
            }
        } else {
            // Post residual cannot fit next item: penalize proportionally to waste.
            score += (next_item_size - pr) as f64 * 0.3;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and mean residual.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 45.0;
        // Early in the stream, opening bins is cheaper (build a portfolio of residuals).
        open_cost -= (1.0 - progress) * 10.0;
        // If mean residual is large and could hold the item, discourage a new bin.
        if mean_residual >= item_size as f64 {
            open_cost += (mean_residual - item_size as f64) * 0.5;
        }
        // If next item is large, an empty bin is useful.
        if next_item_size >= 50 {
            open_cost -= 8.0;
        }
        score += open_cost;
    } else {
        // Slight bonus for using existing bins (keeps open_bins_count low).
        score -= 2.0;
        // Prefer bins whose residual is close to the item (tight fit) via harmonic ratio.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 10.0;
    }

    // Fraction-of-capacity harmonic classes: reward bins whose residual is a clean
    // fraction of capacity (75, 50, 25) after placement.
    if pr == bin_capacity * 3 / 4 || pr == bin_capacity / 2 || pr == bin_capacity / 4 {
        score -= 6.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are still usable in this interface, but very small residuals relative to
    // typical items are hard to fill. Penalize tiny unusable gaps super-linearly.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 3.0; // dead-space quadratic penalty
    }

    // Reward near-perfect fits.
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Reward filling large fractions of the bin (tight packing).
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones; opening new bins is cheaper when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (creates a perfect slot for the upcoming item).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that neither wastes nor helps (mismatched lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by
    // how poor the existing fits are (mean residual high => existing bins bad).
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.3 - pressure * 2.0;
        // If this is the only option, new bin must look attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: nearly-zero post residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post residual exactly/nearly fits the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // chain: this bin will be perfectly filled next step
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving medium dead space
            let dead = post_residual as f64;
            if dead > 20.0 && dead < 60.0 {
                score += 15.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins get filled first).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if the item is large and mean residual is small, new bin is reasonable
        if item_size as f64 > 0.7 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 40.0;
        }
    }

    // Slight preference to fill bins early in the stream (keep flexibility later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, use it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward residual that can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // Penalize opening new bins when open bins are reasonably full or it's a good fit.
        score += 55.0 + 30.0 * pressure - 25.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if fit_ratio > 0.9 {
            score += 80.0; // opening fresh bin for a huge item is fine
        }
    } else {
        // Mild preference for fuller bins to consolidate.
        score += 0.25 * (bin_residual as f64 - mean_residual);
    }

    // Early stream: be slightly more liberal with new bins (spread items), late: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), smoothed polynomial
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in stream, penalize residual waste more strongly
    score += 40.0 * norm_pr * progress * (1.0 - progress + 0.25);

    // Exact-fit reward (smooth, non-piecewise)
    let fit_quality = 1.0 - norm_pr;
    score -= 30.0 * fit_quality * fit_quality * fit_quality;

    // Mean-residual coupling: if this bin's residual deviates from mean, adjust
    let mean_norm = mean_residual / cap;
    let deviation = norm_pr - mean_norm;
    score += 15.0 * deviation * deviation;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: penalize leaving residual that barely fails next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = pr - ni;
        if gap < 0.0 && gap > -20.0 {
            score += 10.0 * (1.0 + gap.abs() / 20.0); // near-miss wasted space
        } else if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap).min(1.0)); // next item fits well
        }
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score = pr + 60.0 - 0.4 * item_size as f64 + 10.0 * progress;
    }

    // Mild open-bin count pressure: many open bins -> prefer consolidating
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 as "harmonics".
    // Residuals that are small-but-nonzero are dead space; reward exact-zero fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let r = (post_residual % 10) as f64;
        // penalize awkward residues (1..9) proportionally, less so for 0 mod 5
        if post_residual % 5 == 0 {
            score += r * 0.3;
        } else {
            score += r * 0.9 + 2.0;
        }
        // Integer-division thresholds: residual classes by decade
        let decade = post_residual / 10;
        score += match decade {
            0 => 8.0,          // <10: nearly unusable
            1 => 3.0,          // 10-19: fits small items only
            2..=4 => 0.0,      // 20-49: usable
            _ => -2.0,         // >=50: roomy bin, prefer filling it
        };
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item's residue class pairs well
            score -= 10.0;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0; // exact divisor: future perfect fill
            }
        } else {
            // next item cannot use this residual; penalize by overshoot class
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / 10.0).min(6.0) * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: give it a neutral-ish baseline so it's chosen only
    // when open bins score poorly (large post_residual or bad residue classes).
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * open_bins_count as f64;
        // late in stream, prefer closing out bins rather than spawning
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer bins below mean residual (tighter, closer to closing).
    score += (mean_residual - post_residual as f64) * 0.2;

    // Capacity fraction coupling: item/binary fraction harmonics
    let frac = item_size as f64 / cap;
    if (frac * 10.0).round() as i64 % 2 == 0 {
        score -= 1.0; // even-tenths items pack predictably
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: small unusable gaps (1..10) are heavily penalized,
    // since nothing can ever fill them.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post) / 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the leftover gap -> dead space risk
        score += 8.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with below-mean residual (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when open bins waste space.
        score = cap * 0.9 + 5.0 * open_bins_count as f64;
        // If no open bin can fit, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If the next item is large, keep current bins for it.
        if next_item_size > 50 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tight fit reward (small post_residual is good)
    score = post_residual as f64;

    // 2-step lookahead: reward bins where the NEXT item also fits the leftover
    let pr = post_residual as f64;
    let nx = next_item_size as f64;
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chainable bin: leftover still usable by next item -> strong reward
            score -= 6.0 + 0.10 * nx;
            // extra reward for near-perfect chaining (leftover just barely fits next)
            let slack = pr - nx;
            score -= 4.0 / (1.0 + slack);
        } else {
            // leftover too small for next item: penalize dead space, worse when close to being usable
            let miss = nx - pr;
            score += 3.0 + 0.08 * miss;
            // tiny leftovers (<10) are near-dead space
            if post_residual < 10 {
                score += 2.0;
            }
        }
    } else {
        // last item: just minimize leftover
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious; using them is cheap
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        score += 2.0 * (rel - 1.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer the tightest (already handled by base), slight spread penalty
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless current fits are bad.
    if bin_residual == bin_capacity {
        // neutral-ish default; adjusted by whether any decent fit exists
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0; // fresh bin chains well
        }
        // penalize opening new bins when good fits exist (fitting_bins_count > 1 means open bins fit)
        if fitting_bins_count >= 1 {
            score += 5.0;
        }
        // early stream: opening bins is fine (build inventory)
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 3.0;
        }
    }

    // Prefer filling many open bins when bin count is large (reduce fragmentation)
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 0.3 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio through the stream
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins that end with small residuals,
    // with a non-linear (squared) penalty on wasted space.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Reward near-perfect fits (residual <= 5) with a subtraction bonus.
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 4.0;
    }

    // Last-chance bin: if this is the ONLY bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item can still fit in the post residual,
    // reward this placement (keeps bins usable for the future).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving dead space.
        score += 0.04 * (next_item_size - post_residual) as f64;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean — a bin with residual close to item_size is a good fit.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.25 * fit_gap;

    // Open-bin pressure: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 0.03 * open_bins_count as f64 * mean_residual.min(bin_capacity as f64);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // early in the stream or when the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fits = fitting_bins_count <= 2;
        if t < 0.15 || (large_item && poor_fits) {
            score -= 8.0;
        } else {
            score += 10.0 + 5.0 * t;
        }
    }

    // Late-stream conservatism: as the stream ends, avoid leaving many
    // half-empty bins; prefer filling bins with larger residuals.
    score += t * 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight-fit reward: smooth quadratic coupling of post_residual with itself,
    // normalized by capacity so small leftovers are strongly favored.
    score += (post / cap) * (post / cap) * 40.0;

    // Perfect fit bonus (smooth exponential rather than hard threshold).
    if post_residual == 0 {
        score -= 25.0;
    } else {
        score -= 12.0 * (-(post / cap) * 10.0).exp();
    }

    // Lookahead coupling: reward leaving residual that can host the next item,
    // penalize residual that is too small for it (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0 * (1.0 - post / nxt);
        }
        // Smooth interaction: leftover that fits next item exactly is great.
        let gap = (post - nxt).abs();
        score += 4.0 * (gap / cap) * (gap / cap);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }
    // Crowding penalty: many competing fitting bins -> mild penalty to spread usage.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate handling: an empty bin has post_residual == cap.
    // Penalize opening a new bin mildly, more so early in the stream, but
    // relax the penalty late when open bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 14.0 * (1.0 - progress) + 6.0 * (1.0 - fragmentation) + openness;
    } else {
        // Favor bins whose residual is below the mean (already committed bins).
        score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).clamp(-1.0, 1.0);
    }

    // Stream-progress coupling: as the stream advances, prefer filling existing
    // bins ever more aggressively (non-linear in progress).
    score -= 10.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible into fine
    // "usable" classes vs coarse dead-space classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Reward tight fits strongly (near-zero post residual).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Modulo arithmetic on post_residual: residuals that are "harmonically
    // aligned" with common item sizes (multiples of 10/25/50) are more
    // likely to be filled by later items -> reward them.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 {
        score -= 6.0;
    }
    // Penalize awkward residues (odd, prime-ish dead zones).
    if post_residual % 10 != 0 && post_residual < 30 {
        score += 6.0; // small awkward remainder unlikely to be reused
    }

    // Non-linear penalty on wasted fraction of capacity.
    score += (frac * frac) * 30.0;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is excellent.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual quality depends on what remains after
            let second_residual = post_residual - next_item_size;
            score -= 15.0 - (second_residual as f64) * 0.15;
        } else {
            // next item cannot use this residual at all
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current fit is bad or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins.
        score += 25.0 + (open_bins_count as f64) * 0.5;
        // But if the item is large, a fresh bin gives a clean layout.
        if item_size >= 50 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    // Mean residual context: when open bins are already slack, prefer
    // consolidating into bins with below-average residual.
    if bin_residual < bin_capacity {
        let diff = mean_residual - (bin_residual as f64);
        score += diff * 0.3; // bins looser than average get penalized
    }

    // Early in the stream, be slightly more willing to open bins to build
    // a diverse pool; late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to the current item size.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 15.0 * tightness;

    // Penalize bins whose residual becomes much larger than typical residuals (wasteful).
    if post_residual as f64 > mean_residual + 20.0 {
        score += (post_residual as f64 - mean_residual - 20.0) * 0.5;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.15 + 0.35 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the remaining gap: mild penalty proportional to gap size.
        score += post_residual as f64 * 0.1;
    }

    // New-bin candidate baseline: neutral-ish score so it's chosen only when
    // all open bins score badly (poor fits / large dead space).
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score = 0.0; // no alternative: opening a new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Slight bonus for a fresh bin when the next item is large.
            score -= next_item_size as f64 * 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)) - 20.0 * (diff == 0.0) as f64;
        // Penalize leaving residuals slightly larger than next item (dead space trap)
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit only
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0;
        // Allow opening a new bin late in stream if fit leaves > 30 dead space
        if post_residual as f64 > 30.0 && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Waste penalty: non-linear squashing of tiny residuals (good) vs large ones
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 10.0;

    // Slight preference for consolidating fewer bins
    score += 0.05 * open_bins_count as f64;

    score
}
